def sum_col_is_nonzero(value: float, eps: float = TREE_SUM_EPSILON) -> bool:
    return abs(float(value)) > eps


def format_float(v: float) -> str:
    return f"{float(v):.2f}"


def treeview_expand_all(tree: ttk.Treeview) -> None:
    def _expand(iid: str) -> None:
        tree.item(iid, open=True)
        for child in tree.get_children(iid):
            _expand(child)

    for iid in tree.get_children(""):
        _expand(iid)


def treeview_collapse_all(tree: ttk.Treeview) -> None:
    def _collapse(iid: str) -> None:
        for child in tree.get_children(iid):
            _collapse(child)
        tree.item(iid, open=False)

    for iid in tree.get_children(""):
        _collapse(iid)


def treeview_collapse_focused(tree: ttk.Treeview) -> None:
    """Skrči izbrano/pozicionirano vozlišče in vse podrejenje."""
    iid = tree.focus() or (tree.selection()[0] if tree.selection() else "")
    if not iid:
        return

    def _collapse_subtree(node: str) -> None:
        for child in tree.get_children(node):
            _collapse_subtree(child)
        tree.item(node, open=False)

    _collapse_subtree(iid)


def treeview_expand_focused(tree: ttk.Treeview) -> None:
    """Raztegni izbrano/pozicionirano vozlišče in vse podrejenje."""
    iid = tree.focus() or (tree.selection()[0] if tree.selection() else "")
    if not iid:
        return

    def _expand_subtree(node: str) -> None:
        tree.item(node, open=True)
        for child in tree.get_children(node):
            _expand_subtree(child)

    _expand_subtree(iid)


def _treeview_item_path(tree: ttk.Treeview, iid: str) -> Tuple[str, ...]:
    parts: List[str] = []
    while iid:
        parts.append(str(tree.item(iid, "text") or ""))
        iid = tree.parent(iid)
    return tuple(reversed(parts))


def treeview_collect_open_paths(tree: ttk.Treeview) -> set:
    open_paths: set = set()

    def _walk(iid: str) -> None:
        if tree.item(iid, "open"):
            open_paths.add(_treeview_item_path(tree, iid))
        for child in tree.get_children(iid):
            _walk(child)

    for root in tree.get_children(""):
        _walk(root)
    return open_paths


def treeview_restore_open_paths(tree: ttk.Treeview, open_paths: set) -> None:
    def _walk(iid: str) -> None:
        if _treeview_item_path(tree, iid) in open_paths:
            tree.item(iid, open=True)
        for child in tree.get_children(iid):
            _walk(child)

    for root in tree.get_children(""):
        _walk(root)


def _compare_tree_razlika_from_values(values: Sequence[str]) -> Optional[float]:
    if len(values) < 7:
        return None
    raw = (values[6] or "").strip()
    if not raw:
        return None
    return parse_amount(raw)


def compare_tree_prune_filtered_nodes(tree: ttk.Treeview, filter_tol: Optional[float]) -> None:
    """Odstrani listne in prazne vmesne vozle brez |Razlika| > filter_tol."""
    if filter_tol is None:
        return

    def _node_visible(iid: str) -> bool:
        vals = tree.item(iid, "values")
        razlika = _compare_tree_razlika_from_values(vals)
        if razlika is not None and abs(razlika) > filter_tol:
            return True
        for child in tree.get_children(iid):
            if _node_visible(child):
                return True
        return False

    changed = True
    while changed:
        changed = False
        for iid in list(_treeview_all_iids(tree)):
            if not tree.exists(iid):
                continue
            if _node_visible(iid):
                continue
            tree.delete(iid)
            changed = True


def _treeview_all_iids(tree: ttk.Treeview) -> List[str]:
    out: List[str] = []

    def _walk(iid: str) -> None:
        out.append(iid)
        for child in tree.get_children(iid):
            _walk(child)

    for root in tree.get_children(""):
        _walk(root)
    return out


def _compare_tree_selected_month_ym(tree: ttk.Treeview) -> Optional[Tuple[str, str]]:
    """Izbran mesec (yyyy, mm) iz drevesa primerjave — focus ali selection."""
    iid = tree.focus() or (tree.selection()[0] if tree.selection() else "")
    if not iid:
        return None
    cur: str = iid
    while cur:
        vals = tree.item(cur, "values")
        if len(vals) >= 2:
            yyyy = str(vals[0] or "").strip()
            mm = str(vals[1] or "").strip()
            if re.fullmatch(r"\d{4}", yyyy) and re.fullmatch(r"\d{1,2}", mm):
                return yyyy, f"{int(mm):02d}"
        parent = tree.parent(cur)
        if not parent:
            break
        cur = parent
    return None


def _compare_export_month_matches(
    month_filter: Optional[Tuple[str, str]],
    yyyy: str,
    mm: str,
) -> bool:
    if month_filter is None:
        return True
    fy, fm = month_filter
    return yyyy == fy and f"{int(mm):02d}" == fm


def _compare_display_razlika(amount_a: float, amount_b: float) -> float:
    """Vrednost stolpca Razlika (B−A), kot v drevesu."""
    return amount_b - amount_a


def _compare_razlika_column_visible(
    amount_a: float,
    amount_b: float,
    filter_tol: Optional[float],
) -> bool:
    """True, če je |Razlika| > filter_tol (npr. >0,05 ali <-0,05)."""
    if filter_tol is None:
        return True
    return abs(_compare_display_razlika(amount_a, amount_b)) > filter_tol


