def _compare_day_neujemajoci_visible(
    day_sa: Dict[str, float],
    day_sb: Dict[str, float],
    detail_col_names: Sequence[str],
    *,
    filter_tol: Optional[float],
    search_pattern: str,
    summary_cols: Sequence[str],
    day_osn_a: float,
    day_osn_b: float,
    dan_display: str,
    osn_col: str,
) -> bool:
    """Ali dan sme biti v drevesu Neujemajoči dnevi (filter Razlika / iskanje)."""
    has_search = _compare_has_active_search(search_pattern)
    if filter_tol is not None:
        return _compare_razlika_column_visible(day_osn_a, day_osn_b, filter_tol)
    if has_search:
        if _compare_search_matches(
            search_pattern,
            row_text=dan_display,
            stolpec=osn_col,
            amount_a=day_osn_a,
            amount_b=day_osn_b,
        ):
            return True
        return _compare_day_has_visible_detail_rows(
            day_sa,
            day_sb,
            detail_col_names,
            filter_tol=None,
            search_pattern=search_pattern,
            summary_cols=summary_cols,
        )
    return True


