def _compare_search_matches(
    pattern: str,
    *,
    row_text: str = "",
    stolpec: str = "",
    amount_a: float = 0.0,
    amount_b: float = 0.0,
) -> bool:
    """Iskanje po dokumentu (#0), stolpcu, KIR, Davčna blagajna (niz ali wildcard * ?)."""
    pat = (pattern or "").strip()
    if not pat:
        return True
    diff = amount_b - amount_a
    parts = [
        row_text,
        stolpec,
        format_float(amount_a),
        format_float(amount_b),
        format_float(diff),
        f"{amount_a}",
        f"{amount_b}",
        f"{diff}",
    ]
    pat_cf = pat.casefold()
    use_glob = any(ch in pat for ch in "*?[]")
    for raw in parts:
        if not raw:
            continue
        text = raw.casefold()
        if use_glob:
            if fnmatch.fnmatch(text, pat_cf):
                return True
        elif pat_cf in text:
            return True
    return False


def _neobdavcljive_amount_from_sums(sums: Dict[str, float]) -> float:
    """Znesek neobdavčljivih iz CSV (oba možna stolpca)."""
    for col in ("Vrednost neobdavčljivih dobav", "Neobdavčljive dobave"):
        v = float(sums.get(col, 0.0))
        if abs(v) >= TREE_SUM_EPSILON:
            return v
    return 0.0


def _oproscene_dobave_amount_from_sums(sums: Dict[str, float]) -> float:
    """Znesek oproščenih dobav iz CSV (P9 / stolpec z č ali _)."""
    for col in OPROSCENE_DOBAV_ALIASES:
        v = float(sums.get(col, 0.0))
        if abs(v) >= TREE_SUM_EPSILON:
            return v
    return 0.0


def _compose_vrednost_racuna_from_components(
    sums: Dict[str, float],
    *,
    include_neobdavcljive: bool = True,
) -> float:
    """Blagajna.csv: Vrednost računa = osnove + davki [+ neobdavčljive] [+ oproščene]."""
    total = (
        float(sums.get("Davčna osnova (22%)", 0.0))
        + float(sums.get("Davek (22%)", 0.0))
        + float(sums.get("Davčna osnova (9,5%)", 0.0))
        + float(sums.get("Davek (9,5%)", 0.0))
    )
    total += _oproscene_dobave_amount_from_sums(sums)
    if include_neobdavcljive:
        total += _neobdavcljive_amount_from_sums(sums)
    return round(total, 2)


def _debet_konto_1000_from_knjizenje(
    *,
    vrednost_neobdavcljivih: float = 0.0,
    vrednost_oproscenih: float = 0.0,
    osnova22: float = 0.0,
    davek22: float = 0.0,
    osnova95: float = 0.0,
    davek95: float = 0.0,
) -> float:
    """Vsota kreditov knjiženja (76* + 26*) — mora ustrezati debetu «Vrednost računa»."""
    return round(
        float(vrednost_neobdavcljivih)
        + float(vrednost_oproscenih)
        + float(osnova22)
        + float(davek22)
        + float(osnova95)
        + float(davek95),
        2,
    )


def _vrednost_racuna_debet_from_sums(sums: Dict[str, float]) -> float:
    """Debet = stolpec «Vrednost računa» iz blagajne.csv (poln znesek, ne glede na kljukico v drevesu)."""
    composed_full = _compose_vrednost_racuna_from_components(sums, include_neobdavcljive=True)
    raw = round(float(sums.get("Vrednost računa", 0.0)), 2)
    if raw > 0 and abs(raw - composed_full) <= TREE_SUM_EPSILON:
        return raw
    if raw > 0 and composed_full <= TREE_SUM_EPSILON:
        return raw
    return composed_full


def _debet_konto_1000_from_sums(sums: Dict[str, float]) -> float:
    """Alias: debet iz seštevkov = Vrednost računa (CSV)."""
    return _vrednost_racuna_debet_from_sums(sums)


def _effective_sums_for_display(
    sums: Dict[str, float],
    *,
    include_neobdavcljive: bool,
    is_kir: bool = False,
) -> Dict[str, float]:
    """Prikaz / seštevki: Vrednost računa z neobdavčljivimi le ob kljukici."""
    out = dict(sums)
    neob = _neobdavcljive_amount_from_sums(out)
    if is_kir:
        full_vr = float(out.get("Vrednost računa", 0.0))
        if include_neobdavcljive:
            out["Vrednost računa"] = round(full_vr, 2)
        else:
            out["Vrednost računa"] = round(full_vr - neob, 2) if neob else round(full_vr, 2)
    else:
        out["Vrednost računa"] = _compose_vrednost_racuna_from_components(
            out, include_neobdavcljive=include_neobdavcljive
        )
    return out


