def company_evidenca_id(company: Dict[str, str]) -> str:
    zst = str(company.get("Zšt", "")).strip()
    if zst:
        return f"Zšt:{zst}"
    davcna = str(company.get("DAVČNA", "")).strip()
    if davcna:
        return f"DAVČNA:{davcna}"
    naziv = str(company.get("NAZIV", "")).strip()
    return f"NAZIV:{naziv}" if naziv else ""


def evidenca_company_snapshot(company: Dict[str, str]) -> Dict[str, str]:
    return {k: str(company.get(k, "")).strip() for k in COMPANY_COLS_UI}


def load_davcna_evidenca_companies() -> List[Dict[str, str]]:
    path = DAVCNA_EVIDENCA_FILE
    if not path.is_file():
        return []
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        log_error("load_davcna_evidenca_companies", exc)
        return []
    if not isinstance(data, dict):
        return []
    raw = data.get("companies")
    if not isinstance(raw, list):
        return []
    out: List[Dict[str, str]] = []
    seen: set = set()
    for item in raw:
        if not isinstance(item, dict):
            continue
        snap = evidenca_company_snapshot(item)
        cid = company_evidenca_id(snap)
        if not cid or cid in seen:
            continue
        seen.add(cid)
        out.append(snap)
    return out


def save_davcna_evidenca_companies(companies: Sequence[Dict[str, str]]) -> None:
    seen: set = set()
    unique: List[Dict[str, str]] = []
    for company in companies:
        snap = evidenca_company_snapshot(company)
        cid = company_evidenca_id(snap)
        if not cid or cid in seen:
            continue
        seen.add(cid)
        unique.append(snap)
    payload = {"version": 1, "companies": unique}
    DAVCNA_EVIDENCA_FILE.parent.mkdir(parents=True, exist_ok=True)
    DAVCNA_EVIDENCA_FILE.write_text(
        json.dumps(payload, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )


def company_in_davcna_evidenca(
    company: Dict[str, str],
    evidenca: Sequence[Dict[str, str]],
) -> bool:
    cid = company_evidenca_id(company)
    if not cid:
        return False
    return any(company_evidenca_id(entry) == cid for entry in evidenca)

