def parse_minimax_document_type_api(raw: str) -> str:
    text = (raw or "").strip()
    if not text:
        return MINIMAX_DOCUMENT_TYPE_DEFAULT
    if " - " in text:
        code = text.split(" - ", 1)[0].strip().upper()
    else:
        code = text.upper()
    code = MINIMAX_DOCUMENT_TYPE_LEGACY_MAP.get(code, code)
    if code in MINIMAX_DOCUMENT_TYPE_API_CODES:
        return code
    return MINIMAX_DOCUMENT_TYPE_DEFAULT


def minimax_document_type_label_for_api(code: str) -> str:
    api = parse_minimax_document_type_api(code)
    return MINIMAX_DOCUMENT_TYPE_LABELS.get(api, MINIMAX_DOCUMENT_TYPE_LABELS[MINIMAX_DOCUMENT_TYPE_DEFAULT])


def minimax_document_type_api_to_xml_sifra(api_code: str) -> str:
    """API DocumentType -> SifraVrsteTemeljnice / KnjigaDDV / stolpec Knjiga (Excel)."""
    api = parse_minimax_document_type_api(api_code)
    if api in {"IRS", "IRI"}:
        return "IR"
    if api == "AVA":
        return "AVA"
    if api == "IZT":
        return "DI"
    return "DI"


