def parse_minimax_issued_status(raw: str) -> str:
    text = (raw or "").strip()
    if not text:
        return "O"
    if " (" in text and text.endswith(")"):
        code = text.rsplit("(", 1)[-1].rstrip(")").strip().upper()
        if code in MINIMAX_ISSUED_STATUS_OPTIONS:
            return code
    code = text.upper()
    if code in MINIMAX_ISSUED_STATUS_OPTIONS:
        return code
    for key, label in MINIMAX_ISSUED_INVOICE_POSTING_STATUS_LABELS.items():
        if text.lower() == label.lower():
            return key
    return "O"


def parse_minimax_received_status(raw: str) -> str:
    text = (raw or "").strip()
    if not text:
        return "O"
    if " (" in text and text.endswith(")"):
        code = text.rsplit("(", 1)[-1].rstrip(")").strip().upper()
        if code in MINIMAX_RECEIVED_STATUS_OPTIONS:
            return code
    code = text.upper()
    if code in MINIMAX_RECEIVED_STATUS_OPTIONS:
        return code
    for key, label in MINIMAX_RECEIVED_INVOICE_STATUS_LABELS.items():
        if text.lower() == label.lower():
            return key
    return "O"


def minimax_received_invoice_status_label(status: Optional[str]) -> str:
    code = (status or "O").strip().upper()
    if not code:
        code = "O"
    name = MINIMAX_RECEIVED_INVOICE_STATUS_LABELS.get(code, code)
    return f"{name} ({code})"


def minimax_issued_invoice_posting_status_label(status: Optional[str]) -> str:
    code = (status or "O").strip().upper()
    if not code:
        code = "O"
    name = MINIMAX_ISSUED_INVOICE_POSTING_STATUS_LABELS.get(code, code)
    return f"{name} ({code})"


def minimax_extract_issued_invoice_posting_status(
    response: Any = None,
    *,
    payload: Optional[Dict[str, Any]] = None,
) -> str:
    if isinstance(response, dict):
        for key in ("Status", "status"):
            val = response.get(key)
            if val is not None and str(val).strip():
                return str(val).strip().upper()[:1]
    if isinstance(payload, dict):
        val = payload.get("Status")
        if val is not None and str(val).strip():
            return str(val).strip().upper()[:1]
    return "O"


def minimax_web_uvoz_opis(yyyy: str, mm: str) -> str:
    """Opis na obrazcu Uvoz podatkov — npr. blagajna 09.2026 (ne pot Excela)."""
    try:
        return f"blagajna {int(str(mm)):02d}.{int(str(yyyy))}"
    except (TypeError, ValueError):
        return f"blagajna {mm}.{yyyy}"


def minimax_web_uvoz_vrsta_temeljnice_for_document_type(api_code: str) -> str:
    """Za Knjižbe in DDV uvoz vedno IR (id=2) — usklajeno z Excel listom DDV Knjiga=IR."""
    _ = parse_minimax_document_type_api(api_code)
    return MINIMAX_WEB_UVOZ_VRSTA_TEMELJNICE


def minimax_format_api_destination_notice(
    *,
    document_type: str,
    posting_id: Optional[int] = None,
    posting_id_to: Optional[int] = None,
    payload: Optional[Dict[str, Any]] = None,
    response: Any = None,
    date_sl: Optional[str] = None,
    description: Optional[str] = None,
) -> str:
    """Človeško berljivo: kam API vstavi knjiženje (modul, status, vrsta DI/IR …)."""
    doc_api = parse_minimax_document_type_api(document_type)
    doc_label = minimax_document_type_label_for_api(doc_api)
    xml_sifra = minimax_document_type_api_to_xml_sifra(doc_api)
    ddv_knjiga = resolve_ddv_knjiga_for_document_type(doc_api)
    status_code = minimax_extract_issued_invoice_posting_status(response, payload=payload)
    status_label = minimax_issued_invoice_posting_status_label(status_code)
    vrsta_temeljnice = minimax_web_uvoz_vrsta_temeljnice_for_document_type(doc_api)

    lines = [
        "Kam je Minimax vpisal podatke (API):",
        f"• Modul: {MINIMAX_ISSUED_INVOICE_POSTING_MODULE_LABEL}",
        "• API: issuedinvoicepostings (ne modul Knjižbe/temeljnice)",
        f"• Vrsta dokumenta (API DocumentType): {doc_label}",
        f"• Status: {status_label}",
        f"• Šifra temeljnice (Excel/XML): {xml_sifra}",
        f"• Knjiga DDV (Excel list DDV): {ddv_knjiga}",
        f"• Vrsta temeljnice (pri ročnem uvozu): {vrsta_temeljnice}",
    ]
    if posting_id is not None and posting_id_to is not None and posting_id_to != posting_id:
        lines.append(f"• ID knjiženja: {posting_id} … {posting_id_to}")
    elif posting_id is not None:
        lines.append(f"• ID knjiženja (IssuedInvoicePostingId): {posting_id}")
    if date_sl:
        lines.append(f"• Datum: {date_sl}")
    if description:
        lines.append(f"• Opis: {description}")
    lines.append("")
    lines.append(
        "V Minimaxu: meni → Knjiženje izdanih računov in iztržkov "
        f"→ poišči po datumu/opisu (vrsta {doc_api}, šifra {xml_sifra})."
    )
    if status_code == "O":
        lines.append(
            "Stanje Osnutek: zapis še ni v modulu Knjižbe (temeljnice) — "
            "po potrditvi/prevzemu v Minimaxu."
        )
    elif status_code == "P":
        lines.append("Stanje Potrjen: preveri tudi modul Knjižbe (temeljnice).")
    return "\n".join(lines)


def minimax_format_web_uvoz_destination_notice(
    *,
    document_type: str,
    date_sl: Optional[str] = None,
) -> str:
    """Kam ročno uvesti Excel, če API ne uspe."""
    doc_api = parse_minimax_document_type_api(document_type)
    doc_label = minimax_document_type_label_for_api(doc_api)
    xml_sifra = minimax_document_type_api_to_xml_sifra(doc_api)
    vrsta_temeljnice = minimax_web_uvoz_vrsta_temeljnice_for_document_type(doc_api)
    lines = [
        "Kam uvesti v Minimax (spletni uvoz — namesto API):",
        f"• Modul: Uvoz podatkov → {MINIMAX_WEB_UVOZ_TIP}",
        f"• Vrsta temeljnice: {vrsta_temeljnice}",
        f"• Šifra (XML/Excel): {xml_sifra}",
        f"• DocumentType (API): {doc_label}",
        f"• Knjiga DDV (Excel): {resolve_ddv_knjiga_for_document_type(doc_api)}",
    ]
    if date_sl:
        lines.append(f"• Datum uvoza: {date_sl}")
    lines.append("")
    lines.append(
        "Po uvozu preveri Knjižbe (temeljnice) in DDV evidenco. "
        "To NI isti modul kot API (Knjiženje izdanih računov in iztržkov)."
    )
    return "\n".join(lines)


def resolve_ddv_knjiga_for_document_type(document_type_api: Optional[str]) -> str:
    """Excel list DDV, stolpec Knjiga — VEDNO 'IR' (za vse DocumentType: IZT, IRI, IRS, AVA).

    Ne vpliva na XML/API DocumentType logiko (ta uporablja
    minimax_document_type_api_to_xml_sifra neposredno).
    """
    _ = document_type_api
    return "IR"


def minimax_format_listina(listina: str, xml_sifra: str) -> str:
    """Listina v DDV/XML: za iztržek (DI) predpona DI:."""
    listina = (listina or "").strip()
    if xml_sifra == "DI" and listina and not listina.upper().startswith("DI:"):
        return f"DI:{listina}"
    return listina


def minimax_document_type_customer_required(api_code: str) -> bool:
    return parse_minimax_document_type_api(api_code) in {"IRS", "IRI", "AVA"}


def resolve_minimax_customer_id(
    *,
    document_type: str,
    customer_id_setting: str,
    journal_rows: Optional[List[Dict[str, Any]]] = None,
) -> Optional[int]:
    if not minimax_document_type_customer_required(document_type):
        return None
    cid = (customer_id_setting or "").strip()
    if not cid and journal_rows:
        for row in journal_rows:
            s = (row.get("Stranka") or "").strip()
            if s.isdigit():
                cid = s
                break
    if not cid:
        return None
    try:
        return int(cid)
    except ValueError:
        raise ValueError(f"Minimax Customer ID mora biti številka, dobil: '{cid}'")


def finalize_issued_invoice_posting_payload(
    base: Dict[str, Any],
    document_type: str,
    *,
    iso_date: str,
    customer_id: Optional[int] = None,
    date_due: Optional[str] = None,
    payment_reference: Optional[str] = None,
    revenue_rows: Optional[List[Dict[str, Any]]] = None,
    tax_rows: Optional[List[Dict[str, Any]]] = None,
    payment_rows: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    doc = parse_minimax_document_type_api(document_type)
    payload: Dict[str, Any] = {
        "DocumentType": doc,
        "Status": base.get("Status", "O"),
        "Date": base.get("Date", iso_date),
        "Description": base.get("Description", ""),
    }

    rev = revenue_rows if revenue_rows is not None else base.get("IssuedInvoicePostingRevenues")
    tax = tax_rows if tax_rows is not None else base.get("IssuedInvoicePostingTaxes")
    pay = payment_rows if payment_rows is not None else base.get("IssuedInvoicePostingPaymentMethods")

    if doc == "IZT":
        if tax:
            payload["IssuedInvoicePostingTaxes"] = tax
        if rev:
            payload["IssuedInvoicePostingRevenues"] = rev
        if pay is not None:
            payload["IssuedInvoicePostingPaymentMethods"] = pay
        return payload

    if doc == "IRI":
        if customer_id is None:
            raise ValueError(
                "DocumentType IRI zahteva stranko (Customer ID). "
                "Vpiši minimax_customer_id v nastavitvah ali stolpec Stranka v knjižbi."
            )
        payload["Customer"] = {"ID": customer_id}
        if tax:
            payload["IssuedInvoicePostingTaxes"] = tax
        return payload

    if doc in {"IRS", "AVA"}:
        if customer_id is None:
            raise ValueError(
                f"DocumentType {doc} zahteva stranko (Customer ID). "
                "Vpiši minimax_customer_id v nastavitvah ali stolpec Stranka v knjižbi."
            )
        payload["Customer"] = {"ID": customer_id}
        payload["DateTransaction"] = iso_date
        payload["DateDue"] = date_due or iso_date
        if payment_reference:
            payload["PaymentReference"] = payment_reference
        if tax:
            payload["IssuedInvoicePostingTaxes"] = tax
        if rev:
            payload["IssuedInvoicePostingRevenues"] = rev
        if pay:
            payload["IssuedInvoicePostingPaymentMethods"] = pay
        return payload

    payload["IssuedInvoicePostingTaxes"] = tax or []
    payload["IssuedInvoicePostingRevenues"] = rev or []
    if pay:
        payload["IssuedInvoicePostingPaymentMethods"] = pay
    return payload
