_kontiranje_prihodkov: List[Dict[str, str]] = []
_kontiranje_placila: List[Dict[str, str]] = []


def _default_kontiranje_prihodkov() -> List[Dict[str, str]]:
    return [
        {"konto": k, "label": lbl, "blago_storitev": bs}
        for k, lbl, bs in VRSTA_PRODAJE_OPTIONS
    ]


def _default_kontiranje_placila() -> List[Dict[str, str]]:
    defaults = {"G": "1000", "T": "1100", "K": "1100", "A": "1900", "D": "1000"}
    return [
        {
            "typ": typ,
            "name": name,
            "konto": defaults.get(typ, ""),
        }
        for _pm_id, name, typ in MINIMAX_PAYMENT_METHOD_FALLBACK
    ]


def _normalize_prihodek_entry(raw: Dict[str, Any]) -> Optional[Dict[str, str]]:
    konto = str(raw.get("konto") or "").strip()
    label = str(raw.get("label") or "").strip()
    bs = str(raw.get("blago_storitev") or "S").strip().upper()[:1] or "S"
    if not konto or not label:
        return None
    if bs not in {"B", "S"}:
        bs = "S"
    return {"konto": konto, "label": label, "blago_storitev": bs}


def _normalize_placilo_entry(raw: Dict[str, Any]) -> Optional[Dict[str, str]]:
    typ = str(raw.get("typ") or "").strip().upper()[:1]
    name = str(raw.get("name") or "").strip()
    konto = str(raw.get("konto") or "").strip()
    if not typ or not name:
        return None
    return {"typ": typ, "name": name, "konto": konto}


def _tree_sums_with_debet_vr(sums: Dict[str, float]) -> Dict[str, float]:
    """V drevesu: «Vrednost računa» = debet (stolpec iz blagajne.csv)."""
    out = dict(sums)
    out["Vrednost računa"] = _vrednost_racuna_debet_from_sums(sums)
    return out


def _rollup_sum_col_for_tree(col: str, sums: Dict[str, float]) -> float:
    if col == "Vrednost računa":
        return _vrednost_racuna_debet_from_sums(sums)
    return float(sums.get(col, 0.0))


def sync_vrsta_prodaje_globals() -> None:
    global VRSTA_PRODAJE_LABELS, VRSTA_PRODAJE_BY_LABEL
    VRSTA_PRODAJE_LABELS = [e["label"] for e in _kontiranje_prihodkov]
    VRSTA_PRODAJE_BY_LABEL = {
        e["label"]: (e["konto"], e["blago_storitev"]) for e in _kontiranje_prihodkov
    }


def init_kontiranje_defaults() -> None:
    global _kontiranje_prihodkov, _kontiranje_placila
    _kontiranje_prihodkov = _default_kontiranje_prihodkov()
    _kontiranje_placila = _default_kontiranje_placila()
    sync_vrsta_prodaje_globals()


def load_kontiranje_from_settings_data(data: Optional[Dict[str, Any]]) -> None:
    global _kontiranje_prihodkov, _kontiranje_placila
    prihodki: List[Dict[str, str]] = []
    placila: List[Dict[str, str]] = []
    if isinstance(data, dict):
        raw_p = data.get("kontiranje_prihodkov")
        if isinstance(raw_p, list):
            for item in raw_p:
                if isinstance(item, dict):
                    norm = _normalize_prihodek_entry(item)
                    if norm:
                        prihodki.append(norm)
        raw_pl = data.get("kontiranje_placila")
        if isinstance(raw_pl, list):
            for item in raw_pl:
                if isinstance(item, dict):
                    norm = _normalize_placilo_entry(item)
                    if norm:
                        placila.append(norm)
    _kontiranje_prihodkov = prihodki or _default_kontiranje_prihodkov()
    if placila:
        by_typ = {e["typ"]: e for e in placila}
        merged: List[Dict[str, str]] = []
        for entry in _default_kontiranje_placila():
            merged.append(dict(by_typ.get(entry["typ"], entry)))
        _kontiranje_placila = merged
    else:
        _kontiranje_placila = _default_kontiranje_placila()
    sync_vrsta_prodaje_globals()


def serialize_kontiranje_for_settings() -> Dict[str, List[Dict[str, str]]]:
    return {
        "kontiranje_prihodkov": [dict(x) for x in _kontiranje_prihodkov],
        "kontiranje_placila": [dict(x) for x in _kontiranje_placila],
    }


def get_kontiranje_prihodkov() -> List[Dict[str, str]]:
    return [dict(x) for x in _kontiranje_prihodkov]


def get_kontiranje_placila() -> List[Dict[str, str]]:
    return [dict(x) for x in _kontiranje_placila]


def set_kontiranje_prihodkov(entries: Sequence[Dict[str, str]]) -> None:
    global _kontiranje_prihodkov
    cleaned = []
    for item in entries:
        norm = _normalize_prihodek_entry(item)
        if norm:
            cleaned.append(norm)
    if not cleaned:
        raise ValueError("Seznam prihodkov ne sme biti prazen.")
    _kontiranje_prihodkov = cleaned
    sync_vrsta_prodaje_globals()


def set_kontiranje_placila(entries: Sequence[Dict[str, str]]) -> None:
    global _kontiranje_placila
    cleaned = []
    for item in entries:
        norm = _normalize_placilo_entry(item)
        if norm:
            cleaned.append(norm)
    if not cleaned:
        raise ValueError("Seznam načinov plačila ne sme biti prazen.")
    _kontiranje_placila = cleaned


def payment_type_from_label(label: str) -> str:
    text = (label or "").strip()
    m = re.search(r"\(([A-Z])\)\s*$", text)
    return m.group(1) if m else ""


def resolve_placilo_konto(payment_label: str) -> str:
    typ = payment_type_from_label(payment_label)
    if typ:
        for entry in _kontiranje_placila:
            if entry.get("typ") == typ:
                return str(entry.get("konto") or "").strip()
    blob = normalize_text(payment_label)
    for entry in _kontiranje_placila:
        if normalize_text(entry.get("name", "")) in blob:
            return str(entry.get("konto") or "").strip()
    return ""


def resolve_prihodek_kontiranje(vrsta_prodaje_label: str) -> Tuple[str, str]:
    label = (vrsta_prodaje_label or "").strip()
    if label in VRSTA_PRODAJE_BY_LABEL:
        return VRSTA_PRODAJE_BY_LABEL[label]
    m = re.match(r"^(\d+)", label)
    return (m.group(1) if m else "7601"), "S"


def infer_placilni_konto_from_journal_rows(journal_rows: Optional[List[Dict[str, Any]]]) -> str:
    for row in journal_rows or []:
        opis = (row.get("Opis") or "").strip()
        if opis.startswith("blagajna za") and " - " not in opis:
            konto = (row.get("Konto") or "").strip()
            debit = round(parse_amount(row.get("Breme domača DE") or row.get("Breme originalna DE")), 2)
            if konto and debit > 0:
                return konto
    return "1000"


