def normalize_text(s: str) -> str:
    s = (s or "").strip().lower()
    s = re.sub(r"\s+", " ", s)
    s = "".join(ch for ch in unicodedata.normalize("NFKD", s) if not unicodedata.combining(ch))
    s = re.sub(r"[^0-9a-z ]+", " ", s)
    s = re.sub(r"\s+", " ", s).strip()
    return s


def header_key(s: str) -> str:
    return normalize_text(s)


def excel_text(v: object) -> str:
    if v is None:
        return ""
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    return str(v).strip()


def header_score(header_norm: str, aliases: Sequence[str]) -> int:
    best = 0
    for alias in aliases:
        alias_norm = header_key(alias)
        if not alias_norm:
            continue
        if header_norm == alias_norm:
            best = max(best, 100)
        elif header_norm.startswith(alias_norm):
            best = max(best, 80)
        elif alias_norm in header_norm:
            best = max(best, 50)
    return best


def find_best_header_row_values_only(ws: Worksheet, required_tokens: Sequence[str], scan_rows: int = 80) -> Optional[int]:
    best_row = None
    best_score = 0
    max_scan = min(ws.max_row, scan_rows)
    for row_i in range(1, max_scan + 1):
        row_vals = [c.value for c in ws[row_i]]
        vals = [header_key(excel_text(v)) for v in row_vals]
        if not any(vals):
            continue
        joined = " | ".join(vals)
        score = sum(1 for tok in required_tokens if tok and tok in joined)
        if score > best_score:
            best_score = score
            best_row = row_i
    return best_row


def normalize_digits(s: str) -> str:
    return re.sub(r"\D+", "", s or "")


def format_zst_folder(zst_value: str) -> str:
    digits = normalize_digits(zst_value)
    if not digits:
        return ""
    n = int(digits)
    width = 3 if n >= 100 else 2
    return f"{n:0{width}d}"


def detect_encoding_bytes(data: bytes, encodings: Sequence[str] = ("utf-8-sig", "utf-8", "cp1250", "latin1")) -> str:
    for enc in encodings:
        try:
            data.decode(enc)
            return enc
        except UnicodeDecodeError:
            continue
    return "latin1"


def detect_dialect(sample_text: str) -> csv.Dialect:
    """FURS blagajne.csv uporablja `;`. Sniffer ob samo glavi (npr. 9,5%) zamenja z `,` — zato `;` ima prednost."""

    class SemicolonDialect(csv.Dialect):
        delimiter = ";"
        quotechar = '"'
        doublequote = True
        skipinitialspace = True
        lineterminator = "\n"
        quoting = csv.QUOTE_MINIMAL

    first_line = (sample_text or "").splitlines()[0] if sample_text else ""
    semi = first_line.count(";")
    comma = first_line.count(",")
    if semi >= 3 and semi > comma:
        return SemicolonDialect()
    try:
        sniffed = csv.Sniffer().sniff(sample_text, delimiters=";,|\t,")
        if getattr(sniffed, "delimiter", "") == "," and semi > comma:
            return SemicolonDialect()
        return sniffed
    except csv.Error:
        return SemicolonDialect()


def parse_amount(value: object) -> float:
    s = ("" if value is None else str(value)).strip()
    if not s or s == "-":
        return 0.0
    s = s.replace("\u00a0", " ").replace(" ", "")
    if "." in s and "," in s:
        s = s.replace(".", "").replace(",", ".")
    elif "," in s and "." not in s:
        s = s.replace(",", ".")
    s = re.sub(r"[^0-9\.\-]", "", s)
    if s in {"", "-", ".", "-."}:
        return 0.0
    try:
        return float(s)
    except ValueError:
        return 0.0


def extract_month(date_str: str) -> Optional[Tuple[str, str]]:
    s = (date_str or "").strip()
    m = MONTH_FROM_DATE_RE.search(s)
    if not m:
        return None
    yyyy = m.group("yyyy")
    mm = int(m.group("mm"))
    return yyyy, f"{mm:02d}"


def extract_day(date_str: str) -> Optional[Tuple[str, str, str]]:
    s = (date_str or "").strip()
    m = MONTH_FROM_DATE_RE.search(s)
    if not m:
        return None
    yyyy = m.group("yyyy")
    mm = int(m.group("mm"))
    dd = int(m.group("dd"))
    return yyyy, f"{mm:02d}", f"{dd:02d}"


def date_to_iso(yyyy: str, mm: str, dd: str) -> str:
    return f"{yyyy}-{int(mm):02d}-{int(dd):02d}"


def date_to_sl(yyyy: str, mm: str, dd: str) -> str:
    return f"{int(dd):02d}.{int(mm):02d}.{yyyy}"


def format_amount_sl(v: float) -> str:
    """Slovenski zapis zneska: 1.234,56"""
    amount = round(float(v), 2)
    negative = amount < 0
    amount = abs(amount)
    whole = int(amount)
    cents = int(round((amount - whole) * 100))
    if cents >= 100:
        whole += 1
        cents = 0
    groups: List[str] = []
    n = whole
    while n > 999:
        groups.append(f"{n % 1000:03d}")
        n //= 1000
    groups.append(str(n))
    int_str = ".".join(reversed(groups))
    return f"{'-' if negative else ''}{int_str},{cents:02d}"


def iso_date_to_sl(value: str) -> str:
    raw = (value or "").strip()
    if not raw:
        return ""
    m = re.fullmatch(r"(\d{4})-(\d{2})-(\d{2})", raw)
    if m:
        return date_to_sl(m.group(1), m.group(2), m.group(3))
    ymd = extract_day(raw)
    if ymd:
        return date_to_sl(*ymd)
    return raw


def parse_sl_date_to_iso(value: str) -> str:
    raw = (value or "").strip()
    if not raw:
        raise ValueError("Manjka datum.")
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw):
        return raw
    ymd = extract_day(raw)
    if ymd:
        return date_to_iso(*ymd)
    raise ValueError(f"Neveljaven datum (pričakovan dd.mm.yyyy): {value}")


def minimax_account_primary_code(item: Dict[str, Any]) -> str:
    for key in ("Code", "code", "AccountNumber", "accountNumber"):
        val = str(item.get(key) or "").strip()
        if val:
            return val
    for candidate in minimax_item_account_code_candidates(item):
        if candidate:
            return candidate
    return ""


def minimax_account_display_name(item: Dict[str, Any]) -> str:
    for key in ("Name", "name", "Title", "title", "Description", "description"):
        val = str(item.get(key) or "").strip()
        if val:
            return val
    return ""


def minimax_accounts_combobox_entries(
    accounts: List[Dict[str, Any]],
) -> Tuple[List[str], Dict[str, str]]:
    """Vrne (oznake za combo, oznaka -> koda konta)."""
    seen: set[str] = set()
    labels: List[str] = []
    label_to_code: Dict[str, str] = {}

    def _sort_key(code: str) -> Tuple[int, str]:
        digits = re.sub(r"\D", "", code)
        return (0, f"{int(digits):010d}") if digits.isdigit() else (1, code.lower())

    rows: List[Tuple[str, str]] = []
    for item in accounts:
        if not isinstance(item, dict):
            continue
        code = minimax_account_primary_code(item)
        if not code or code in seen:
            continue
        seen.add(code)
        name = minimax_account_display_name(item)
        label = f"{code} — {name}" if name else code
        rows.append((code, label))

    for _code, label in sorted(rows, key=lambda row: _sort_key(row[0])):
        labels.append(label)
        label_to_code[label] = _code
    return labels, label_to_code


def minimax_account_code_from_ref(
    account_ref: Any,
    accounts: List[Dict[str, Any]],
) -> str:
    if not isinstance(account_ref, dict):
        return ""
    code = str(account_ref.get("Code") or account_ref.get("code") or "").strip()
    if code:
        return code
    name = str(account_ref.get("Name") or account_ref.get("name") or "").strip()
    if name:
        m = re.match(r"^(\d+)\b", name)
        if m:
            return m.group(1)
    acc_id = account_ref.get("ID") or account_ref.get("Id") or account_ref.get("id")
    if acc_id is None:
        return ""
    try:
        want_id = int(acc_id)
    except (TypeError, ValueError):
        return ""
    for item in accounts:
        for id_key in ("ID", "Id", "id", "AccountId", "accountId"):
            try:
                if int(item.get(id_key)) == want_id:
                    return minimax_account_primary_code(item)
            except (TypeError, ValueError):
                continue
    return ""


def parse_konto_combo_value(raw: str) -> str:
    s = (raw or "").strip()
    if not s:
        return ""
    if " — " in s:
        return s.split(" — ", 1)[0].strip()
    m = re.match(r"^(\S+)", s)
    return m.group(1) if m else s


def minimax_fetch_all_customers_paginated(
    api_base: str, token: str, organisation_id: int
) -> List[Dict[str, Any]]:
    return minimax_fetch_items_paginated(api_base, token, organisation_id, "customers")


def minimax_customer_primary_id(item: Dict[str, Any]) -> Optional[int]:
    if not isinstance(item, dict):
        return None
    for id_key in ("CustomerId", "CustomerID", "ID", "Id", "id"):
        val = item.get(id_key)
        if val is not None:
            try:
                n = int(val)
                if n > 0:
                    return n
            except (TypeError, ValueError):
                pass
    return None


def minimax_customer_display_name(item: Dict[str, Any]) -> str:
    if not isinstance(item, dict):
        return ""
    for key in ("Name", "name", "Title", "title", "Code", "code"):
        val = str(item.get(key) or "").strip()
        if val:
            return val
    return ""


def minimax_customers_combobox_entries(
    customers: List[Dict[str, Any]],
) -> Tuple[List[str], Dict[str, str]]:
    """Vrne (oznake za combo, oznaka -> Customer ID kot niz)."""
    seen: set[int] = set()
    labels: List[str] = []
    label_to_id: Dict[str, str] = {}
    rows: List[Tuple[int, str, str]] = []

    for item in customers:
        if not isinstance(item, dict):
            continue
        cid = minimax_customer_primary_id(item)
        if cid is None or cid in seen:
            continue
        seen.add(cid)
        name = minimax_customer_display_name(item)
        tax = str(item.get("TaxNumber") or item.get("VatNumber") or item.get("RegistrationNumber") or "").strip()
        label = f"{cid} — {name}" if name else str(cid)
        if tax:
            label = f"{label} ({tax})"
        rows.append((cid, label, name.lower()))

    for cid, label, _name in sorted(rows, key=lambda row: (row[2], row[0])):
        labels.append(label)
        label_to_id[label] = str(cid)
    return labels, label_to_id


def parse_customer_combo_value(raw: str) -> str:
    s = (raw or "").strip()
    if not s:
        return ""
    if " — " in s:
        return s.split(" — ", 1)[0].strip()
    m = re.match(r"^(\d+)", s)
    if m:
        return m.group(1)
    if s.isdigit():
        return s
    return s


def customer_combo_label_for_id(
    customer_id: str,
    label_to_id: Dict[str, str],
    customers: Optional[List[Dict[str, Any]]] = None,
) -> str:
    want = (customer_id or "").strip()
    if not want:
        return ""
    for label, mapped in label_to_id.items():
        if str(mapped) == want:
            return label
    if customers:
        try:
            want_id = int(want)
        except (TypeError, ValueError):
            return want
        for item in customers:
            if not isinstance(item, dict):
                continue
            cid = minimax_customer_primary_id(item)
            if cid is None or int(cid) != want_id:
                continue
            name = minimax_customer_display_name(item)
            tax = str(
                item.get("TaxNumber") or item.get("VatNumber") or item.get("RegistrationNumber") or ""
            ).strip()
            label = f"{cid} — {name}" if name else str(cid)
            if tax:
                label = f"{label} ({tax})"
            return label
    return want


def resolve_kpr_supplier_customer_id(
    payload: Dict[str, Any],
    customers: List[Dict[str, Any]],
    kirkpr_fields: Optional[Dict[str, str]],
    customer_id_setting: str,
) -> str:
    """Dobavitelj: payload → P1 davčna → nastavitev (samo če obstaja v seznamu)."""
    cust = payload.get("Customer")
    if isinstance(cust, dict) and cust.get("ID") is not None:
        return str(cust.get("ID"))
    tax_cid = minimax_customer_id_by_tax_number(
        customers, (kirkpr_fields or {}).get("P1") or ""
    )
    if tax_cid is not None:
        return str(tax_cid)
    setting = (customer_id_setting or "").strip()
    if not setting:
        return ""
    if customers:
        try:
            want_id = int(setting)
        except (TypeError, ValueError):
            return ""
        for item in customers:
            cid = minimax_customer_primary_id(item)
            if cid is not None and int(cid) == want_id:
                return setting
        return ""
    return setting


def resolve_kir_customer_id(
    payload: Dict[str, Any],
    customers: List[Dict[str, Any]],
    kirkpr_fields: Optional[Dict[str, str]],
    customer_id_setting: str,
) -> str:
    """Kupec/stranka za KIR: payload → P1 (davčna) → nastavitev."""
    return resolve_kpr_supplier_customer_id(
        payload, customers, kirkpr_fields, customer_id_setting
    )


def minimax_api_date_to_iso(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    m = re.fullmatch(r"(\d{4}-\d{2}-\d{2})", raw[:10])
    if m:
        return m.group(1)
    ymd = extract_day(raw)
    if ymd:
        return date_to_iso(*ymd)
    return ""


def minimax_amounts_close(a: float, b: float, tol: float = COMPARE_FLOAT_TOLERANCE) -> bool:
    return abs(float(a) - float(b)) <= tol


def minimax_account_matches_book(code: str, book: str) -> bool:
    """KIR = prihodki (7), KPR = stroški (4, 6) po slovenskem kontnem načrtu."""
    digits = re.sub(r"\D", "", (code or "").strip())
    if not digits:
        return False
    lead = int(digits[0])
    book_u = (book or "KIR").strip().upper()
    if book_u == "KPR":
        return lead in (4, 6)
    return lead == 7


def minimax_accounts_combobox_entries_for_book(
    accounts: List[Dict[str, Any]],
    book: str,
    *,
    include_codes: Optional[set[str]] = None,
) -> Tuple[List[str], Dict[str, str]]:
    want_codes = {c.strip() for c in (include_codes or set()) if (c or "").strip()}
    filtered: List[Dict[str, Any]] = []
    for item in accounts:
        if not isinstance(item, dict):
            continue
        code = minimax_account_primary_code(item)
        if not code:
            continue
        if code in want_codes or minimax_account_matches_book(code, book):
            filtered.append(item)
    if not filtered and accounts:
        filtered = [a for a in accounts if isinstance(a, dict)]
    return minimax_accounts_combobox_entries(filtered)


def minimax_get_org_resource(
    api_base: str,
    token: str,
    organisation_id: int,
    resource_path: str,
) -> Dict[str, Any]:
    path = (resource_path or "").strip().strip("/")
    url = minimax_api_url(api_base, f"orgs/{organisation_id}/{path}")
    data = http_json_request(url, headers=_minimax_auth_headers(token))
    return data if isinstance(data, dict) else {}


def minimax_customer_id_by_tax_number(
    customers: List[Dict[str, Any]],
    tax_number: str,
) -> Optional[int]:
    want = re.sub(r"\D", "", (tax_number or "").strip())
    if not want:
        return None
    for item in customers:
        if not isinstance(item, dict):
            continue
        for key in ("TaxNumber", "VatNumber", "RegistrationNumber", "Code"):
            raw = re.sub(r"\D", "", str(item.get(key) or ""))
            if not raw:
                continue
            if raw == want or (
                len(want) >= 7 and (raw.endswith(want) or want.endswith(raw))
            ):
                return minimax_customer_primary_id(item)
    return None


def minimax_customers_merge_row(
    customers: List[Dict[str, Any]],
    row: Dict[str, Any],
) -> None:
    if not isinstance(row, dict):
        return
    cid = minimax_customer_primary_id(row)
    if cid is None:
        return
    for item in customers:
        if minimax_customer_primary_id(item) == cid:
            return
    customers.append(row)


def minimax_fetch_customer_by_id(
    api_base: str,
    token: str,
    organisation_id: int,
    customer_id: int,
    customers: List[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    for item in customers:
        if minimax_customer_primary_id(item) == customer_id:
            return item
    try:
        row = minimax_get_org_resource(
            api_base, token, organisation_id, f"customers/{int(customer_id)}"
        )
        if isinstance(row, dict) and row:
            minimax_customers_merge_row(customers, row)
            return row
    except Exception as exc:
        log_error(f"minimax_fetch_customer_by_id {customer_id}", exc)
    return None


def minimax_resolve_customer_id_from_evidence(
    api_base: str,
    token: str,
    organisation_id: int,
    customers: List[Dict[str, Any]],
    kirkpr_fields: Optional[Dict[str, str]],
    payload: Dict[str, Any],
    customer_id_setting: str,
) -> Optional[int]:
    """Stranka/dobavitelj: payload → P1 → API iskanje → nastavitev."""
    cust = payload.get("Customer")
    if isinstance(cust, dict) and cust.get("ID") is not None:
        try:
            cid = int(cust.get("ID"))
            minimax_fetch_customer_by_id(api_base, token, organisation_id, cid, customers)
            return cid
        except (TypeError, ValueError):
            pass

    fields = kirkpr_fields or {}
    tax = (fields.get("P1") or "").strip()
    cid = minimax_customer_id_by_tax_number(customers, tax)
    if cid is not None:
        minimax_fetch_customer_by_id(api_base, token, organisation_id, cid, customers)
        return cid

    search_terms: List[str] = []
    seen_term: set[str] = set()
    want_digits = re.sub(r"\D", "", tax)
    for term in (want_digits, tax, (fields.get("P6") or "").split(",")[0].strip()):
        t = (term or "").strip()
        if t and t not in seen_term:
            seen_term.add(t)
            search_terms.append(t)

    name_hint = _kpr_supplier_address_from_fields(fields).split(",")[0].strip().lower()
    for term in search_terms[:5]:
        try:
            rows = minimax_find_items_by_search(
                api_base, token, organisation_id, "customers", term
            )
        except Exception as exc:
            log_error(f"minimax_resolve_customer_id search '{term}'", exc)
            continue
        for row in rows:
            minimax_customers_merge_row(customers, row)
        cid = minimax_customer_id_by_tax_number(rows, tax)
        if cid is not None:
            return cid
        if name_hint:
            for row in rows:
                if not isinstance(row, dict):
                    continue
                nm = minimax_customer_display_name(row).lower()
                if name_hint in nm or nm in name_hint:
                    rid = minimax_customer_primary_id(row)
                    if rid is not None:
                        return rid

    setting = (customer_id_setting or "").strip()
    if not setting:
        return None
    try:
        want_id = int(setting)
    except (TypeError, ValueError):
        return None
    if minimax_fetch_customer_by_id(api_base, token, organisation_id, want_id, customers):
        return want_id
    for item in customers:
        rid = minimax_customer_primary_id(item)
        if rid is not None and int(rid) == want_id:
            return want_id
    return None


def minimax_accounts_merge_by_code(
    api_base: str,
    token: str,
    organisation_id: int,
    code: str,
    accounts: List[Dict[str, Any]],
) -> None:
    code = (code or "").strip()
    if not code:
        return
    for item in accounts:
        if minimax_account_codes_equal(minimax_account_primary_code(item), code):
            return
    try:
        acc_id = minimax_search_accounts_by_code(api_base, token, organisation_id, code)
        if acc_id is None:
            return
        row = minimax_get_org_resource(
            api_base, token, organisation_id, f"accounts/{int(acc_id)}"
        )
        if isinstance(row, dict) and row:
            accounts.append(row)
    except Exception as exc:
        log_error(f"minimax_accounts_merge_by_code {code}", exc)


def minimax_combobox_ensure_account_code(
    labels: List[str],
    label_to_code: Dict[str, str],
    code: str,
    accounts: List[Dict[str, Any]],
    *,
    api_base: str = "",
    token: str = "",
    organisation_id: int = 0,
) -> Tuple[List[str], Dict[str, str]]:
    code = (code or "").strip()
    if not code:
        return labels, label_to_code
    existing = konto_combo_label_for_code(code, label_to_code)
    if existing:
        if existing not in label_to_code:
            labels.append(existing)
            label_to_code[existing] = code
        return labels, label_to_code
    if api_base and token and organisation_id:
        minimax_accounts_merge_by_code(api_base, token, organisation_id, code, accounts)
    for item in accounts:
        if not isinstance(item, dict):
            continue
        acc_code = minimax_account_primary_code(item)
        if not minimax_account_codes_equal(acc_code, code):
            continue
        name = minimax_account_display_name(item)
        label = f"{acc_code} — {name}" if name else acc_code
        if label not in label_to_code:
            labels.append(label)
            label_to_code[label] = acc_code
        return labels, label_to_code
    label = code
    if label not in label_to_code:
        labels.append(label)
        label_to_code[label] = code
    return labels, label_to_code


def minimax_combobox_ensure_customer_id(
    labels: List[str],
    label_to_id: Dict[str, str],
    customer_id: str,
    customers: List[Dict[str, Any]],
    *,
    api_base: str = "",
    token: str = "",
    organisation_id: int = 0,
) -> Tuple[List[str], Dict[str, str]]:
    want = (customer_id or "").strip()
    if not want:
        return labels, label_to_id
    existing = customer_combo_label_for_id(want, label_to_id, customers)
    if existing:
        if existing not in label_to_id:
            labels.append(existing)
            label_to_id[existing] = want
        return labels, label_to_id
    try:
        cid = int(want)
    except (TypeError, ValueError):
        return labels, label_to_id
    if api_base and token and organisation_id:
        minimax_fetch_customer_by_id(api_base, token, organisation_id, cid, customers)
    label = customer_combo_label_for_id(want, label_to_id, customers)
    if label and label not in label_to_id:
        labels.append(label)
        label_to_id[label] = want
    return labels, label_to_id


def _issued_posting_total_amount(posting: Dict[str, Any]) -> float:
    pays = posting.get("IssuedInvoicePostingPaymentMethods") or []
    total = round(sum(float(p.get("Amount") or 0.0) for p in pays if isinstance(p, dict)), 2)
    if total > 0:
        return total
    revs = posting.get("IssuedInvoicePostingRevenues") or []
    total = round(sum(float(r.get("Amount") or 0.0) for r in revs if isinstance(r, dict)), 2)
    if total > 0:
        return total
    return round(float(posting.get("InvoiceAmount") or posting.get("Amount") or 0.0), 2)


def minimax_received_invoice_document_label(payload: Dict[str, Any]) -> str:
    """Minimax oznaka prejetega računa npr. 2026-264 (Year-InvoiceNumber)."""
    year = payload.get("Year")
    number = payload.get("InvoiceNumber")
    if year is not None and number is not None:
        try:
            return f"{int(year)}-{int(number)}"
        except (TypeError, ValueError):
            pass
    return ""


def _kpr_payment_reference_looks_valid(ref: str) -> bool:
    """Zavrni numerične ID-je temeljnice (npr. 2026271), ohrani TS in 2026-264."""
    raw = (ref or "").strip()
    if not raw:
        return False
    if raw.upper().startswith("TS"):
        return True
    if "-" in raw:
        return True
    if re.fullmatch(r"\d{5,}", raw):
        return False
    return True


def _kpr_expense_row_amount(row: Dict[str, Any]) -> float:
    for key in (
        "Amount",
        "BaseAmount",
        "TaxBase",
        "NetAmount",
        "Value",
        "ExpenseAmount",
        "Osnova",
    ):
        try:
            val = round(float(row.get(key) or 0.0), 2)
        except (TypeError, ValueError):
            continue
        if val > 0:
            return val
    return 0.0


def _kpr_expense_konto_from_payload(
    payload: Dict[str, Any],
    accounts: List[Dict[str, Any]],
    *,
    doc_sums: Optional[Dict[str, float]] = None,
) -> str:
    match_amounts = _kpr_journal_match_amounts(doc_sums or {})
    expense = payload.get("RevenueExpense")
    if isinstance(expense, dict):
        code = minimax_account_code_from_ref(expense, accounts)
        if code and minimax_account_matches_book(code, "KPR"):
            return code

    row_lists: List[List[Dict[str, Any]]] = []
    for key in (
        "ReceivedInvoiceItems",
        "ReceivedInvoiceRows",
        "ReceivedInvoiceExpenses",
        "Items",
        "Rows",
        "Expenses",
    ):
        rows = payload.get(key)
        if isinstance(rows, list) and rows:
            row_lists.append([r for r in rows if isinstance(r, dict)])

    best_code = ""
    best_score = -1
    fallback_code = ""
    for rows in row_lists:
        for row in rows:
            code = ""
            for acc_key in ("Account", "ExpenseAccount", "RevenueExpense", "CostAccount"):
                ref = row.get(acc_key)
                if isinstance(ref, dict):
                    code = minimax_account_code_from_ref(ref, accounts)
                    if code:
                        break
            if not code or not minimax_account_matches_book(code, "KPR"):
                continue
            if not fallback_code:
                fallback_code = code
            amount = _kpr_expense_row_amount(row)
            score = 0
            if amount > 0 and match_amounts:
                if any(minimax_amounts_close(amount, amt) for amt in match_amounts):
                    score += 10
                elif any(minimax_amounts_close(amount, amt, tol=0.05) for amt in match_amounts):
                    score += 5
            if score > best_score:
                best_score = score
                best_code = code
    return best_code or fallback_code


def minimax_try_enrich_received_invoice(
    api_base: str,
    token: str,
    organisation_id: int,
    invoice: Dict[str, Any],
    accounts: List[Dict[str, Any]],
) -> Dict[str, Any]:
    out = dict(invoice)
    inv_id = out.get("ReceivedInvoiceId") or out.get("ID") or out.get("Id")
    if inv_id is None:
        return out
    for suffix in ("items", "receivedinvoiceitems", "receivedinvoiceexpenses", "rows", "expenses"):
        try:
            sub = minimax_get_org_resource(
                api_base,
                token,
                organisation_id,
                f"receivedinvoices/{int(inv_id)}/{suffix}",
            )
            rows = minimax_extract_rows_from_response(sub)
            if rows:
                out["ReceivedInvoiceItems"] = rows
                code = _kpr_expense_konto_from_payload(out, accounts)
                if code:
                    break
        except Exception:
            continue
    return out


def build_kpr_minimax_notes_text(
    st_listine: str,
    vezni_dokument: str,
    *,
    fallback: str = "",
) -> str:
    """Opis/Notes: «prejeti račun;št.listine;» npr. 2026-264;260327;"""
    doc = (vezni_dokument or "").strip()
    stl = (st_listine or "").strip()
    if doc and stl:
        return f"{doc};{stl};"
    if stl:
        return f"{stl};"
    if doc:
        return f"{doc};"
    return (fallback or "").strip()


def _parse_kpr_notes_parts(notes: str) -> Tuple[str, str]:
    raw = (notes or "").strip()
    if ";" in raw:
        left, right = raw.split(";", 1)
        return left.strip(), right.strip()
    return raw, ""


def minimax_fetch_journal_entries(
    api_base: str,
    token: str,
    organisation_id: int,
    *,
    date_from: str = "",
    date_to: str = "",
    search_string: str = "",
    page_size: int = MINIMAX_API_PAGE_SIZE,
) -> List[Dict[str, Any]]:
    all_rows: List[Dict[str, Any]] = []
    current_page = 1
    while True:
        params: Dict[str, Any] = {"CurrentPage": current_page, "PageSize": page_size}
        if search_string:
            params["SearchString"] = search_string
        if date_from:
            params["DateFrom"] = date_from
        if date_to:
            params["DateTo"] = date_to
        qs = "?" + urlparse.urlencode(params)
        try:
            data = http_json_request(
                minimax_api_url(api_base, f"orgs/{organisation_id}/journals/journal-entries{qs}"),
                headers=_minimax_auth_headers(token),
            )
        except Exception as exc:
            log_error("minimax_fetch_journal_entries", exc)
            break
        rows = minimax_extract_rows_from_response(data)
        if not rows:
            break
        all_rows.extend(rows)
        total_rows = minimax_response_total_rows(data)
        if total_rows is not None and len(all_rows) >= total_rows:
            break
        if len(rows) < page_size:
            break
        current_page += 1
        if current_page > 8:
            break
    return all_rows


def _scan_journal_rows_for_kpr_hints(
    rows: List[Dict[str, Any]],
    accounts: List[Dict[str, Any]],
    terms: List[str],
    match_amounts: List[float],
    out: Dict[str, str],
    *,
    kirkpr_fields: Optional[Dict[str, str]] = None,
    best_konto: str,
    best_konto_score: int,
    best_rid: Optional[int],
) -> Tuple[str, int, Optional[int]]:
    for row in rows:
        desc = str(row.get("Description") or "")
        pay_ref = str(row.get("PaymentReference") or "")
        blob = f"{desc} {pay_ref}".lower()
        term_hit = bool(terms) and any(t.lower() in blob for t in terms)
        pay_ref_clean = pay_ref.strip()
        if pay_ref_clean and not out["vezni_dokument"]:
            if _kpr_payment_reference_looks_valid(pay_ref_clean) and not _kpr_text_is_supplier_address(
                pay_ref_clean, kirkpr_fields
            ):
                out["vezni_dokument"] = pay_ref_clean
        rid = _journal_row_received_invoice_id(row)
        if rid is not None:
            best_rid = rid
        due_iso = minimax_api_date_to_iso(
            row.get("DateDue") or row.get("DueDate") or row.get("PaymentDueDate") or ""
        )
        if due_iso and not out["date_due"]:
            out["date_due"] = due_iso
        code = minimax_account_code_from_ref(row.get("Account"), accounts)
        if not code or not minimax_account_matches_book(code, "KPR"):
            continue
        debit = round(
            float(row.get("DebitInDomesticCurrency") or row.get("Debit") or 0.0),
            2,
        )
        if debit <= 0:
            continue
        amount_hit = any(minimax_amounts_close(debit, amt) for amt in match_amounts if amt > 0)
        amount_near = any(
            minimax_amounts_close(debit, amt, tol=0.05) for amt in match_amounts if amt > 0
        )
        if terms and not term_hit and not amount_hit:
            continue
        score = 0
        if amount_hit:
            score += 10
        elif amount_near:
            score += 5
        if term_hit:
            score += 3
        if score > best_konto_score:
            best_konto_score = score
            best_konto = code
        elif not best_konto and (term_hit or amount_hit):
            best_konto = code
    return best_konto, best_konto_score, best_rid


def find_kpr_posting_hints_from_journal(
    api_base: str,
    token: str,
    organisation_id: int,
    accounts: List[Dict[str, Any]],
    *,
    iso_date: str,
    target_amount: float,
    search_terms: List[str],
    doc_sums: Optional[Dict[str, float]] = None,
    kirkpr_fields: Optional[Dict[str, str]] = None,
) -> Dict[str, str]:
    """Konto stroškov, vezni dokument in ID prejetega računa iz knjiženja (temeljnica)."""
    out: Dict[str, str] = {
        "konto": "",
        "vezni_dokument": "",
        "received_invoice_id": "",
        "date_due": "",
        "posted": "",
    }
    terms = [t.strip() for t in search_terms if (t or "").strip()]
    match_amounts = _kpr_journal_match_amounts(doc_sums or {})
    if target_amount > 0 and not any(minimax_amounts_close(target_amount, a) for a in match_amounts):
        match_amounts.insert(0, round(target_amount, 2))
    seen_ids: set[str] = set()
    best_konto = ""
    best_konto_score = -1
    best_rid: Optional[int] = None

    def _ingest_batch(batch: List[Dict[str, Any]]) -> None:
        nonlocal best_konto, best_konto_score, best_rid
        fresh: List[Dict[str, Any]] = []
        for row in batch:
            if not isinstance(row, dict):
                continue
            rid = str(row.get("JournalEntryId") or row.get("ID") or row.get("Id") or id(row))
            if rid in seen_ids:
                continue
            seen_ids.add(rid)
            fresh.append(row)
        if not fresh:
            return
        best_konto, best_konto_score, best_rid = _scan_journal_rows_for_kpr_hints(
            fresh,
            accounts,
            terms,
            match_amounts,
            out,
            kirkpr_fields=kirkpr_fields,
            best_konto=best_konto,
            best_konto_score=best_konto_score,
            best_rid=best_rid,
        )

    for term in terms[:3]:
        _ingest_batch(
            minimax_fetch_journal_entries(
                api_base,
                token,
                organisation_id,
                date_from=iso_date,
                date_to=iso_date,
                search_string=term,
            )
        )
        if best_rid is not None and best_konto and out.get("vezni_dokument"):
            break
    if (not best_konto or not out.get("vezni_dokument")) and iso_date:
        _ingest_batch(
            minimax_fetch_journal_entries(
                api_base,
                token,
                organisation_id,
                date_from=iso_date,
                date_to=iso_date,
            )
        )

    if best_konto:
        out["konto"] = best_konto
        out["posted"] = "1"
    if best_rid is not None:
        out["received_invoice_id"] = str(best_rid)
    return out


def minimax_customer_match_by_query(
    customers: List[Dict[str, Any]],
    query: str,
    label_to_id: Optional[Dict[str, str]] = None,
) -> str:
    """Vrne Customer ID iz izbire comboboxa ali delnega imena (npr. «qui» → Quick)."""
    direct = parse_customer_combo_value(query)
    if direct.isdigit():
        return direct
    q = (query or "").strip().lower()
    if not q:
        return ""
    for label, cid in (label_to_id or {}).items():
        if q in label.lower():
            return str(cid)
    for item in customers:
        if not isinstance(item, dict):
            continue
        name = minimax_customer_display_name(item).lower()
        tax = str(item.get("TaxNumber") or item.get("VatNumber") or "").lower()
        if q in name or (tax and q in tax):
            cid = minimax_customer_primary_id(item)
            if cid is not None:
                return str(cid)
    return direct


def _collect_minimax_search_terms(
    *,
    doc_id: str = "",
    match_id: str = "",
    kirkpr_fields: Optional[Dict[str, str]] = None,
) -> List[str]:
    terms: List[str] = []
    seen: set[str] = set()
    fields = kirkpr_fields or {}
    raw_values = [
        doc_id,
        match_id,
        fields.get("P3"),
        fields.get("P1"),
    ]
    p3 = (fields.get("P3") or "").strip()
    if ";" in p3:
        left, right = p3.split(";", 1)
        raw_values.extend((left, right))
    for raw in raw_values:
        val = (raw or "").strip()
        if val and val not in seen:
            seen.add(val)
            terms.append(val)
    return terms


def _kpr_receipt_iso_from_fields(
    yyyy: str,
    mm: str,
    dd: str,
    fields: Optional[Dict[str, str]] = None,
) -> str:
    iso = date_to_iso(yyyy, mm, dd)
    for tag in ("P2", "P4"):
        alt = minimax_api_date_to_iso((fields or {}).get(tag) or "")
        if alt:
            return alt
    return iso


def _kpr_supplier_address_from_fields(fields: Optional[Dict[str, str]] = None) -> str:
    """P6 v KPR = ime in naslov dobavitelja (ne vezni dokument)."""
    return ((fields or {}).get("P6") or "").strip()


def _kpr_text_is_supplier_address(text: str, fields: Optional[Dict[str, str]] = None) -> bool:
    raw = (text or "").strip()
    if not raw:
        return False
    p6 = _kpr_supplier_address_from_fields(fields)
    if p6 and raw.lower() == p6.lower():
        return True
    if p6 and len(p6) > 12 and p6.lower() in raw.lower():
        return True
    low = raw.lower()
    if "d.o.o" in low and "," in raw and len(raw) > 25:
        return True
    return False


def _kpr_journal_search_terms(
    *,
    doc_id: str = "",
    match_id: str = "",
    kirkpr_fields: Optional[Dict[str, str]] = None,
) -> List[str]:
    """Iskalni pojmi za temeljnico — brez P6 (naslov dobavitelja)."""
    terms: List[str] = []
    seen: set[str] = set()
    fields = kirkpr_fields or {}
    for raw in (doc_id, match_id, fields.get("P3"), fields.get("P1")):
        val = (raw or "").strip()
        if val and val not in seen:
            seen.add(val)
            terms.append(val)
    p3 = (fields.get("P3") or "").strip()
    if ";" in p3:
        left, right = p3.split(";", 1)
        for part in (left, right):
            part = part.strip()
            if part and part not in seen:
                seen.add(part)
                terms.append(part)
    return terms


def _kpr_journal_match_amounts(doc_sums: Dict[str, float]) -> List[float]:
    """Zneski za ujemanje v temeljnici (bruto, osnova P8–P13, osnova DDV)."""
    out: List[float] = []
    seen: set[float] = set()

    def _add(val: float) -> None:
        v = round(float(val), 2)
        if v > 0 and v not in seen:
            seen.add(v)
            out.append(v)

    _add(doc_sums.get("Vrednost računa", 0.0))
    for col in (
        "P8 Blago in storitve",
        "P9 Samoobdavčitev",
        "P10 Pridobitev blaga",
        "P11 Prejete storitve",
        "P12 Nepremičnine",
        "P13 Druga OS",
        "Davčna osnova (22%)",
        "Osnova za DDV - skupaj",
    ):
        _add(doc_sums.get(col, 0.0))
    return out


def _kpr_due_date_iso_from_fields(fields: Optional[Dict[str, str]] = None) -> str:
    """Datum zapadlosti iz KPR evidence (P5)."""
    return minimax_api_date_to_iso((fields or {}).get("P5") or "")


def _received_invoice_row_iso_date(row: Dict[str, Any]) -> str:
    for key in ("DateReceived", "DateIssued", "Date"):
        iso = minimax_api_date_to_iso(row.get(key) or "")
        if iso:
            return iso
    return ""


def _journal_row_received_invoice_id(row: Dict[str, Any]) -> Optional[int]:
    for key in ("ReceivedInvoiceId", "ReceivedInvoiceID"):
        val = row.get(key)
        if val is not None:
            try:
                return int(val)
            except (TypeError, ValueError):
                pass
    ri = row.get("ReceivedInvoice")
    if isinstance(ri, dict) and ri.get("ID") is not None:
        try:
            return int(ri.get("ID"))
        except (TypeError, ValueError):
            pass
    return None


def minimax_fetch_received_invoices_for_date(
    api_base: str,
    token: str,
    organisation_id: int,
    iso_date: str,
    *,
    page_size: int = MINIMAX_API_PAGE_SIZE,
) -> List[Dict[str, Any]]:
    """Prejeti računi za dan (DateFrom/DateTo ali filtriranje po straneh)."""
    iso_date = (iso_date or "").strip()
    if not iso_date:
        return []
    rows: List[Dict[str, Any]] = []
    current_page = 1
    used_date_filter = False
    while current_page <= 8:
        params: Dict[str, Any] = {
            "CurrentPage": current_page,
            "PageSize": page_size,
            "DateFrom": iso_date,
            "DateTo": iso_date,
        }
        qs = "?" + urlparse.urlencode(params)
        try:
            data = http_json_request(
                minimax_api_url(api_base, f"orgs/{organisation_id}/receivedinvoices{qs}"),
                headers=_minimax_auth_headers(token),
            )
            used_date_filter = True
        except Exception as exc:
            if used_date_filter and current_page == 1:
                log_error("minimax_fetch_received_invoices_for_date DateFrom", exc)
                used_date_filter = False
                current_page = 1
                continue
            log_error("minimax_fetch_received_invoices_for_date", exc)
            break
        batch = minimax_extract_rows_from_response(data)
        if not batch:
            break
        if used_date_filter:
            rows.extend(batch)
        else:
            for row in batch:
                if not isinstance(row, dict):
                    continue
                if _received_invoice_row_iso_date(row) == iso_date:
                    rows.append(row)
        total_rows = minimax_response_total_rows(data)
        if total_rows is not None and len(rows) >= total_rows:
            break
        if len(batch) < page_size:
            break
        current_page += 1
        if not used_date_filter and current_page > 4:
            break
    return rows


def _score_received_invoice_candidate(
    full: Dict[str, Any],
    *,
    iso_received: str,
    target_amount: float,
    terms: List[str],
    tax_cid: Optional[int] = None,
) -> int:
    recv_date = minimax_api_date_to_iso(
        full.get("DateReceived") or full.get("DateIssued") or ""
    )
    if iso_received and recv_date and recv_date != iso_received:
        return -1
    amount = round(float(full.get("InvoiceAmount") or full.get("InvoiceValue") or 0.0), 2)
    if target_amount > 0 and amount > 0 and not minimax_amounts_close(amount, target_amount):
        return -1
    score = 0
    if target_amount > 0 and amount > 0 and minimax_amounts_close(amount, target_amount):
        score += 10
    ref = str(
        full.get("DocumentReference")
        or full.get("PaymentReferenceNumber")
        or full.get("Notes")
        or ""
    )
    for term in terms:
        if term and term in ref:
            score += 5
    cust = full.get("Customer") if isinstance(full.get("Customer"), dict) else {}
    if tax_cid and cust.get("ID") is not None:
        try:
            if int(cust.get("ID")) == tax_cid:
                score += 4
        except (TypeError, ValueError):
            pass
    status = str(full.get("Status") or "").upper()
    if status == "P":
        score += 3
    return score


def find_minimax_issued_invoice_posting_for_kir(
    api_base: str,
    token: str,
    organisation_id: int,
    yyyy: str,
    mm: str,
    dd: str,
    doc_sums: Dict[str, float],
    *,
    doc_id: str = "",
    match_id: str = "",
    kirkpr_fields: Optional[Dict[str, str]] = None,
) -> Optional[Dict[str, Any]]:
    iso_target = date_to_iso(yyyy, mm, dd)
    target_amount = round(float(doc_sums.get("Vrednost računa", 0.0)), 2)
    terms = _collect_minimax_search_terms(
        doc_id=doc_id, match_id=match_id, kirkpr_fields=kirkpr_fields
    )

    candidates: Dict[int, Dict[str, Any]] = {}
    for term in terms or [""]:
        try:
            rows = (
                minimax_find_items_by_search(
                    api_base, token, organisation_id, "issuedinvoicepostings", term
                )
                if term
                else minimax_fetch_items_paginated(
                    api_base, token, organisation_id, "issuedinvoicepostings"
                )
            )
        except Exception as exc:
            log_error(f"find_minimax_issued_invoice_posting_for_kir search '{term}'", exc)
            continue
        for row in rows:
            if not isinstance(row, dict):
                continue
            pid = row.get("IssuedInvoicePostingId") or row.get("ID") or row.get("Id")
            if pid is None:
                continue
            try:
                candidates[int(pid)] = row
            except (TypeError, ValueError):
                continue

    best: Optional[Dict[str, Any]] = None
    best_score = -1
    for pid, row in candidates.items():
        row_date = minimax_api_date_to_iso(row.get("Date"))
        if row_date and row_date != iso_target:
            continue
        try:
            full = minimax_get_org_resource(
                api_base, token, organisation_id, f"issuedinvoicepostings/{pid}"
            )
        except Exception as exc:
            log_error(f"find_minimax_issued_invoice_posting_for_kir GET {pid}", exc)
            continue
        if not full:
            continue
        full_date = minimax_api_date_to_iso(full.get("Date")) or row_date
        if full_date and full_date != iso_target:
            continue
        amount = _issued_posting_total_amount(full)
        if target_amount > 0 and not minimax_amounts_close(amount, target_amount):
            continue
        score = 0
        if target_amount > 0 and minimax_amounts_close(amount, target_amount):
            score += 10
        desc = str(full.get("Description") or "").lower()
        for term in terms:
            if term and term.lower() in desc:
                score += 5
        status = str(full.get("Status") or "").upper()
        if status == "P":
            score += 3
        if score > best_score:
            best_score = score
            best = full
    return best


def find_minimax_received_invoice_for_kpr(
    api_base: str,
    token: str,
    organisation_id: int,
    yyyy: str,
    mm: str,
    dd: str,
    doc_sums: Dict[str, float],
    accounts: List[Dict[str, Any]],
    *,
    doc_id: str = "",
    match_id: str = "",
    kirkpr_fields: Optional[Dict[str, str]] = None,
    customers: Optional[List[Dict[str, Any]]] = None,
) -> Optional[Dict[str, Any]]:
    fields = kirkpr_fields or {}
    iso_received = _kpr_receipt_iso_from_fields(yyyy, mm, dd, fields)
    target_amount = round(float(doc_sums.get("Vrednost računa", 0.0)), 2)
    terms = _collect_minimax_search_terms(
        doc_id=doc_id, match_id=match_id, kirkpr_fields=fields
    )

    candidates: Dict[int, Dict[str, Any]] = {}

    def _add_candidate_row(row: Dict[str, Any]) -> None:
        rid = row.get("ReceivedInvoiceId") or row.get("ID") or row.get("Id")
        if rid is None:
            return
        try:
            candidates[int(rid)] = row
        except (TypeError, ValueError):
            pass

    for term in (terms[:2] if terms else []):
        try:
            rows = minimax_find_items_by_search(
                api_base, token, organisation_id, "receivedinvoices", term
            )
        except Exception as exc:
            log_error(f"find_minimax_received_invoice_for_kpr search '{term}'", exc)
            continue
        for row in rows:
            if isinstance(row, dict):
                _add_candidate_row(row)

    try:
        for row in minimax_fetch_received_invoices_for_date(
            api_base, token, organisation_id, iso_received
        ):
            if isinstance(row, dict):
                _add_candidate_row(row)
    except Exception as exc:
        log_error("find_minimax_received_invoice_for_kpr by date", exc)

    if not candidates:
        return None

    tax_cid: Optional[int] = None
    if customers:
        tax_cid = minimax_customer_id_by_tax_number(customers, fields.get("P1") or "")

    pre_scored: List[Tuple[int, int, Dict[str, Any]]] = []
    for rid, row in candidates.items():
        score = _score_received_invoice_candidate(
            row,
            iso_received=iso_received,
            target_amount=target_amount,
            terms=terms,
            tax_cid=tax_cid,
        )
        if score >= 0:
            pre_scored.append((score, rid, row))
    if not pre_scored:
        pre_scored = [(0, rid, row) for rid, row in list(candidates.items())[:3]]
    pre_scored.sort(key=lambda item: item[0], reverse=True)

    best: Optional[Dict[str, Any]] = None
    best_score = -1
    for _pre, rid, _row in pre_scored[:3]:
        try:
            full = minimax_get_org_resource(
                api_base, token, organisation_id, f"receivedinvoices/{rid}"
            )
        except Exception as exc:
            log_error(f"find_minimax_received_invoice_for_kpr GET {rid}", exc)
            continue
        if not full:
            continue
        score = _score_received_invoice_candidate(
            full,
            iso_received=iso_received,
            target_amount=target_amount,
            terms=terms,
            tax_cid=tax_cid,
        )
        if score > best_score:
            best_score = score
            best = full
            if best_score >= 17:
                break
    if best:
        best = minimax_try_enrich_received_invoice(
            api_base, token, organisation_id, best, accounts
        )
    return best


def konto_combo_label_for_code(
    code: str,
    label_to_code: Dict[str, str],
) -> str:
    want = (code or "").strip()
    if not want:
        return ""
    for label, mapped in label_to_code.items():
        if minimax_account_codes_equal(mapped, want):
            return label
    return want


def resolve_minimax_supplier_id(customer_id_setting: str) -> Optional[int]:
    cid = (customer_id_setting or "").strip()
    if not cid:
        return None
    try:
        return int(cid)
    except ValueError as exc:
        raise ValueError(f"Minimax Customer ID (dobavitelj) mora biti številka, dobil: '{cid}'") from exc


def kirkpr_minimax_form_defaults_kir(
    payload: Dict[str, Any],
    accounts: List[Dict[str, Any]],
    doc_sums: Dict[str, float],
    *,
    yyyy: str,
    mm: str,
    dd: str,
    source_row: Optional[int],
    konto_fallback: str,
    customer_id_setting: str = "",
    kirkpr_fields: Optional[Dict[str, str]] = None,
    customers: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, str]:
    row_hint = f" vrstica {source_row}" if source_row is not None else ""
    konto = (konto_fallback or "").strip()
    revenues = payload.get("IssuedInvoicePostingRevenues") or []
    if revenues:
        code = minimax_account_code_from_ref(revenues[0].get("Account"), accounts)
        if code:
            konto = code

    placilo = _vrednost_racuna_debet_from_sums(doc_sums)
    for pay in payload.get("IssuedInvoicePostingPaymentMethods") or []:
        placilo = max(placilo, float(pay.get("Amount") or 0.0))

    customer = resolve_kir_customer_id(
        payload,
        list(customers or []),
        kirkpr_fields,
        customer_id_setting,
    )

    iso_date = str(payload.get("Date") or date_to_iso(yyyy, mm, dd))
    date_due_raw = str(payload.get("DateDue") or payload.get("Date") or "")
    date_tx_raw = str(payload.get("DateTransaction") or "")
    doc_type = str(payload.get("DocumentType") or "")

    return {
        "document_type": minimax_document_type_label_for_api(doc_type),
        "status": minimax_issued_invoice_posting_status_label(str(payload.get("Status") or "O")),
        "datum": iso_date_to_sl(iso_date),
        "datum_zapadlosti": iso_date_to_sl(date_due_raw),
        "datum_transakcije": iso_date_to_sl(date_tx_raw),
        "opis": str(
            payload.get("Description")
            or f"KIR {yyyy}-{int(mm):02d}{row_hint}"
        ),
        "sklic": str(payload.get("PaymentReference") or ""),
        "stranka_id": customer,
        "konto": konto,
        "vrednost": format_amount_sl(placilo),
        "osnova22": format_amount_sl(doc_sums.get("Davčna osnova (22%)", 0.0)),
        "davek22": format_amount_sl(doc_sums.get("Davek (22%)", 0.0)),
        "osnova95": format_amount_sl(doc_sums.get("Davčna osnova (9,5%)", 0.0)),
        "davek95": format_amount_sl(doc_sums.get("Davek (9,5%)", 0.0)),
        "neobdavcljive": format_amount_sl(_neobdavcljive_amount_from_sums(doc_sums)),
        "oproscene": format_amount_sl(_oproscene_dobave_amount_from_sums(doc_sums)),
    }


def kirkpr_minimax_form_defaults_kpr(
    payload: Dict[str, Any],
    accounts: List[Dict[str, Any]],
    doc_sums: Dict[str, float],
    *,
    yyyy: str,
    mm: str,
    dd: str,
    source_row: Optional[int],
    konto_fallback: str,
    customer_id_setting: str = "",
    kirkpr_fields: Optional[Dict[str, str]] = None,
    journal_hints: Optional[Dict[str, str]] = None,
    customers: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, str]:
    from v2.kirkpr_knjizba_form_layout import KPR_FIELD_KEY_TO_SUM_COL

    row_hint = f" vrstica {source_row}" if source_row is not None else ""
    fields = kirkpr_fields or {}
    hints = journal_hints or {}

    konto = _kpr_expense_konto_from_payload(payload, accounts, doc_sums=doc_sums)
    if konto and not minimax_account_matches_book(konto, "KPR"):
        konto = ""
    if not konto:
        konto = (hints.get("konto") or "").strip()
    if not konto:
        fallback = (konto_fallback or "").strip()
        if fallback and minimax_account_matches_book(fallback, "KPR"):
            konto = fallback

    customer = resolve_kpr_supplier_customer_id(
        payload,
        list(customers or []),
        fields,
        customer_id_setting,
    )

    iso_received = str(payload.get("DateReceived") or date_to_iso(yyyy, mm, dd))
    iso_issued = str(payload.get("DateIssued") or iso_received)
    iso_due = str(payload.get("DateDue") or "")
    if not iso_due:
        iso_due = _kpr_due_date_iso_from_fields(fields)
    if not iso_due:
        iso_due = str(hints.get("date_due") or "")

    notes_raw = str(payload.get("Notes") or "")
    notes_st, notes_vezni = _parse_kpr_notes_parts(notes_raw)
    st_listine = (fields.get("P3") or notes_st or "").strip()
    if not st_listine:
        doc_ref = str(payload.get("DocumentReference") or "").strip()
        if doc_ref and not _kpr_text_is_supplier_address(doc_ref, fields):
            st_listine = doc_ref

    minimax_doc = minimax_received_invoice_document_label(payload)
    if minimax_doc:
        vezni = minimax_doc
    else:
        vezni = (hints.get("vezni_dokument") or "").strip()
        if vezni and not _kpr_payment_reference_looks_valid(vezni):
            vezni = ""
    if _kpr_text_is_supplier_address(vezni, fields):
        vezni = ""
    if not vezni:
        cand = notes_vezni.strip()
        if cand and _kpr_payment_reference_looks_valid(cand) and not _kpr_text_is_supplier_address(cand, fields):
            vezni = cand
    if not vezni:
        pay_num = str(payload.get("PaymentReferenceNumber") or "").strip()
        if pay_num and not _kpr_text_is_supplier_address(pay_num, fields):
            if pay_num.upper().startswith("TS") or "-" in pay_num:
                vezni = pay_num
    if not vezni:
        doc_ref = str(payload.get("DocumentReference") or "").strip()
        if (
            doc_ref
            and doc_ref != st_listine
            and _kpr_payment_reference_looks_valid(doc_ref)
            and not _kpr_text_is_supplier_address(doc_ref, fields)
        ):
            vezni = doc_ref

    opis = build_kpr_minimax_notes_text(
        st_listine,
        vezni,
        fallback=st_listine or notes_raw or f"KPR {yyyy}-{int(mm):02d}{row_hint}",
    )

    sklic = str(payload.get("PaymentReferenceNumber") or "").strip()
    if _kpr_text_is_supplier_address(sklic, fields):
        sklic = ""
    if sklic and (sklic.upper().startswith("TS") or sklic == vezni):
        sklic = ""

    api_status = str(payload.get("Status") or "").upper()
    if api_status != "P" and hints.get("posted"):
        api_status = "P"
    status_label = minimax_received_invoice_status_label(api_status or "O")

    out: Dict[str, str] = {
        "status": status_label,
        "datum": iso_date_to_sl(iso_received),
        "datum_racuna": iso_date_to_sl(iso_issued),
        "datum_zapadlosti": iso_date_to_sl(iso_due),
        "st_listine": st_listine,
        "vezni_dokument": vezni,
        "opis": opis,
        "sklic": sklic,
        "dobavitelj_id": customer,
        "konto": konto,
        "vrednost": format_amount_sl(
            float(payload.get("InvoiceAmount") or doc_sums.get("Vrednost računa", 0.0))
        ),
    }
    for key, col in KPR_FIELD_KEY_TO_SUM_COL.items():
        out[key] = format_amount_sl(doc_sums.get(col, 0.0))
    return out


def kirkpr_minimax_form_defaults_from_payload(
    payload: Dict[str, Any],
    accounts: List[Dict[str, Any]],
    doc_sums: Dict[str, float],
    *,
    yyyy: str,
    mm: str,
    dd: str,
    book: str,
    source_row: Optional[int],
    konto_fallback: str,
    customer_id_setting: str = "",
    kirkpr_fields: Optional[Dict[str, str]] = None,
    journal_hints: Optional[Dict[str, str]] = None,
    customers: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, str]:
    if (book or "").strip().upper() == "KPR":
        return kirkpr_minimax_form_defaults_kpr(
            payload,
            accounts,
            doc_sums,
            yyyy=yyyy,
            mm=mm,
            dd=dd,
            source_row=source_row,
            konto_fallback=konto_fallback,
            customer_id_setting=customer_id_setting,
            kirkpr_fields=kirkpr_fields,
            journal_hints=journal_hints,
            customers=customers,
        )
    return kirkpr_minimax_form_defaults_kir(
        payload,
        accounts,
        doc_sums,
        yyyy=yyyy,
        mm=mm,
        dd=dd,
        source_row=source_row,
        konto_fallback=konto_fallback,
        customer_id_setting=customer_id_setting,
        kirkpr_fields=kirkpr_fields,
        customers=customers,
    )


def normalize_csv_header_cell(value: object) -> str:
    """FURS CSV: odstrani presledke in morebitni BOM v prvem stolpcu glave."""
    return str(value or "").strip().lstrip("\ufeff").strip()


def build_csv_column_index(header: List[str]) -> Dict[str, int]:
    """Indeks stolpcev CSV z aliasi za SUM_COLS (npr. Vrednost dobav → Osnova za DDV - skupaj)."""
    idx = {normalize_csv_header_cell(h): i for i, h in enumerate(header)}
    for col, aliases in SUM_COL_HEADER_ALIASES.items():
        if col in idx:
            continue
        for alias in aliases:
            if alias in idx:
                idx[col] = idx[alias]
                break
    if SEND_DATETIME_COL not in idx:
        for alias in SEND_DATETIME_ALIASES:
            if alias in idx:
                idx[SEND_DATETIME_COL] = idx[alias]
                break
    return idx


def required_sum_cols_for_csv() -> List[str]:
    return [
        c
        for c in SUM_COLS
        if c not in OPTIONAL_SUM_COLS
        and c not in EXCLUDED_SUM_COLS_ANALYSIS
        and c not in KPR_ONLY_SUM_COLS
        and c != NEOBDAVCLJIVE_DISPLAY_COL
    ]


def sum_cols_for_csv_aggregation() -> List[str]:
    """Stolpci za seštevke iz Blagajna.csv (brez duplikata Neobdavčljive dobave)."""
    return [
        c
        for c in SUM_COLS
        if c not in EXCLUDED_SUM_COLS_ANALYSIS and c not in KPR_ONLY_SUM_COLS
    ]


def sum_cols_for_doc_aggregation(docs: Sequence["CompareDailyDocument"]) -> List[str]:
    """Stolpci za seštevke dokumentov — KPR doda polja P8–P21."""
    cols = list(sum_cols_for_csv_aggregation())
    if any(_doc_is_kpr_entry(doc) for doc in docs):
        for col in KPR_FIELD_SUM_COLS:
            if col not in cols:
                cols.append(col)
    return cols


def _zero_sum_cols_for_docs(docs: Sequence["CompareDailyDocument"]) -> Dict[str, float]:
    if any(_doc_is_kpr_entry(doc) for doc in docs):
        return _zero_kpr_sum_cols()
    return _zero_sum_cols()


def sum_cols_for_daily_storage() -> List[str]:
    """Dnevni seštevki za drevo + Minimax (enako kot agregacija CSV)."""
    return list(sum_cols_for_csv_aggregation())


def csv_row_is_neveljaven(idx: Dict[str, int], row: List[str]) -> bool:
    """True, če je v stolpcu Veljavnost vrednost N (vrstica se ne upošteva)."""
    ci: Optional[int] = None
    for alias in CSV_VELJAVNOST_ALIASES:
        if alias in idx:
            ci = idx[alias]
            break
    if ci is None:
        return False
    val = (row[ci] if ci < len(row) else "").strip().upper()
    return val == "N"


def _csv_has_osnova_skupaj_column(idx: Dict[str, int]) -> bool:
    return "Osnova za DDV - skupaj" in idx


def _csv_has_split_tax_bases(idx: Dict[str, int]) -> bool:
    return "Davčna osnova (22%)" in idx and "Davčna osnova (9,5%)" in idx


def validate_csv_compare_columns(idx: Dict[str, int], source_id: str) -> None:
    """CSV mora imeti zahtevane stolpce; osnova za DDV je lahko stolpec ali vsota 22%+9,5%."""
    missing = [c for c in required_sum_cols_for_csv() if c not in idx]
    if missing:
        preview = ", ".join(missing[:6])
        extra = f" … (+{len(missing) - 6})" if len(missing) > 6 else ""
        raise ValueError(f"Manjkajo stolpci v {source_id}: {preview}{extra}")
    if not _csv_has_osnova_skupaj_column(idx) and not _csv_has_split_tax_bases(idx):
        raise ValueError(
            f"V {source_id} manjka «Osnova za DDV - skupaj» (ali «Vrednost dobav») "
            f"oziroma stolpca «Davčna osnova (22%)» in «Davčna osnova (9,5%)»."
        )


def _normalize_compare_sums(
    sums: Dict[str, float],
    *,
    recompute_vrednost_racuna: bool = False,
) -> Dict[str, float]:
    """Dopolni manjkajoče zneske; CSV: Vrednost računa iz komponent."""
    out = dict(sums)
    base22 = float(out.get("Davčna osnova (22%)", 0.0))
    base95 = float(out.get("Davčna osnova (9,5%)", 0.0))
    if recompute_vrednost_racuna:
        osn = float(out.get("Osnova za DDV - skupaj", 0.0))
        if abs(osn) < TREE_SUM_EPSILON and (
            abs(base22) >= TREE_SUM_EPSILON or abs(base95) >= TREE_SUM_EPSILON
        ):
            out["Osnova za DDV - skupaj"] = round(base22 + base95, 2)
    neob_raw = _neobdavcljive_amount_from_sums(out)
    if abs(neob_raw) >= TREE_SUM_EPSILON:
        out["Vrednost neobdavčljivih dobav"] = round(neob_raw, 2)
    oprosc_raw = _oproscene_dobave_amount_from_sums(out)
    if abs(oprosc_raw) >= TREE_SUM_EPSILON:
        out[OPROSCENE_DOBAV_COL] = round(oprosc_raw, 2)
    if recompute_vrednost_racuna:
        out["Vrednost računa"] = _compose_vrednost_racuna_from_components(
            out, include_neobdavcljive=True
        )
    for col in EXCLUDED_SUM_COLS_ANALYSIS:
        out[col] = 0.0
    return out


def _csv_row_sums(idx: Dict[str, int], row: List[str]) -> Dict[str, float]:
    """Vsi SUM_COLS iz vrstice CSV; Vrednost računa = vsota komponent."""
    sums = _zero_sum_cols()
    for c in SUM_COLS:
        sums[c] = parse_sum_col_from_csv_row(idx, row, c)
    return _normalize_compare_sums(sums, recompute_vrednost_racuna=True)


def _csv_entry_compare_amounts(sums: Dict[str, float]) -> Dict[str, float]:
    normalized = _normalize_compare_sums(sums)
    return {col: float(normalized.get(col, 0.0)) for col in COMPARE_DOC_FIELD_COLS}


def parse_sum_col_from_csv_row(idx: Dict[str, int], row: List[str], col: str) -> float:
    ci = idx.get(col)
    if ci is None:
        return 0.0
    v = row[ci] if ci < len(row) else ""
    return parse_amount(v)


def read_csv_from_bytes(data: bytes) -> Tuple[List[str], List[List[str]]]:
    enc = detect_encoding_bytes(data)
    text = data.decode(enc, errors="replace")
    dialect = detect_dialect(text[:8192])
    rows: List[List[str]] = []
    reader = csv.reader(text.splitlines(), dialect)
    for r in reader:
        rows.append([c.strip() for c in r])
    if not rows:
        return [], []
    rows[0] = [normalize_csv_header_cell(c) for c in rows[0]]
    return rows[0], rows[1:]


def read_csv_from_path(path: Path) -> Tuple[List[str], List[List[str]]]:
    return read_csv_from_bytes(path.read_bytes())


def month_dir_to_yyyy_mm(folder_name: str) -> Optional[Tuple[str, str]]:
    """Lokalno ime mape meseca → (YYYY, MM). Sprejme tudi 2025-1 oblike 2025-01."""
    if MONTH_DIR_RE.match(folder_name):
        ypart, mpart = folder_name.split("-", 1)
        return ypart, mpart
    m = MONTH_DIR_ONE_OR_TWO_DIGIT_MM_RE.match(folder_name)
    if m:
        return m.group("yyyy"), f"{int(m.group('mm')):02d}"
    return None


def list_month_dirs(root: Path) -> List[Path]:
    out: List[Path] = []
    try:
        for p in root.iterdir():
            if p.is_dir() and month_dir_to_yyyy_mm(p.name):
                out.append(p)
    except OSError:
        return []
    return sorted(out, key=lambda p: p.name)


def list_month_zips(root: Path) -> List[Path]:
    return sorted([p for p in root.iterdir() if p.is_file() and MONTH_ZIP_RE.match(p.name)])


def list_blagajna_zip_files(root: Path) -> List[Path]:
    """Vsi ZIP v mapi Blagajna (tudi 01.zip, ne le YYYY-MM.zip)."""
    try:
        return sorted(
            [p for p in root.iterdir() if p.is_file() and p.suffix.lower() == ".zip"],
            key=lambda p: p.name.lower(),
        )
    except OSError:
        return []


@dataclass
class ZipPackageProbe:
    name: str
    path: Path
    package_label: str
    row_count: int
    doc_count: int
    vrednost_racuna: float
    size_bytes: int
    modified_ts: float
    content_md5: str
    date_from: str
    date_to: str
    ok: bool
    error: str = ""


def _zip_package_label_from_name(name: str, context_yyyy: str = "") -> str:
    period = zip_file_period_ym(name, context_yyyy)
    if period:
        return f"{period[0]}-{period[1]}"
    return name


def zip_file_period_ym(name: str, context_yyyy: str) -> Optional[Tuple[str, str]]:
    """Obdobje ZIP: 2026-01.zip → (2026,01); 01.zip + leto 2026 → (2026,01)."""
    m = MONTH_ZIP_RE.match(name)
    if m:
        return m.group("yyyy"), f"{int(m.group('mm')):02d}"
    m2 = SHORT_MONTH_ZIP_RE.match(name)
    yyyy = (context_yyyy or "").strip()
    if m2 and re.fullmatch(r"\d{4}", yyyy):
        return yyyy, f"{int(m2.group('mm')):02d}"
    return None


def infer_blagajna_context_year(root: Path) -> str:
    years: List[str] = []
    for zp in list_blagajna_zip_files(root):
        m = MONTH_ZIP_RE.match(zp.name)
        if m:
            years.append(m.group("yyyy"))
    if years:
        return max(years)
    return str(datetime.now().year)


def list_zips_for_calendar_period(root: Path, yyyy: str, mm: str) -> List[Path]:
    mm_norm = f"{int(mm):02d}"
    out: List[Path] = []
    for zp in list_blagajna_zip_files(root):
        if zip_file_period_ym(zp.name, yyyy) == (yyyy, mm_norm):
            out.append(zp)
    return sorted(out, key=lambda p: (0 if MONTH_ZIP_RE.match(p.name) else 1, p.name.lower()))


def zip_calendar_month_stats(zp: Path, csv_name: str, yyyy: str, mm: str) -> Tuple[int, float]:
    """Število računov in Vrednost računa v ZIP za koledarski mesec (datum izdaje)."""
    mm_norm = f"{int(mm):02d}"
    try:
        with zipfile.ZipFile(zp, "r") as zf:
            member = find_csv_member_in_zip(zf, csv_name)
            if not member:
                return 0, 0.0
            header, rows = read_csv_from_bytes(zf.read(member))
    except (zipfile.BadZipFile, OSError):
        return 0, 0.0
    if not header:
        return 0, 0.0
    idx = build_csv_column_index(header)
    if DATE_COL not in idx:
        return 0, 0.0
    date_i = idx[DATE_COL]
    vr_i = idx.get("Vrednost računa")
    n_docs = 0
    total = 0.0
    for r in rows:
        if csv_row_is_neveljaven(idx, r):
            continue
        ym = extract_month(r[date_i] if date_i < len(r) else "")
        if ym != (yyyy, mm_norm):
            continue
        n_docs += 1
        if vr_i is not None and vr_i < len(r):
            total += parse_amount(r[vr_i])
    return n_docs, round(total, 2)


def probe_blagajna_zip(zp: Path, csv_name: str, *, context_yyyy: str = "") -> ZipPackageProbe:
    """Hitri pregled ZIP (število računov, VR, hash vsebine)."""
    base = ZipPackageProbe(
        name=zp.name,
        path=zp,
        package_label=_zip_package_label_from_name(zp.name, context_yyyy),
        row_count=0,
        doc_count=0,
        vrednost_racuna=0.0,
        size_bytes=0,
        modified_ts=0.0,
        content_md5="",
        date_from="",
        date_to="",
        ok=False,
    )
    try:
        st = zp.stat()
        base.size_bytes = int(st.st_size)
        base.modified_ts = float(st.st_mtime)
    except OSError as exc:
        base.error = str(exc)
        return base
    try:
        with zipfile.ZipFile(zp, "r") as zf:
            member = find_csv_member_in_zip(zf, csv_name)
            if not member:
                base.error = f"Ni CSV `{csv_name}`"
                return base
            raw = zf.read(member)
            base.content_md5 = hashlib.md5(raw).hexdigest()
            header, rows = read_csv_from_bytes(raw)
            if not header:
                base.error = "Prazna CSV"
                return base
            idx = build_csv_column_index(header)
            if DATE_COL not in idx:
                base.error = f"Manjka `{DATE_COL}`"
                return base
            date_i = idx[DATE_COL]
            vr_i = idx.get("Vrednost računa")
            base.row_count = len(rows)
            dates: List[Tuple[int, int, int]] = []
            for r in rows:
                if csv_row_is_neveljaven(idx, r):
                    continue
                base.doc_count += 1
                if vr_i is not None and vr_i < len(r):
                    base.vrednost_racuna += parse_amount(r[vr_i])
                if date_i < len(r):
                    ymd = extract_day((r[date_i] or "").strip())
                    if ymd:
                        dates.append((int(ymd[0]), int(ymd[1]), int(ymd[2])))
            if dates:
                dates.sort()
                d0, d1 = dates[0], dates[-1]
                base.date_from = f"{d0[2]:02d}.{d0[1]:02d}.{d0[0]}"
                base.date_to = f"{d1[2]:02d}.{d1[1]:02d}.{d1[0]}"
            base.vrednost_racuna = round(base.vrednost_racuna, 2)
            base.ok = True
    except zipfile.BadZipFile:
        base.error = "Poškodovan ZIP"
    except Exception as exc:
        base.error = str(exc)
    return base


def scan_blagajna_zips(root: Path, csv_name: str, *, context_yyyy: Optional[str] = None) -> List[ZipPackageProbe]:
    ctx = context_yyyy or infer_blagajna_context_year(root)
    return [probe_blagajna_zip(zp, csv_name, context_yyyy=ctx) for zp in list_blagajna_zip_files(root)]


def default_zip_enabled_map(probes: Sequence[ZipPackageProbe], saved: Dict[str, bool]) -> Dict[str, bool]:
    """Privzeto: YYYY-MM.zip vključen; identična vsebina — samo prvi."""
    out: Dict[str, bool] = {}
    hash_owner: Dict[str, str] = {}
    for p in sorted(probes, key=lambda x: (0 if MONTH_ZIP_RE.match(x.name) else 1, x.name.lower())):
        if p.name in saved:
            out[p.name] = bool(saved[p.name])
            if p.content_md5 and out[p.name]:
                hash_owner.setdefault(p.content_md5, p.name)
            continue
        if p.content_md5 and p.content_md5 in hash_owner:
            out[p.name] = False
            continue
        enabled = bool(p.ok and MONTH_ZIP_RE.match(p.name))
        out[p.name] = enabled
        if enabled and p.content_md5:
            hash_owner[p.content_md5] = p.name
    return out


def data_root_has_month_sources(root: Path) -> bool:
    if not root.is_dir():
        return False
    try:
        return bool(list_month_dirs(root) or list_month_zips(root))
    except OSError:
        return False


def try_resolve_single_nested_month_data_root(root_path: Path) -> Optional[Path]:
    """
    Če v korenu ni mesečnih map/ZIPov, poišči natanko ENO podlogo, kjer so (npr. …/Firma/Blagajna/2025-01).
    Če jih je več, ne ugibaj — uporabnik naj izbere ožjo pot.
    """
    if data_root_has_month_sources(root_path):
        return None
    hits: List[Path] = []
    try:
        children = [p for p in root_path.iterdir() if p.is_dir()]
    except OSError:
        return None
    for child in sorted(children, key=lambda p: p.name.lower()):
        low = child.name.lower()
        if low == "blagajna" and data_root_has_month_sources(child):
            hits.append(child)
            continue
        if data_root_has_month_sources(child):
            hits.append(child)
            continue
        nested_b = child / "Blagajna"
        if nested_b.is_dir() and data_root_has_month_sources(nested_b):
            hits.append(nested_b)
    return hits[0] if len(hits) == 1 else None


def resolve_analysis_data_root(root_path: Path) -> Path:
    """Poišči mapo z YYYY-MM mapami/zip (firma ali Blagajna).

    Vrstni red kandidatov je pomemben:
    • Če je izbrana mapa sama Blagajna, najprej ta mapa — sicer ima starš
      pogosto še naključne YYYY-MM mape/ZIP-e (brez CSV) in starš zmaga narobe.
    • Če je izbrana mapa firme, najprej podmapa Blagajna (standard iz Trops),
      nato koren (posamezni uporabniki imajo YYYY-MM neposredno v mapi firme).
    """
    root_path = root_path.expanduser().resolve()
    candidates: List[Path] = []
    if root_path.name.lower() == "blagajna":
        candidates.extend([root_path, root_path.parent])
    else:
        blagajna = root_path / "Blagajna"
        if blagajna.is_dir():
            candidates.append(blagajna)
        candidates.append(root_path)

    seen: set = set()
    ordered: List[Path] = []
    for cand in candidates:
        key = str(cand).lower()
        if key not in seen:
            seen.add(key)
            ordered.append(cand)

    probe_lines: List[str] = []
    for cand in ordered:
        if not cand.is_dir():
            probe_lines.append(f"  • {cand} | ni mape")
            continue
        try:
            dirs_l = list_month_dirs(cand)
            zips_l = list_month_zips(cand)
            n_dirs, n_zips = len(dirs_l), len(zips_l)
            has_layout = bool(dirs_l or zips_l)
        except OSError as exc:
            probe_lines.append(f"  • {cand} | napaka pri branju: {exc}")
            continue
        probe_lines.append(
            f"  • {cand} | podmape YYYY-MM={n_dirs} | zip meseci={n_zips} "
            f"| ustreza strukturi={'da' if has_layout else 'ne'}"
        )

    picked: Optional[Path] = None
    for cand in ordered:
        if data_root_has_month_sources(cand):
            picked = cand
            break
    if picked is None:
        for cand in ordered:
            nested = try_resolve_single_nested_month_data_root(cand)
            if nested is not None:
                picked = nested.resolve()
                probe_lines.append(f"  • (samodejno) enotna podmapa z mesečnimi podatki: {picked}")
                break
    if picked is None:
        picked = ordered[0]

    log_info(
        "resolve_analysis_data_root | izbrane poti:\n"
        + "\n".join(probe_lines)
        + f"\n  => uporabljena mapa za analizo: {picked}"
    )
    return picked


def find_csv_member_in_zip(z: zipfile.ZipFile, csv_name: str) -> Optional[str]:
    target = csv_name.lower()
    for name in z.namelist():
        if name.lower().endswith("/"):
            continue
        if Path(name).name.lower() == target:
            return name
    return None


def build_monthly_sums(root: Path, csv_name: str, include_zips: bool, report: Report) -> Dict[Tuple[str, str], Dict[str, float]]:
    result: Dict[Tuple[str, str], Dict[str, float]] = {}

    def add_rows(source_id: str, fallback_yyyy: str, fallback_mm: str, header: List[str], rows: List[List[str]]) -> None:
        if not header:
            report.empty_csv_sources.append(source_id)
            return
        idx = build_csv_column_index(header)
        if DATE_COL not in idx:
            report.missing_date_column.append(source_id)
            return
        missing = [c for c in required_sum_cols_for_csv() if c not in idx]
        if missing:
            report.missing_columns[source_id] = missing
            return

        try:
            validate_csv_compare_columns(idx, source_id)
        except ValueError as exc:
            report.missing_columns[source_id] = [str(exc)]
            return
        if not rows:
            report.empty_csv_sources.append(source_id)
            report.rows_read_per_source[source_id] = 0
            return
        date_i = idx[DATE_COL]
        report.rows_read_per_source[source_id] = len(rows)
        agg_cols = sum_cols_for_csv_aggregation()
        for r in rows:
            if csv_row_is_neveljaven(idx, r):
                continue
            date_val = r[date_i] if date_i < len(r) else ""
            ym = extract_month(date_val)
            yyyy, mm = ym if ym is not None else (fallback_yyyy, fallback_mm)
            key = (yyyy, mm)
            if key not in result:
                result[key] = {c: 0.0 for c in SUM_COLS}
            row_sums = _csv_row_sums(idx, r)
            for c in agg_cols:
                result[key][c] += row_sums[c]

    for month_dir in list_month_dirs(root):
        csv_path = month_dir / csv_name
        if not csv_path.exists():
            report.missing_csv_dirs.append(month_dir)
            continue
        header, rows = read_csv_from_path(csv_path)
        ym = month_dir_to_yyyy_mm(month_dir.name)
        if ym is None:
            continue
        yyyy, mm = ym
        add_rows(str(csv_path), yyyy, mm, header, rows)

    if include_zips:
        for zp in list_month_zips(root):
            m = MONTH_ZIP_RE.match(zp.name)
            assert m is not None
            yyyy, mm = m.group("yyyy"), m.group("mm")
            try:
                with zipfile.ZipFile(zp, "r") as zf:
                    member = find_csv_member_in_zip(zf, csv_name)
                    if not member:
                        report.missing_csv_zips.append(zp)
                        continue
                    header, rows = read_csv_from_bytes(zf.read(member))
                    add_rows(f"{zp}::{member}", yyyy, mm, header, rows)
            except zipfile.BadZipFile:
                report.missing_csv_zips.append(zp)

    return result


def build_daily_sums(root: Path, csv_name: str, include_zips: bool, report: Report) -> Dict[Tuple[str, str, str], Dict[str, float]]:
    result: Dict[Tuple[str, str, str], Dict[str, float]] = {}

    def add_rows(source_id: str, fallback_yyyy: str, fallback_mm: str, header: List[str], rows: List[List[str]]) -> None:
        if not header:
            report.empty_csv_sources.append(source_id)
            return
        idx = build_csv_column_index(header)
        if DATE_COL not in idx:
            report.missing_date_column.append(source_id)
            return
        missing = [c for c in required_sum_cols_for_csv() if c not in idx]
        if missing:
            report.missing_columns[source_id] = missing
            return

        try:
            validate_csv_compare_columns(idx, source_id)
        except ValueError as exc:
            report.missing_columns[source_id] = [str(exc)]
            return
        if not rows:
            report.empty_csv_sources.append(source_id)
            report.rows_read_per_source[source_id] = 0
            return
        date_i = idx[DATE_COL]
        report.rows_read_per_source[source_id] = len(rows)
        store_cols = sum_cols_for_daily_storage()
        for r in rows:
            if csv_row_is_neveljaven(idx, r):
                continue
            date_val = r[date_i] if date_i < len(r) else ""
            ymd = extract_day(date_val)
            if ymd is None:
                yyyy, mm = fallback_yyyy, fallback_mm
                dd = "01"
            else:
                yyyy, mm, dd = ymd
            key = (yyyy, mm, dd)
            if key not in result:
                result[key] = {c: 0.0 for c in SUM_COLS}
            row_sums = _csv_row_sums(idx, r)
            for c in store_cols:
                result[key][c] += row_sums[c]

    for month_dir in list_month_dirs(root):
        csv_path = month_dir / csv_name
        if not csv_path.exists():
            report.missing_csv_dirs.append(month_dir)
            continue
        header, rows = read_csv_from_path(csv_path)
        ym = month_dir_to_yyyy_mm(month_dir.name)
        if ym is None:
            continue
        yyyy, mm = ym
        add_rows(str(csv_path), yyyy, mm, header, rows)

    if include_zips:
        for zp in list_month_zips(root):
            m = MONTH_ZIP_RE.match(zp.name)
            assert m is not None
            yyyy, mm = m.group("yyyy"), m.group("mm")
            try:
                with zipfile.ZipFile(zp, "r") as zf:
                    member = find_csv_member_in_zip(zf, csv_name)
                    if not member:
                        report.missing_csv_zips.append(zp)
                        continue
                    header, rows = read_csv_from_bytes(zf.read(member))
                    add_rows(f"{zp}::{member}", yyyy, mm, header, rows)
            except zipfile.BadZipFile:
                report.missing_csv_zips.append(zp)

    return result


def build_daily_docs(
    root: Path,
    csv_name: str,
    include_zips: bool,
    report: Report,
    selected_zip_names: Optional[Sequence[str]] = None,
) -> DailyDocsMap:
    result: DailyDocsMap = {}

    def add_rows(source_id: str, fallback_yyyy: str, fallback_mm: str, header: List[str], rows: List[List[str]]) -> None:
        if not header:
            report.empty_csv_sources.append(source_id)
            return
        idx = build_csv_column_index(header)
        if DATE_COL not in idx:
            report.missing_date_column.append(source_id)
            return
        missing = [c for c in required_sum_cols_for_csv() if c not in idx]
        if missing:
            report.missing_columns[source_id] = missing
            return

        try:
            validate_csv_compare_columns(idx, source_id)
        except ValueError as exc:
            report.missing_columns[source_id] = [str(exc)]
            return
        if not rows:
            report.empty_csv_sources.append(source_id)
            report.rows_read_per_source[source_id] = 0
            return

        date_i = idx[DATE_COL]
        doc_id_i, doc_type_i = _find_csv_compare_doc_columns(header)
        report.rows_read_per_source[source_id] = len(rows)
        for row_idx, r in enumerate(rows, start=1):
            if csv_row_is_neveljaven(idx, r):
                continue
            parsed = _csv_row_to_compare_doc(
                r,
                header=header,
                idx=idx,
                date_i=date_i,
                doc_id_i=doc_id_i,
                doc_type_i=doc_type_i,
                fallback_yyyy=fallback_yyyy,
                fallback_mm=fallback_mm,
                source_row=row_idx,
            )
            if parsed is None:
                continue
            day_key, doc = parsed
            doc.source_id = source_id
            zip_name = Path(source_id.split("::", 1)[0]).name if "::" in source_id else ""
            if MONTH_ZIP_RE.match(zip_name):
                doc.package_ym = (fallback_yyyy, f"{int(fallback_mm):02d}")
            else:
                doc.package_ym = (day_key[0], day_key[1])
            result.setdefault(day_key, []).append(doc)

    for month_dir in list_month_dirs(root):
        csv_path = month_dir / csv_name
        if not csv_path.exists():
            report.missing_csv_dirs.append(month_dir)
            continue
        header, rows = read_csv_from_path(csv_path)
        ym = month_dir_to_yyyy_mm(month_dir.name)
        if ym is None:
            continue
        yyyy, mm = ym
        add_rows(str(csv_path), yyyy, mm, header, rows)

    if include_zips:
        zip_allow: Optional[set] = None
        if selected_zip_names is not None:
            zip_allow = {str(n) for n in selected_zip_names}
        for zp in list_blagajna_zip_files(root):
            if zip_allow is not None and zp.name not in zip_allow:
                continue
            m = MONTH_ZIP_RE.match(zp.name)
            if m:
                yyyy, mm = m.group("yyyy"), m.group("mm")
            else:
                yyyy, mm = "", ""
            try:
                with zipfile.ZipFile(zp, "r") as zf:
                    member = find_csv_member_in_zip(zf, csv_name)
                    if not member:
                        report.missing_csv_zips.append(zp)
                        continue
                    header, rows = read_csv_from_bytes(zf.read(member))
                    if not yyyy or not mm:
                        ym = _infer_dominant_month_from_csv_rows(header, rows)
                        if ym:
                            yyyy, mm = ym
                    fb_y, fb_m = yyyy or "0000", mm or "01"
                    add_rows(f"{zp}::{member}", fb_y, fb_m, header, rows)
            except zipfile.BadZipFile:
                report.missing_csv_zips.append(zp)

    result = _normalize_daily_docs(result)
    return deduplicate_daily_docs_map(result, report)


def _infer_dominant_month_from_csv_rows(
    header: List[str], rows: List[List[str]]
) -> Optional[Tuple[str, str]]:
    """Za ZIP brez YYYY-MM v imenu: prevladujoči mesec po datumu izdaje računa."""
    idx = build_csv_column_index(header)
    if DATE_COL not in idx:
        return None
    date_i = idx[DATE_COL]
    counts: Dict[Tuple[str, str], int] = {}
    for r in rows:
        if csv_row_is_neveljaven(idx, r):
            continue
        ym = extract_month(r[date_i] if date_i < len(r) else "")
        if ym:
            counts[ym] = counts.get(ym, 0) + 1
    if not counts:
        return None
    return max(counts.items(), key=lambda kv: kv[1])[0]


def _xml_local_tag(element: ET.Element) -> str:
    tag = element.tag
    return tag.split("}", 1)[-1] if "}" in tag else tag


def _kir_find_child(parent: ET.Element, local_name: str) -> Optional[ET.Element]:
    """Poišči otroka po imenu (z ali brez XML namespace)."""
    el = parent.find(f"{{{KIRKPR_XML_NS}}}{local_name}")
    if el is not None:
        return el
    for child in parent:
        if _xml_local_tag(child) == local_name:
            return child
    return None


def _kirkpr_elem_amount(parent: ET.Element, tag: str) -> float:
    el = _kir_find_child(parent, tag)
    if el is None or el.text is None:
        return 0.0
    return parse_amount(el.text)


def _kirkpr_elem_text(parent: ET.Element, tag: str) -> str:
    el = _kir_find_child(parent, tag)
    if el is None or el.text is None:
        return ""
    return el.text.strip()


def _ddv_xml_kir_rows(root: ET.Element) -> List[ET.Element]:
    """Vrstice knjige izdanih računov (Lista_KIR/KIR)."""
    rows = root.findall(f".//{{{KIRKPR_XML_NS}}}Lista_KIR/{{{KIRKPR_XML_NS}}}KIR")
    if rows:
        return rows
    for el in root.iter():
        if _xml_local_tag(el) != "Lista_KIR":
            continue
        return [child for child in el if _xml_local_tag(child) == "KIR"]
    return []


def _ddv_xml_kpr_rows(root: ET.Element) -> List[ET.Element]:
    """Vrstice knjige prejetih računov (Lista_KPR/KPR)."""
    rows = root.findall(f".//{{{KIRKPR_XML_NS}}}Lista_KPR/{{{KIRKPR_XML_NS}}}KPR")
    if rows:
        return rows
    for el in root.iter():
        if _xml_local_tag(el) != "Lista_KPR":
            continue
        return [child for child in el if _xml_local_tag(child) == "KPR"]
    return []


def _iso_date_to_ymd(iso_date: str) -> Optional[Tuple[str, str, str]]:
    s = (iso_date or "").strip()
    m = ISO_DATE_RE.match(s)
    if m:
        return m.group("yyyy"), f"{int(m.group('mm')):02d}", f"{int(m.group('dd')):02d}"
    return extract_day(s)


def _blagajna_kir_day_from_text(text: str) -> Optional[Tuple[str, str, str]]:
    """npr. P3 = 'blagajna za 2026 - 04 - 01' → (2026, 04, 01)."""
    s = (text or "").strip()
    m = BLAGAJNA_KIR_DAY_RE.search(s)
    if not m:
        return None
    return (
        m.group("yyyy"),
        f"{int(m.group('mm')):02d}",
        f"{int(m.group('dd')):02d}",
    )


def _kir_entry_ymd(kir: ET.Element) -> Optional[Tuple[str, str, str]]:
    """Datum KIR vrstice: P2 (ISO) ali P3 ('blagajna za YYYY - MM - DD')."""
    ymd = _iso_date_to_ymd(_kirkpr_elem_text(kir, "P2"))
    if ymd is not None:
        return ymd
    return _blagajna_kir_day_from_text(_kirkpr_elem_text(kir, "P3"))


def _kpr_entry_ymd(kpr: ET.Element) -> Optional[Tuple[str, str, str]]:
    """Datum KPR vrstice: P2 (datum prejema) ali P4/P5."""
    for tag in ("P2", "P4", "P5"):
        ymd = _iso_date_to_ymd(_kirkpr_elem_text(kpr, tag))
        if ymd is not None:
            return ymd
    return None


_KPR_XML_TAGS: Tuple[Tuple[str, str], ...] = (
    ("P8", "P8 Blago in storitve"),
    ("P9", "P9 Samoobdavčitev"),
    ("P10", "P10 Pridobitev blaga"),
    ("P11", "P11 Prejete storitve"),
    ("P12", "P12 Nepremičnine"),
    ("P13", "P13 Druga OS"),
    ("P14", "P14 Oproščene nabave"),
    ("P15", "P15 Oproščene nepremičnine"),
    ("P16", "P16 Oproščena druga OS"),
    ("P17", "P17 DDV se ne odbija"),
    ("P18", "P18 DDV 22%"),
    ("P19", "P19 DDV 9,5%"),
    ("P20", "P20 DDV 5%"),
    ("P21", "P21 Pavšalno nadomestilo"),
)


def find_xml_members_in_zip(z: zipfile.ZipFile) -> List[str]:
    members = [
        name
        for name in z.namelist()
        if not name.endswith("/") and Path(name).suffix.lower() == ".xml"
    ]
    members.sort(key=lambda n: (0 if Path(n).name.upper().startswith("KR-") else 1, n.lower()))
    return members


def _kirkpr_period_token(yyyy: str, mm: str) -> str:
    y, m = _normalize_month_key(yyyy, mm)
    return f"{y}{m}"


def edavki_kirkpr_zip_name(yyyy: str, mm: str) -> str:
    """Ciljno ime ZIP v mapi Blagajna (eDavki KIR/KPR)."""
    return f"Evidenca eDavki KIRKPR_{_kirkpr_period_token(yyyy, mm)}.zip"


def minimax_kirkpr_xml_name(yyyy: str, mm: str) -> str:
    """Ciljno ime XML v mapi DDV (Minimax KIR/KPR)."""
    return f"Evidenca minimax KIRKPR_{_kirkpr_period_token(yyyy, mm)}.xml"


def minimax_kirkpr_zip_name(yyyy: str, mm: str) -> str:
    """Ciljno ime ZIP v mapi DDV (Minimax KIR/KPR)."""
    return f"Evidenca minimax KIRKPR_{_kirkpr_period_token(yyyy, mm)}.zip"


def kirkpr_minimax_prenos_paths(
    *,
    trops_base: Path,
    zst_value: str,
    blagajna_dir: Path,
    yyyy: str,
    mm: str,
    source: str,
) -> Tuple[Path, Path]:
    """Ciljna mapa in datoteka za prenos iz Minimax ObracunDDV (eDavki → Blagajna ZIP, Minimax → DDV)."""
    source_u = (source or "minimax").strip().lower()
    if source_u == "edavki":
        dest_dir = blagajna_dir.expanduser().resolve()
        target = dest_dir / edavki_kirkpr_zip_name(yyyy, mm)
    else:
        dest_dir = minimax_ddv_dir(trops_base, zst_value)
        target = dest_dir / minimax_kirkpr_xml_name(yyyy, mm)
    return dest_dir, target


def kirkpr_zip_search_names(yyyy: str, mm: str) -> Tuple[str, ...]:
    token = _kirkpr_period_token(yyyy, mm)
    return (
        edavki_kirkpr_zip_name(yyyy, mm),
        f"Evidenca KIRKPR_{token}.zip",
        KIRKPR_ZIP_LEGACY_NAME,
    )


def resolve_kirkpr_zip_path(search_roots: Sequence[Path], yyyy: str, mm: str) -> Optional[Path]:
    """Poišči Evidenca eDavki KIRKPR_YYYYMM.zip (ali starejša imena) v podanih mapah."""
    names = kirkpr_zip_search_names(yyyy, mm)
    seen: set = set()
    for root in search_roots:
        root = root.expanduser().resolve()
        if not root.is_dir():
            continue
        for name in names:
            candidate = (root / name).resolve()
            key = str(candidate).lower()
            if key in seen:
                continue
            seen.add(key)
            if candidate.is_file() and _furs_is_valid_zip_file(candidate):
                return candidate
    return None


def minimax_kirkpr_dir(trops_base: Path, zst_value: str) -> Path:
    """Legacy podmapa EvidencaKIRKPR (starejši izvozi)."""
    zst_folder = format_zst_folder(zst_value)
    if not zst_folder:
        raise ValueError("Manjka veljavna Zšt za mapo Minimax KIR/KPR.")
    return trops_base / zst_folder / MINIMAX_KIRKPR_FOLDER


def minimax_ddv_dir(trops_base: Path, zst_value: str) -> Path:
    """Mapa DDV za izvoz Minimax KIR/KPR (Evidenca minimax KIRKPR_YYYYMM.xml)."""
    zst_folder = format_zst_folder(zst_value)
    if not zst_folder:
        raise ValueError("Manjka veljavna Zšt za mapo DDV.")
    return trops_base / zst_folder / "DDV"


def _kirkpr_xml_month_from_root(root: ET.Element) -> Optional[Tuple[str, str]]:
    glava = root.find(f"{{{KIRKPR_XML_NS}}}Glava")
    if glava is None:
        for el in root.iter():
            if _xml_local_tag(el) == "Glava":
                glava = el
                break
    if glava is None:
        return None
    ymd = _iso_date_to_ymd(_kirkpr_elem_text(glava, "OBDOBJE_OD"))
    if ymd is None:
        return None
    return ymd[0], ymd[1]


def _kirkpr_xml_month_from_file(path: Path) -> Optional[Tuple[str, str]]:
    try:
        root = ET.parse(path).getroot()
    except (ET.ParseError, OSError):
        return None
    if _xml_local_tag(root) != "DDV_KIR_KPR":
        return None
    return _kirkpr_xml_month_from_root(root)


def _file_head_contains_ddv_kir_kpr(path: Path) -> bool:
    try:
        with path.open("rb") as handle:
            return b"DDV_KIR_KPR" in handle.read(8000)
    except OSError:
        return False


def resolve_minimax_kirkpr_xml_path(
    trops_base: Path,
    zst_value: str,
    yyyy: str,
    mm: str,
) -> Optional[Path]:
    """Poišči Minimax KIR/KPR XML v Trops/…/DDV (ali legacy EvidencaKIRKPR)."""
    y, m = _normalize_month_key(yyyy, mm)
    token = f"{y}{m}"
    search_specs: List[Tuple[Path, Tuple[str, ...]]] = [
        (
            minimax_ddv_dir(trops_base, zst_value),
            (
                minimax_kirkpr_xml_name(yyyy, mm),
                f"KIRKPR_{y}-{m}.xml",
                f"KIRKPR_{token}.xml",
            ),
        ),
        (
            minimax_kirkpr_dir(trops_base, zst_value),
            (
                minimax_kirkpr_xml_name(yyyy, mm),
                f"KIRKPR_{y}-{m}.xml",
                f"KIRKPR_{token}.xml",
                f"KR-{token}.xml",
            ),
        ),
    ]
    for folder, names in search_specs:
        if not folder.is_dir():
            continue
        for name in names:
            candidate = folder / name
            if candidate.is_file() and _file_head_contains_ddv_kir_kpr(candidate):
                return candidate
    best: Optional[Path] = None
    best_mtime = 0.0
    for folder, _names in search_specs:
        if not folder.is_dir():
            continue
        for candidate in folder.glob("*.xml"):
            if not _file_head_contains_ddv_kir_kpr(candidate):
                continue
            file_ym = _kirkpr_xml_month_from_file(candidate)
            if file_ym == (y, m):
                mtime = candidate.stat().st_mtime
                if mtime >= best_mtime:
                    best, best_mtime = candidate, mtime
                continue
            stem = candidate.stem
            if f"{y}-{m}" in stem or token in stem.replace("-", ""):
                mtime = candidate.stat().st_mtime
                if mtime >= best_mtime:
                    best, best_mtime = candidate, mtime
    return best


def resolve_minimax_kirkpr_file_path(
    trops_base: Path,
    zst_value: str,
    yyyy: str,
    mm: str,
) -> Optional[Path]:
    """Poišči Minimax KIR/KPR XML ali ZIP v Trops/…/DDV (ne v Blagajna)."""
    xml_path = resolve_minimax_kirkpr_xml_path(trops_base, zst_value, yyyy, mm)
    if xml_path is not None:
        return xml_path
    y, m = _normalize_month_key(yyyy, mm)
    token = f"{y}{m}"
    ddv_dir = minimax_ddv_dir(trops_base, zst_value)
    if not ddv_dir.is_dir():
        return None
    zip_names = (
        minimax_kirkpr_zip_name(yyyy, mm),
        minimax_kirkpr_xml_name(yyyy, mm).replace(".xml", ".zip"),
        f"KIRKPR_{y}-{m}.zip",
        f"KIRKPR_{token}.zip",
    )
    seen: set = set()
    for name in zip_names:
        candidate = (ddv_dir / name).resolve()
        key = str(candidate).lower()
        if key in seen:
            continue
        seen.add(key)
        if candidate.is_file() and _furs_is_valid_zip_file(candidate):
            return candidate
    best: Optional[Path] = None
    best_mtime = 0.0
    for candidate in ddv_dir.glob("*.zip"):
        if not _furs_is_valid_zip_file(candidate):
            continue
        stem = candidate.stem.lower()
        if token in stem.replace("-", "") or f"{y}-{m}" in stem or "kirkpr" in stem:
            mtime = candidate.stat().st_mtime
            if mtime >= best_mtime:
                best, best_mtime = candidate, mtime
    return best


def load_kirkpr_aggregates_from_xml_path(
    path: Path,
) -> Tuple[
    Dict[Tuple[str, str], Dict[str, float]],
    Dict[Tuple[str, str, str], Dict[str, float]],
    DailyDocsMap,
]:
    path = path.expanduser().resolve()
    xml_data = path.read_bytes()
    monthly, daily, _meta = build_kirkpr_sums_from_xml(xml_data, source_id=str(path))
    daily_docs = build_kirkpr_daily_docs_from_xml(xml_data, source_id=str(path))
    return monthly, daily, _normalize_daily_docs(daily_docs)


def kirkir_entry_to_sum_cols(entry: ET.Element) -> Dict[str, float]:
    """KIR vrstica (Lista_KIR/KIR) -> SUM_COLS.

    Vrednost računa = P7 + P10 + P14 + P15.
    Davčna osnova (22 %) = P14 / 0,22; Davčna osnova (9,5 %) = P15 / 0,095.
    """
    p7 = _kirkpr_elem_amount(entry, "P7")
    p8 = _kirkpr_elem_amount(entry, "P8")
    p9 = _kirkpr_elem_amount(entry, "P9")
    p10 = _kirkpr_elem_amount(entry, "P10")
    p11 = _kirkpr_elem_amount(entry, "P11")
    p12 = _kirkpr_elem_amount(entry, "P12")
    p13 = _kirkpr_elem_amount(entry, "P13")
    p14 = _kirkpr_elem_amount(entry, "P14")
    p15 = _kirkpr_elem_amount(entry, "P15")
    p16 = _kirkpr_elem_amount(entry, "P16")

    base22 = round(p14 / KIRKPR_VAT_RATE_22, 2) if p14 else 0.0
    base95 = round(p15 / KIRKPR_VAT_RATE_95, 2) if p15 else 0.0
    base5 = round(p16 / KIRKPR_VAT_RATE_05, 2) if p16 else 0.0
    exempt_no_deduction = p9
    special_supplies = p8 + p11 + p12 + p13

    sums = {c: 0.0 for c in SUM_COLS}
    sums["Vrednost računa"] = round(p7 + p10 + p14 + p15, 2)
    sums["Davčna osnova (22%)"] = base22
    sums["Davek (22%)"] = p14
    sums["Davčna osnova (9,5%)"] = base95
    sums["Davek (9,5%)"] = p15
    sums["Vrednost neobdavčljivih dobav"] = p10
    sums["Osnova za DDV-ostalo"] = base5
    sums["DDV-ostalo"] = p16
    sums["Vrednost oproš_enih dobav"] = exempt_no_deduction
    sums["Vrednost dobav (posebne ureditve)"] = special_supplies
    sums["Osnova za DDV - skupaj"] = p7
    out = _normalize_compare_sums(sums, recompute_vrednost_racuna=False)
    out["Osnova za DDV - skupaj"] = p7
    return out


def kpr_entry_to_sum_cols(entry: ET.Element) -> Dict[str, float]:
    """KPR vrstica (Lista_KPR/KPR) -> SUM_COLS po eDavki shemi (P8–P21)."""
    field_vals: Dict[str, float] = {}
    for xml_tag, col_name in _KPR_XML_TAGS:
        field_vals[col_name] = _kirkpr_elem_amount(entry, xml_tag)

    nabave_brez_ddv = round(
        sum(
            field_vals[col_name]
            for tag, col_name in _KPR_XML_TAGS
            if tag in ("P8", "P9", "P10", "P11", "P12", "P13")
        ),
        2,
    )
    oproscene = round(
        sum(
            field_vals[col_name]
            for tag, col_name in _KPR_XML_TAGS
            if tag in ("P14", "P15", "P16")
        ),
        2,
    )
    p17 = field_vals["P17 DDV se ne odbija"]
    p18 = field_vals["P18 DDV 22%"]
    p19 = field_vals["P19 DDV 9,5%"]
    p20 = field_vals["P20 DDV 5%"]
    p21 = field_vals["P21 Pavšalno nadomestilo"]
    odbitni_ddv = round(p18 + p19 + p20 + p21, 2)
    vrednost = round(nabave_brez_ddv + odbitni_ddv + p17 + oproscene, 2)

    sums = _zero_kpr_sum_cols()
    for _tag, col_name in _KPR_XML_TAGS:
        sums[col_name] = field_vals[col_name]
    sums["Vrednost računa"] = vrednost
    sums["Osnova za DDV - skupaj"] = nabave_brez_ddv
    sums["Davčna osnova (22%)"] = nabave_brez_ddv
    sums["Davek (22%)"] = p18
    sums["Davek (9,5%)"] = p19
    sums["DDV-ostalo"] = p20
    sums["Znesek pavšalnega nadomestila (8%)"] = p21
    sums[OPROSCENE_DOBAV_COL] = oproscene
    sums["Ostali davki/dajatve"] = p17
    out = _normalize_compare_sums(sums, recompute_vrednost_racuna=False)
    out["Osnova za DDV - skupaj"] = nabave_brez_ddv
    out["Vrednost računa"] = vrednost
    for _tag, col_name in _KPR_XML_TAGS:
        out[col_name] = field_vals[col_name]
    return out


def _kirkpr_entry_compare_amounts(entry: ET.Element) -> Dict[str, float]:
    """Zneski KIR vrstice za primerjavo (P3, P7, P10, P14, P15 ↔ blagajna.csv)."""
    sums = kirkir_entry_to_sum_cols(entry)
    return {col: float(sums.get(col, 0.0)) for col in COMPARE_DOC_FIELD_COLS}


def _kpr_entry_compare_amounts(entry: ET.Element) -> Dict[str, float]:
    """Zneski KPR vrstice za prikaz in primerjavo."""
    sums = kpr_entry_to_sum_cols(entry)
    return {col: float(sums.get(col, 0.0)) for col in COMPARE_DOC_FIELD_COLS}


def build_kirkpr_sums_from_xml(
    xml_data: bytes,
    *,
    source_id: str = "KIRKPR.xml",
) -> Tuple[Dict[Tuple[str, str], Dict[str, float]], Dict[Tuple[str, str, str], Dict[str, float]], Dict[str, Any]]:
    """Seštevki iz DDV_KIR_KPR XML — samo Lista_KIR/KIR (KPR se preskoči)."""
    try:
        root = ET.fromstring(xml_data)
    except ET.ParseError as exc:
        raise ValueError(f"Neveljaven XML ({source_id}): {exc}") from exc

    if _xml_local_tag(root) != "DDV_KIR_KPR":
        raise ValueError(
            f"Nepričakovana koren XML '{_xml_local_tag(root)}' v {source_id} "
            f"(pričakovan DDV_KIR_KPR, shema {KIRKPR_XML_NS})."
        )

    glava = root.find(f"{{{KIRKPR_XML_NS}}}Glava")
    obd_od_el = glava.find(f"{{{KIRKPR_XML_NS}}}OBDOBJE_OD") if glava is not None else None
    obd_do_el = glava.find(f"{{{KIRKPR_XML_NS}}}OBDOBJE_DO") if glava is not None else None
    obd_od = (obd_od_el.text or "").strip() if obd_od_el is not None else ""
    obd_do = (obd_do_el.text or "").strip() if obd_do_el is not None else ""

    monthly: Dict[Tuple[str, str], Dict[str, float]] = {}
    daily: Dict[Tuple[str, str, str], Dict[str, float]] = {}
    kir_rows = _ddv_xml_kir_rows(root)
    skipped_no_date = 0

    for kir in kir_rows:
        ymd = _kir_entry_ymd(kir)
        if ymd is None:
            skipped_no_date += 1
            continue
        yyyy, mm, dd = ymd
        row_sums = kirkir_entry_to_sum_cols(kir)
        month_key = (yyyy, mm)
        day_key = (yyyy, mm, dd)
        if month_key not in monthly:
            monthly[month_key] = {c: 0.0 for c in SUM_COLS}
        if day_key not in daily:
            daily[day_key] = {c: 0.0 for c in SUM_COLS}
        for col in SUM_COLS:
            monthly[month_key][col] += row_sums[col]
            daily[day_key][col] += row_sums[col]

    meta: Dict[str, Any] = {
        "source_id": source_id,
        "obdobje_od": obd_od,
        "obdobje_do": obd_do,
        "kir_rows": len(kir_rows),
        "skipped_no_date": skipped_no_date,
        "compare_amount_note": KIR_COMPARE_AMOUNT_LOG,
    }
    return monthly, daily, meta


def _kirkpr_kir_entry_to_compare_doc(
    kir: ET.Element,
    *,
    source_row: int,
) -> Optional[Tuple[Tuple[str, str, str], "CompareDailyDocument"]]:
    """KIR vrstica -> (day_key, CompareDailyDocument).

    P3: identifikator (npr. IR:AEON-MK-97846 ali 'blagajna za 2026 - 04 - 01').
    Datum: P2 (ISO) ali iz besedila P3.
    """
    ymd = _kir_entry_ymd(kir)
    if ymd is None:
        return None
    yyyy, mm, dd = ymd
    p3 = _kirkpr_elem_text(kir, "P3")
    doc_id = _compare_doc_id_from_raw(p3)
    if not doc_id:
        doc_id = _compare_doc_id_from_raw(_kirkpr_elem_text(kir, "P1"))
    if not doc_id:
        doc_id = p3
    if not doc_id:
        doc_id = f"KIR #{source_row}"
    match_id = _compare_doc_id_from_raw(p3) or _compare_doc_id_from_raw(_kirkpr_elem_text(kir, "P1")) or p3
    sums = kirkir_entry_to_sum_cols(kir)
    compare_amounts = _kirkpr_entry_compare_amounts(kir)
    if _blagajna_kir_day_from_text(p3):
        doc_type = "KIR (dnevni seštevek blagajne)"
    elif p3:
        doc_type = f"KIR (storitev {p3})"
    else:
        doc_type = "KIR"
    p2 = _kirkpr_elem_text(kir, "P2")
    doc = CompareDailyDocument(
        doc_id=doc_id,
        doc_type=doc_type,
        sums=sums,
        compare_amounts=compare_amounts,
        source_row=source_row,
        match_id=match_id,
        sent_datetime=p2,
        kirkpr_fields=_kirkpr_entry_field_map(kir),
    )
    return (yyyy, mm, dd), doc


def build_kirkpr_daily_docs_from_xml(
    xml_data: bytes,
    *,
    source_id: str = "KIRKPR.xml",
) -> Dict[Tuple[str, str, str], List["CompareDailyDocument"]]:
    try:
        root = ET.fromstring(xml_data)
    except ET.ParseError as exc:
        raise ValueError(f"Neveljaven XML ({source_id}): {exc}") from exc

    if _xml_local_tag(root) != "DDV_KIR_KPR":
        raise ValueError(
            f"Nepričakovana koren XML '{_xml_local_tag(root)}' v {source_id} "
            f"(pričakovan DDV_KIR_KPR, shema {KIRKPR_XML_NS})."
        )

    daily_docs: Dict[Tuple[str, str, str], List[CompareDailyDocument]] = {}
    kir_rows = _ddv_xml_kir_rows(root)
    for row_idx, kir in enumerate(kir_rows, start=1):
        parsed = _kirkpr_kir_entry_to_compare_doc(kir, source_row=row_idx)
        if parsed is None:
            continue
        day_key, doc = parsed
        daily_docs.setdefault(day_key, []).append(doc)
    return daily_docs


def _read_kirkpr_xml_bytes_from_zip(zip_path: Path) -> Tuple[bytes, str]:
    zip_path = zip_path.expanduser().resolve()
    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            members = find_xml_members_in_zip(zf)
            if not members:
                raise ValueError(f"V ZIP {zip_path.name} ni XML datoteke (pričakovan KR-*.xml).")
            member = members[0]
            return zf.read(member), member
    except zipfile.BadZipFile as exc:
        raise ValueError(f"Neveljaven ZIP: {zip_path}") from exc


def _kirkpr_xml_rows(root: ET.Element, book: str) -> List[ET.Element]:
    book_u = (book or "KIR").strip().upper()
    if book_u == "KPR":
        return _ddv_xml_kpr_rows(root)
    return _ddv_xml_kir_rows(root)


def _set_kirkpr_elem_text(parent: ET.Element, tag: str, value: str) -> None:
    val = (value or "").strip()
    el = _kir_find_child(parent, tag)
    if not val:
        if el is not None:
            parent.remove(el)
        return
    if el is None:
        el = ET.SubElement(parent, f"{{{KIRKPR_XML_NS}}}{tag}")
    el.text = val


def load_kirkpr_row_field_map(
    file_path: Path,
    book: str,
    source_row: int,
    *,
    xml_member: Optional[str] = None,
) -> Dict[str, str]:
    """Preberi P polja ene vrstice iz DDV_KIR_KPR XML (ZIP ali datoteka)."""
    file_path = file_path.expanduser().resolve()
    row_i = int(source_row)
    if row_i < 1:
        raise ValueError(f"Neveljavna vrstica: {source_row}")
    if file_path.suffix.lower() == ".zip":
        xml_data, member = _read_kirkpr_xml_bytes_from_zip(file_path)
        if xml_member:
            with zipfile.ZipFile(file_path, "r") as zf:
                xml_data = zf.read(xml_member)
            member = xml_member
    else:
        xml_data = file_path.read_bytes()
        member = None
    root = ET.fromstring(xml_data)
    rows = _kirkpr_xml_rows(root, book)
    if row_i > len(rows):
        raise ValueError(f"Vrstica {row_i} ne obstaja (skupaj {len(rows)}).")
    return _kirkpr_entry_field_map(rows[row_i - 1])


def save_kirkpr_row_field_map(
    file_path: Path,
    book: str,
    source_row: int,
    fields: Dict[str, str],
    *,
    xml_member: Optional[str] = None,
) -> None:
    """Zapiši P polja ene vrstice nazaj v DDV_KIR_KPR XML (ZIP ali datoteka)."""
    file_path = file_path.expanduser().resolve()
    row_i = int(source_row)
    if row_i < 1:
        raise ValueError(f"Neveljavna vrstica: {source_row}")

    if file_path.suffix.lower() == ".zip":
        with zipfile.ZipFile(file_path, "r") as zf:
            member = xml_member or (find_xml_members_in_zip(zf) or [None])[0]
            if not member:
                raise ValueError(f"V ZIP {file_path.name} ni XML.")
            xml_data = zf.read(member)
            other_files = {n: zf.read(n) for n in zf.namelist() if n != member}
        root = ET.fromstring(xml_data)
        rows = _kirkpr_xml_rows(root, book)
        if row_i > len(rows):
            raise ValueError(f"Vrstica {row_i} ne obstaja (skupaj {len(rows)}).")
        entry = rows[row_i - 1]
        for tag, val in fields.items():
            if tag.startswith("P"):
                _set_kirkpr_elem_text(entry, tag, val)
        try:
            ET.indent(root, space="  ")
        except AttributeError:
            pass
        new_xml = ET.tostring(root, encoding="utf-8", xml_declaration=True)
        tmp = file_path.with_suffix(file_path.suffix + ".tmp")
        with zipfile.ZipFile(tmp, "w", compression=zipfile.ZIP_DEFLATED) as zout:
            zout.writestr(member, new_xml)
            for name, data in other_files.items():
                zout.writestr(name, data)
        tmp.replace(file_path)
        log_info(f"save_kirkpr_row_field_map | zip={file_path} member={member} row={row_i}")
        return

    root = ET.fromstring(file_path.read_bytes())
    rows = _kirkpr_xml_rows(root, book)
    if row_i > len(rows):
        raise ValueError(f"Vrstica {row_i} ne obstaja (skupaj {len(rows)}).")
    entry = rows[row_i - 1]
    for tag, val in fields.items():
        if tag.startswith("P"):
            _set_kirkpr_elem_text(entry, tag, val)
    try:
        ET.indent(root, space="  ")
    except AttributeError:
        pass
    file_path.write_bytes(ET.tostring(root, encoding="utf-8", xml_declaration=True))
    log_info(f"save_kirkpr_row_field_map | xml={file_path} row={row_i}")


def build_kirkpr_daily_docs_from_zip(
    zip_path: Path,
) -> Dict[Tuple[str, str, str], List[CompareDailyDocument]]:
    xml_data, member = _read_kirkpr_xml_bytes_from_zip(zip_path)
    return build_kirkpr_daily_docs_from_xml(
        xml_data,
        source_id=f"{zip_path}::{member}",
    )


def _kirkpr_kpr_entry_to_compare_doc(
    kpr: ET.Element,
    *,
    source_row: int,
) -> Optional[Tuple[Tuple[str, str, str], "CompareDailyDocument"]]:
    ymd = _kpr_entry_ymd(kpr)
    if ymd is None:
        return None
    yyyy, mm, dd = ymd
    p3 = _kirkpr_elem_text(kpr, "P3")
    doc_id = _compare_doc_id_from_raw(p3)
    if not doc_id:
        doc_id = _compare_doc_id_from_raw(_kirkpr_elem_text(kpr, "P1"))
    if not doc_id:
        doc_id = p3
    if not doc_id:
        doc_id = f"KPR #{source_row}"
    match_id = _compare_doc_id_from_raw(p3) or _compare_doc_id_from_raw(_kirkpr_elem_text(kpr, "P1")) or p3
    sums = kpr_entry_to_sum_cols(kpr)
    compare_amounts = _kpr_entry_compare_amounts(kpr)
    if p3:
        doc_type = f"KPR (prejeti račun {p3})"
    else:
        doc_type = "KPR (prejeti račun)"
    p2 = _kirkpr_elem_text(kpr, "P2")
    p4 = _kirkpr_elem_text(kpr, "P4")
    sent_datetime = p2 or p4
    doc = CompareDailyDocument(
        doc_id=doc_id,
        doc_type=doc_type,
        sums=sums,
        compare_amounts=compare_amounts,
        source_row=source_row,
        match_id=match_id,
        sent_datetime=sent_datetime,
        kirkpr_fields=_kirkpr_entry_field_map(kpr),
    )
    return (yyyy, mm, dd), doc


