def open_minimax_uvoz_in_browser(organisation_id: Optional[int] = None) -> str:
    """Odpri Minimax uvoz — takoj nov zavihek v Chrome (brez CDP iskanja)."""
    url = minimax_web_uvoz_url(organisation_id)
    if _furs_open_url_in_existing_chrome(url):
        log_info(f"open_minimax_uvoz_in_browser | --new-tab | org={organisation_id} | {url}")
        return url
    webbrowser.open(url)
    log_info(f"open_minimax_uvoz_in_browser | webbrowser | org={organisation_id} | {url}")
