def _minimax_knjizenje_fill_search_js(
    *,
    date_from_sl: str,
    date_to_sl: str,
    opis: str = "",
) -> str:
    """Hitri zajem 2026-10-11: DatumOd/Do + Najdi na KnjizenjeIzdanegaRacuna.aspx."""
    d0 = json.dumps(str(date_from_sl or "").strip())
    d1 = json.dumps(str(date_to_sl or "").strip())
    op = json.dumps(str(opis or "").strip())
    return f"""
(() => {{
  const setVal = (sel, v) => {{
    const el = document.querySelector(sel);
    if (!el) return false;
    el.focus();
    el.value = String(v || '');
    el.dispatchEvent(new Event('input', {{ bubbles: true }}));
    el.dispatchEvent(new Event('change', {{ bubbles: true }}));
    el.dispatchEvent(new Event('blur', {{ bubbles: true }}));
    return true;
  }};
  const odOk = setVal('#PPC_ctl04_ctl00_ctl01_I_DatumOd', {d0});
  const doOk = setVal('#PPC_ctl04_ctl00_ctl01_I_DatumDo', {d1});
  const opis = {op};
  let opisOk = true;
  if (opis) opisOk = setVal('#PPC_ctl04_ctl00_ctl01_I_Opis', opis);
  const btn = document.querySelector('#PPC_ctl04_ctl00_B_Search, button#PPC_ctl04_ctl00_B_Search');
  let clicked = false;
  if (btn) {{
    try {{ btn.click(); clicked = true; }} catch (e) {{
      try {{
        btn.dispatchEvent(new MouseEvent('click', {{ bubbles: true, cancelable: true, view: window }}));
        clicked = true;
      }} catch (e2) {{}}
    }}
  }}
  // Hitri zajem (prava firma): rezultati v #TSearchFrame tudi brez Datum Od/Do —
  // Najdi je dovolj, če smo v pravi org (navbar Eko-romatika…).
  const tbl = document.querySelector('#TSearchFrame');
  const rows = tbl ? tbl.querySelectorAll('tr').length : 0;
  const nav = String(document.body ? document.body.innerText : '').slice(0, 800);
  return {{
    ok: !!(clicked || (odOk && doOk)),
    odOk, doOk, opisOk, clicked,
    tableRows: rows,
    title: String(document.title || ''),
    path: String(location.pathname || ''),
    navSample: nav,
  }};
}})()
"""


def _minimax_knjizenje_verify_js(organisation_name: str = "") -> str:
    """Preveri navbar firmo + vrstice v #TSearchFrame (ciljni zajem Eko-romatika)."""
    onm = json.dumps(str(organisation_name or "").strip().lower())
    return f"""
(() => {{
  const norm = (s) => String(s || '')
    .normalize('NFD').replace(/[\\u0300-\\u036f]/g, '')
    .replace(/\\s+/g, ' ').trim().toLowerCase();
  const want = norm({onm});
  const body = norm(document.body ? document.body.innerText : '');
  const navLink = document.querySelector(
    'ul.mm-menu a[href*="ZacetekOrganizacije"], span.mm-header-dropdown a, a[href*="ZacetekOrganizacije"]'
  );
  const navText = norm(navLink ? navLink.innerText : '');
  const firmOk = !want || navText.includes(want) || body.includes(want);
  const tbl = document.querySelector('#TSearchFrame');
  const rows = tbl ? Array.from(tbl.querySelectorAll('tr')).map(tr =>
    Array.from(tr.querySelectorAll('th,td')).map(c => (c.innerText || '').trim()).filter(Boolean)
  ).filter(r => r.length) : [];
  const hasData = rows.some(r => r.some(c => /blagajna|iztr|\\d{{1,2}}\\.\\d{{1,2}}\\.\\d{{4}}/i.test(c)));
  return {{
    ok: !!(firmOk && (hasData || rows.length > 1)),
    firmOk, hasData,
    navText: (navLink && navLink.innerText || '').trim().slice(0, 80),
    rowCount: rows.length,
    sample: rows.slice(0, 4),
  }};
}})()
"""


def _minimax_knjizenje_cdp_fill_search(
    *,
    date_from_sl: str,
    date_to_sl: str,
    opis: str = "",
    wait_sec: float = 8.0,
) -> Tuple[bool, str]:
    """V že odprtem Minimax Chrome/Edge (:9223) vpiši obdobje in klikni Najdi."""
    js = _minimax_knjizenje_fill_search_js(
        date_from_sl=date_from_sl, date_to_sl=date_to_sl, opis=opis
    )
    deadline = time.time() + max(2.0, float(wait_sec))
    last_err = "ni zavihka Knjiženje"
    while time.time() < deadline:
        found = None
        for host, port in _minimax_cdp_iter_endpoints():
            for row in _chrome_cdp_list_pages(host, int(port)):
                if str(row.get("type") or "").lower() not in ("", "page"):
                    continue
                page_url = str(row.get("url") or "").lower()
                title = str(row.get("title") or "").lower()
                if "knjizenjeizdanegaracuna" not in page_url.replace("%", ""):
                    if "knjizenje" not in page_url and "izdanih" not in title:
                        continue
                ws = str(row.get("webSocketDebuggerUrl") or "").strip()
                if not ws:
                    continue
                found = (host, int(port), row, ws)
                break
            if found:
                break
        if not found:
            time.sleep(0.4)
            continue
        host, port, page, ws = found
        try:
            _chrome_cdp_activate_page(host, port, page)
            result = _chrome_cdp_runtime_evaluate(ws, js, timeout_sec=10.0) or {}
            if isinstance(result, dict) and result.get("ok"):
                log_info(
                    f"_minimax_knjizenje_cdp_fill_search | OK | {date_from_sl}–{date_to_sl} | "
                    f"{host}:{port}"
                )
                return True, "OK — Datum Od/Do + Najdi"
            last_err = f"fill partial: {result!r}"
        except Exception as exc:
            last_err = str(exc)
            log_error("_minimax_knjizenje_cdp_fill_search", exc)
        time.sleep(0.5)
    return False, last_err


def _minimax_session_navigate_knjizenje(
    url: str,
    *,
    organisation_name: str = "",
) -> Tuple[bool, str]:
    """V OBSTOJEČI Minimax CDP seji navigiraj na Knjiženje — brez novega zavihka."""
    found = _minimax_pick_best_session_tab(organisation_name=organisation_name)
    if not found:
        return False, "ni obstoječega Minimax zavihka"
    h, p, page = found
    page, ws = _minimax_refresh_page_ws(h, int(p), page)
    if not ws:
        return False, "ni websocket na obstoječem zavihku"
    u = str((page or {}).get("url") or "").lower()
    _chrome_cdp_activate_page(h, int(p), page or {})
    if "knjizenjeizdanegaracuna" in u or (
        "knjizenje" in u and "izdan" in u
    ):
        return True, f"reuse_existing_tab :{p}"
    try:
        _chrome_cdp_navigate(ws, url, timeout_sec=18.0)
        time.sleep(1.1)
        return True, f"navigate_existing_tab :{p}"
    except Exception as exc:
        log_error("_minimax_session_navigate_knjizenje", exc)
        return False, str(exc)


def open_minimax_knjizenje_after_api(
    *,
    organisation_id: Optional[int],
    yyyy: str,
    mm: str,
    date_from_sl: Optional[str] = None,
    date_to_sl: Optional[str] = None,
    opis: str = "",
    organisation_name: str = "",
) -> str:
    """Po API: pregled Knjiženja v samostojnem WebView2 (video OdpriKnjiženje).

    HARD Moje org → naziv firme → Knjiženje IR/iztržkov → Najdi (Od/Do).
    Brez Chrome vtičnika / Bridge. Uvoz KN WebView2 (3.0.42) ostane nespremenjen.
    """
    oid = int(organisation_id) if organisation_id and int(organisation_id) > 0 else 0
    org_name = (organisation_name or "").strip()
    if not org_name and oid:
        org_name = (lookup_minimax_org_name(oid) or "").strip()
    url = minimax_web_knjizenje_url(oid if oid else None)
    try:
        mm_i = int(str(mm).strip())
        yyyy_s = str(yyyy).strip()
        d0 = (date_from_sl or "").strip() or f"01.{mm_i:02d}.{yyyy_s}"
        d1 = (date_to_sl or "").strip() or last_day_of_month_sl(yyyy_s, f"{mm_i:02d}")
    except (TypeError, ValueError):
        d0 = (date_from_sl or "").strip()
        d1 = (date_to_sl or "").strip()

    def _work() -> None:
        try:
            from v2.minimax_uvoz_config import load_minimax_uvoz_config
            from v2.minimax_webview2 import MinimaxUvozWebView2Controller, WebView2Unavailable
            from v2.version_journal import APP_ROOT

            cfg = load_minimax_uvoz_config()
            port = int(cfg.get("remote_debugging_port") or 9333)
            login_user, login_pass = "", ""
            try:
                login_user, login_pass = load_minimax_web_login_credentials_from_settings()
            except Exception:
                login_user, login_pass = "", ""

            def _log(m: str) -> None:
                log_info(f"open_minimax_knjizenje_after_api | {m}")

            ctrl = MinimaxUvozWebView2Controller(APP_ROOT)
            result = ctrl.open_knjizenje(
                organisation_id=oid if oid else None,
                organisation_name=org_name,
                date_from=d0 or "",
                date_to=d1 or "",
                opis=str(opis or "").strip(),
                remote_debugging_port=port,
                start_url=MINIMAX_WEB_ZACETEK_URL,
                login_username=login_user or "",
                login_password=login_pass or "",
                log=_log,
            )
            log_info(
                f"open_minimax_knjizenje_after_api | WebView2 OK | "
                f"org={result.get('organisation') or org_name} | "
                f"{d0}–{d1} | najdi={((result.get('najdi') or {}).get('ok'))} | {url}"
            )
        except Exception as exc:
            # WebView2Unavailable / Timeout / Runtime — log, ne zruši API uspeha
            try:
                from v2.minimax_webview2 import WebView2Unavailable

                if isinstance(exc, WebView2Unavailable):
                    log_error("open_minimax_knjizenje_after_api WebView2", exc)
                else:
                    log_error("open_minimax_knjizenje_after_api", exc)
            except Exception:
                log_error("open_minimax_knjizenje_after_api", exc)

    threading.Thread(
        target=_work, daemon=True, name="MinimaxKnjizenjeAfterApi"
    ).start()
    log_info(
        f"open_minimax_knjizenje_after_api | start WebView2 | org={oid or '-'} | "
        f"{org_name or '-'} | {d0 or '?'}–{d1 or '?'} | {url}"
    )
    return url


def _minimax_uvoz_select_podatki_kn_js() -> str:
    """
    Hitri zajem korak 1: na praznem Uvoz strani izberi Podatki = Knjižbe in DDV (KN).
    Šele potem se razširi obrazec (radio, datum, IR, datoteka).
    """
    tip_js = json.dumps(MINIMAX_WEB_UVOZ_TIP)
    return f"""
(() => {{
  const tipWant = {tip_js};
  const norm = (s) => String(s || '').replace(/\\s+/g, ' ').trim().toLowerCase();
  const steps = [];
  const hasForm = Boolean(document.querySelector('#PPC_EPC_DC_I_Datum') || document.querySelector('#PPC_EPC_DC_I_Moznosti_1'));
  const vp = document.querySelector('#PPC_EPC_DC_I_VrstaPrometa_h');
  if (vp && String(vp.value || '').toUpperCase() === 'KN' && hasForm) {{
    return {{ ok: true, steps: ['KN_already'], has_form: true }};
  }}

  const setNative = (el, val) => {{
    if (!el) return false;
    try {{
      const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value');
      if (desc && desc.set) desc.set.call(el, val); else el.value = val;
    }} catch (e) {{ el.value = val; }}
    el.dispatchEvent(new Event('input', {{ bubbles: true }}));
    el.dispatchEvent(new Event('change', {{ bubbles: true }}));
    el.dispatchEvent(new Event('blur', {{ bubbles: true }}));
    return true;
  }};

  // Skrito polje (ASP.NET)
  if (vp) {{ setNative(vp, 'KN'); steps.push('KN_h'); }}

  // Najdi mm-select za »Podatki:«
  const inputs = Array.from(document.querySelectorAll('input.mm-select-input, input[type=text]'));
  let podatkiInp = null;
  for (const inp of inputs) {{
    const wrap = inp.closest('.input-group, .form-group, .mm-form-group, td, div') || inp.parentElement;
    let lab = '';
    try {{
      const prev = wrap && wrap.previousElementSibling;
      lab = ((prev && (prev.innerText || prev.textContent)) || '') + ' ' + (inp.getAttribute('aria-label') || '') + ' ' + (inp.id || '');
      const lbl = wrap && wrap.querySelector && wrap.querySelector('label');
      if (lbl) lab += ' ' + (lbl.innerText || '');
      // label[for]
      if (inp.id) {{
        const fl = document.querySelector('label[for=\"' + inp.id + '\"]');
        if (fl) lab += ' ' + (fl.innerText || '');
      }}
    }} catch (e) {{}}
    if (/podatk/i.test(lab) || /VrstaPrometa/i.test(inp.id || '')) {{
      podatkiInp = inp;
      break;
    }}
  }}
  if (!podatkiInp && inputs.length) {{
    // prvi prazen mm-select na strani Uvoz = Podatki
    podatkiInp = inputs.find(i => !(i.value || '').trim()) || inputs[0];
  }}

  const openAndPick = (inp) => {{
    if (!inp) return false;
    try {{ inp.focus(); inp.click(); }} catch (e) {{}}
    const btn = (inp.closest('.input-group') || inp.parentElement || document)
      .querySelector('button, .mm-select-btn, .dropdown-toggle, span.caret, i.fa-caret-down');
    if (btn) {{ try {{ btn.click(); }} catch (e) {{}} }}
    setNative(inp, tipWant);
    try {{
      inp.dispatchEvent(new KeyboardEvent('keydown', {{ key: 'ArrowDown', bubbles: true }}));
      inp.dispatchEvent(new KeyboardEvent('keydown', {{ key: 'Enter', bubbles: true }}));
    }} catch (e) {{}}

    const opts = Array.from(document.querySelectorAll(
      'li, .mm-select-item, .dropdown-item, [role=option], a, span, div'
    ));
    const hit = opts.find(el => {{
      const t = norm(el.innerText || el.textContent || el.getAttribute('title'));
      if (!t || t.length > 80) return false;
      return t.includes('knjižbe in ddv') || t.includes('knjizbe in ddv') || t === 'kn' || /\\bkn\\b/.test(t);
    }});
    if (hit) {{
      try {{ hit.click(); steps.push('KN_opt'); return true; }} catch (e) {{}}
    }}
    steps.push('KN_typed');
    return Boolean(inp.value);
  }};

  const picked = openAndPick(podatkiInp);
  const formNow = Boolean(document.querySelector('#PPC_EPC_DC_I_Datum') || document.querySelector('#PPC_EPC_DC_I_Moznosti_1'));
  return {{
    ok: picked || formNow || steps.includes('KN_h'),
    steps,
    has_form: formNow,
    podatki: podatkiInp ? (podatkiInp.value || '') : '',
    vp: vp ? (vp.value || '') : ''
  }};
}})()
""".strip()


def _minimax_uvoz_fill_form_js(
    *,
    date_sl: str,
    opis: str,
    vrsta_label: str = MINIMAX_WEB_UVOZ_VRSTA_TEMELJNICE,
    vrsta_id: str = MINIMAX_WEB_UVOZ_VRSTA_TEMELJNICE_ID,
) -> str:
    date_js = json.dumps(date_sl)
    opis_js = json.dumps(str(opis))
    vrsta_js = json.dumps(vrsta_label)
    vrsta_id_js = json.dumps(str(vrsta_id or MINIMAX_WEB_UVOZ_VRSTA_TEMELJNICE_ID))
    tip_js = json.dumps(MINIMAX_WEB_UVOZ_TIP)
    return f"""
(() => {{
  const dateVal = {date_js};
  const opisVal = {opis_js};
  const vrstaWant = {vrsta_js};
  const vrstaId = {vrsta_id_js};
  const tipWant = {tip_js};
  const setNative = (el, val) => {{
    if (!el) return false;
    try {{
      const proto = window.HTMLInputElement && window.HTMLInputElement.prototype;
      const desc = proto && Object.getOwnPropertyDescriptor(proto, 'value');
      if (desc && desc.set) desc.set.call(el, val);
      else el.value = val;
    }} catch (e) {{ el.value = val; }}
    el.dispatchEvent(new Event('input', {{ bubbles: true }}));
    el.dispatchEvent(new Event('change', {{ bubbles: true }}));
    el.dispatchEvent(new Event('blur', {{ bubbles: true }}));
    return true;
  }};
  const steps = [];
  const hasForm = Boolean(document.querySelector('#PPC_EPC_DC_I_Datum'));
  if (!hasForm) {{
    return {{ ok: false, reason: 'need_KN', steps, path: location.pathname || '' }};
  }}
  // Možnosti: Podatki naj se uvozijo
  const radio = document.querySelector('#PPC_EPC_DC_I_Moznosti_1');
  if (radio) {{
    radio.checked = true;
    radio.click();
    radio.dispatchEvent(new Event('change', {{ bubbles: true }}));
    steps.push('uvoz');
  }}
  // Datum
  if (setNative(document.querySelector('#PPC_EPC_DC_I_Datum'), dateVal)) steps.push('datum');
  // Opis = blagajna MM.YYYY
  if (setNative(document.querySelector('#PPC_EPC_DC_I_Opis'), opisVal)) steps.push('opis');
  // Skrito KN (če še ni)
  const vp = document.querySelector('#PPC_EPC_DC_I_VrstaPrometa_h');
  if (vp) {{
    setNative(vp, 'KN');
    steps.push('KN');
  }}
  // Vrsta temeljnice — skrito ID 2 (IR)
  const vt = document.querySelector('#PPC_EPC_DC_I_VrstaTemeljniceID_h');
  if (vt) {{
    setNative(vt, vrstaId);
    steps.push('vrsta_h');
  }}
  // Vidni mm-select: IR
  try {{
    const inputs = Array.from(document.querySelectorAll('input.mm-select-input'));
    for (const inp of inputs) {{
      const wrap = inp.closest('.input-group') || inp.parentElement;
      const label = (wrap && wrap.previousElementSibling)
        ? (wrap.previousElementSibling.textContent || '')
        : '';
      const blob = (label + ' ' + (inp.getAttribute('aria-label') || '')).toLowerCase();
      if (/temeljnic|vrsta/.test(blob) || (!inp.value && vrstaWant)) {{
        inp.focus();
        setNative(inp, vrstaWant);
        inp.dispatchEvent(new KeyboardEvent('keydown', {{ key: 'Enter', bubbles: true }}));
        // klik opcije v seznamu
        const opts = Array.from(document.querySelectorAll('li, .mm-select-item, [role=option]'));
        const hit = opts.find(el => /izdani\\s*račun|\\bir\\b/i.test((el.innerText || '').trim()));
        if (hit) try {{ hit.click(); }} catch (e) {{}}
        steps.push('vrsta_ui');
        break;
      }}
    }}
  }} catch (e) {{}}
  return {{
    ok: steps.includes('datum') || steps.includes('opis') || steps.includes('uvoz'),
    steps,
    date: (document.querySelector('#PPC_EPC_DC_I_Datum') || {{}}).value || '',
    opis: (document.querySelector('#PPC_EPC_DC_I_Opis') || {{}}).value || '',
    vrsta_id: (document.querySelector('#PPC_EPC_DC_I_VrstaTemeljniceID_h') || {{}}).value || '',
    path: location.pathname || ''
  }};
}})()
""".strip()


def _minimax_uvoz_click_import_js() -> str:
    return """
(() => {
  const btn = document.querySelector('#PPC_EPC_DC_B_Import');
  if (!btn) return { ok: false, reason: 'no_import_btn' };
  btn.click();
  return { ok: true, clicked: true };
})()
""".strip()


def _minimax_uvoz_read_report_js() -> str:
    return """
(() => {
  const heading = Array.from(document.querySelectorAll('h1,h2,h3,legend,fieldset'))
    .map(e => (e.innerText || e.textContent || '').trim())
    .find(t => /poro[cč]ilo o uvozu/i.test(t));
  const showBtn = document.querySelector('#PPC_EPC_DC_A_PrikaziTemeljnico');
  const table = document.querySelector('table.mm-table');
  const rows = [];
  let errors = 0;
  if (table) {
    for (const tr of table.querySelectorAll('tr')) {
      const cells = Array.from(tr.querySelectorAll('th,td')).map(c => (c.innerText || '').trim());
      if (cells.length >= 4) {
        rows.push(cells);
        const label = (cells[0] || '').toLowerCase();
        if (/temeljnic|vrstica|ddv/.test(label)) {
          const n = parseInt(String(cells[3] || '0').replace(/\\D/g, ''), 10);
          if (!isNaN(n)) errors += n;
        }
      }
    }
  }
  const body = (document.body && document.body.innerText) || '';
  const hasReport = Boolean(heading) || /Poročilo o uvozu podatkov/i.test(body) || Boolean(showBtn);
  return {
    ok: hasReport,
    has_report: hasReport,
    errors,
    rows,
    show_temeljnica: Boolean(showBtn),
    url: location.href || '',
    title: document.title || ''
  };
})()
""".strip()


def _minimax_uvoz_click_show_temeljnica_js() -> str:
    return """
(() => {
  const btn = document.querySelector('#PPC_EPC_DC_A_PrikaziTemeljnico');
  if (!btn) return { ok: false };
  btn.click();
  return { ok: true };
})()
""".strip()


def _chrome_cdp_set_file_input(ws_url: str, selector: str, file_path: Path) -> bool:
    """CDP DOM.setFileInputFiles — brez Save As / file dialog."""
    path = str(Path(file_path).resolve())
    if not Path(path).is_file():
        return False
    try:
        _chrome_cdp_send(ws_url, "DOM.enable", {}, timeout_sec=5.0)
        doc = _chrome_cdp_send(ws_url, "DOM.getDocument", {"depth": 1}, timeout_sec=8.0)
        root_id = ((doc or {}).get("root") or {}).get("nodeId")
        if not root_id:
            return False
        q = _chrome_cdp_send(
            ws_url,
            "DOM.querySelector",
            {"nodeId": int(root_id), "selector": selector},
            timeout_sec=8.0,
        )
        node_id = (q or {}).get("nodeId")
        if not node_id:
            return False
        _chrome_cdp_send(
            ws_url,
            "DOM.setFileInputFiles",
            {"nodeId": int(node_id), "files": [path]},
            timeout_sec=10.0,
        )
        return True
    except Exception as exc:
        log_error("_chrome_cdp_set_file_input", exc)
        return False


def _minimax_cdp_iter_endpoints() -> List[Tuple[str, int]]:
    """Minimax Chrome (:9223) + Edge debug porte — nikoli FURS/eDavki 9222."""
    out: List[Tuple[str, int]] = []
    port_candidates: List[int] = []

    chrome_host, chrome_port = _load_minimax_chrome_debug_endpoint()
    if int(chrome_port) not in port_candidates:
        port_candidates.append(int(chrome_port))

    try:
        edge_host, edge_port = _load_minimax_edge_debug_endpoint()
    except Exception:
        edge_host, edge_port = "127.0.0.1", MINIMAX_EDGE_DEBUG_PORT_DEFAULT
    if int(edge_port) not in port_candidates:
        port_candidates.append(int(edge_port))
    try:
        for p in _minimax_list_edge_debug_ports_from_processes():
            if int(p) not in port_candidates and int(p) != 9222:
                port_candidates.append(int(p))
    except Exception as exc:
        log_error("_minimax_cdp_iter_endpoints edge scan", exc)

    hosts: List[str] = []
    for h in (chrome_host, edge_host, "127.0.0.1", "localhost"):
        hs = str(h or "").strip()
        if hs and hs not in hosts:
            hosts.append(hs)

    for try_host in hosts:
        for try_port in port_candidates:
            if int(try_port) == 9222:
                continue  # eDavki/FURS — ne mešaj
            if _furs_debug_port_available(try_host, int(try_port), timeout_sec=0.4):
                pair = (try_host, int(try_port))
                if pair not in out:
                    out.append(pair)
    return out


def _minimax_is_vstopite_landing_url(url: str) -> bool:
    """Goli moj.minimax.si (peach / Vstopite) — brez WebUI poti."""
    u = (url or "").strip().lower()
    if "moj.minimax.si" not in u:
        return False
    if any(x in u for x in ("/webui/", "zacetek", "uvozpodatkov", "login", "prijava", "oauth")):
        return False
    after = u.split("moj.minimax.si", 1)[-1]
    path = after.split("?", 1)[0].strip("/")
    return path in ("", "si")


def _minimax_refresh_page_ws(
    host: str, port: int, page: Optional[Dict[str, Any]]
) -> Tuple[Optional[Dict[str, Any]], str]:
    """Osveži page + websocket (po navigaciji /json/new se target id pogosto menja)."""
    if not page:
        return None, ""
    pid = str(page.get("id") or "").strip()
    url0 = str(page.get("url") or "").strip().lower()
    try:
        rows = _chrome_cdp_list_pages(host, int(port))
    except Exception:
        rows = []
    for row in rows:
        if pid and str(row.get("id") or "").strip() == pid:
            ws = str(row.get("webSocketDebuggerUrl") or "").strip()
            if ws:
                return row, ws
    for row in rows:
        u = str(row.get("url") or "").lower()
        if url0 and (url0 == u or url0.rstrip("/") == u.rstrip("/") or url0 in u or u in url0):
            ws = str(row.get("webSocketDebuggerUrl") or "").strip()
            if ws:
                return row, ws
    ws = str(page.get("webSocketDebuggerUrl") or "").strip()
    return page, ws


def _minimax_cdp_pass_vstopite_gate(
    ws: str,
    *,
    wait_after: float = 1.8,
    host: str = "",
    port: int = 0,
    page: Optional[Dict[str, Any]] = None,
    timeout_sec: float = 14.0,
) -> bool:
    """
    Če je peach stran z gumbom »Vstopite v program« — klikni in počakaj,
    dokler ni Moje org / WebUI (ne ostani na Vstopite).
    """
    cur_ws = (ws or "").strip()
    cur_page = page
    if not cur_ws and not (host and port and cur_page):
        return False
    probe_js = """
(() => {
  const href = location.href || '';
  const title = document.title || '';
  const body = document.body ? (document.body.innerText || '') : '';
  const hasBtn = /vstopite\\s+v\\s+program/i.test(body) || /vstopite\\s+v\\s+program/i.test(title);
  const bare = (() => {
    try {
      const u = new URL(href);
      if (!/moj\\.minimax\\.si$/i.test(u.hostname)) return false;
      const p = (u.pathname || '/').replace(/\\/+$/, '') || '/';
      return p === '/' || p.toLowerCase() === '/si';
    } catch (e) { return false; }
  })();
  const inApp = /WebUI|Zacetek|UvozPodatkov/i.test(href);
  return { hasBtn, bare, inApp, href, title };
})()
""".strip()
    deadline = time.time() + max(5.0, float(timeout_sec))
    clicked = False
    while time.time() < deadline:
        if host and port and cur_page is not None:
            cur_page, cur_ws = _minimax_refresh_page_ws(host, int(port), cur_page)
            if cur_page is not None:
                url_l = str(cur_page.get("url") or "").lower()
                if clicked and not _minimax_is_vstopite_landing_url(url_l) and (
                    "/webui/" in url_l or "zacetek" in url_l
                ):
                    time.sleep(max(0.3, float(wait_after) * 0.35))
                    return True
        if not cur_ws:
            time.sleep(0.35)
            continue
        try:
            probe = _chrome_cdp_runtime_evaluate(cur_ws, probe_js, timeout_sec=5.0) or {}
        except Exception as exc:
            log_error("_minimax_cdp_pass_vstopite_gate probe", exc)
            if host and port and cur_page is not None:
                cur_page, cur_ws = _minimax_refresh_page_ws(host, int(port), cur_page)
            time.sleep(0.35)
            continue
        if not isinstance(probe, dict):
            probe = {}
        if probe.get("inApp") and not probe.get("hasBtn"):
            return clicked
        if not (probe.get("hasBtn") or probe.get("bare")):
            return clicked
        try:
            res = _chrome_cdp_runtime_evaluate(
                cur_ws, _minimax_click_vstopite_js(), timeout_sec=6.0
            ) or {}
        except Exception as exc:
            log_error("_minimax_cdp_pass_vstopite_gate", exc)
            if host and port and cur_page is not None:
                cur_page, cur_ws = _minimax_refresh_page_ws(host, int(port), cur_page)
            time.sleep(0.4)
            continue
        if isinstance(res, dict) and res.get("ok"):
            clicked = True
            log_info("minimax_uvoz | Vstopite v program → klik")
            time.sleep(max(0.8, float(wait_after)))
            if host and port and cur_page is not None:
                cur_page, cur_ws = _minimax_refresh_page_ws(host, int(port), cur_page)
            continue
        time.sleep(0.4)
    return clicked


def _minimax_pick_best_session_tab(
    *,
    organisation_name: str = "",
) -> Optional[Tuple[str, int, Dict[str, Any]]]:
    """
    Hitri zajem: vzemi zavihek kjer je uporabnik že v programu (firma / Moje org / uvoz).
    ChromeMinimax :9223 in/ali Edge z debug portom. Peach Vstopite je zadnja izbira.
    """
    org_key = (organisation_name or "").strip().lower()
    org_parts = [p for p in re.split(r"[,.\s]+", org_key) if len(p) >= 3][:2]
    best: Optional[Tuple[int, str, int, Dict[str, Any]]] = None
    endpoints = _minimax_cdp_iter_endpoints()
    if not endpoints:
        return None
    for host, port in endpoints:
        for row in _chrome_cdp_list_pages(host, port):
            if str(row.get("type") or "").lower() not in ("", "page"):
                continue
            u = str(row.get("url") or "").lower()
            title = str(row.get("title") or "").lower()
            if "moj.minimax.si" not in u and "minimax" not in title:
                continue
            if not str(row.get("webSocketDebuggerUrl") or "").strip():
                continue
            score = 10
            if "uvozpodatkov" in u:
                score = 100
            elif "knjizenjeizdanegaracuna" in u or (
                "knjizenje" in u and "izdan" in u
            ):
                # Že odprt Knjiženje izdanih — ista prijavljena seja
                score = 98
            elif "zacetekorganizacije" in u:
                score = 90
            elif org_parts and all(p in title or p in u for p in org_parts):
                score = 85
            elif "zacetek.aspx" in u and "organizacije" not in u:
                # Moje org (prijavljen) — bolje kot nov peach zavihek
                score = 75 if ("dober dan" in title or "organizacij" in title) else 65
            elif "login" in u or "prijava" in u:
                score = 5
            # peach vhod (samo gumb) — najnižje
            if _minimax_is_vstopite_landing_url(u) or (
                title.strip() in ("minimax", "minimax -", "") and "webui" not in u
            ):
                score = min(score, 3)
            cand = (score, host, int(port), row)
            if best is None or cand[0] > best[0]:
                best = cand
    if best is None:
        return None
    return best[1], best[2], best[3]


def _minimax_open_cdp_new_tab_on_9223(url: str) -> bool:
    """Nov zavihek SAMO na Minimax debug :9223 — brez FURS / drugih portov."""
    host, port = _load_minimax_chrome_debug_endpoint()
    for try_host in (host, "127.0.0.1", "localhost"):
        if _furs_debug_port_available(try_host, int(port), timeout_sec=0.4):
            if _chrome_open_cdp_new_tab(url, try_host, int(port)):
                return True
    return False


def _minimax_ensure_uvoz_tab_cdp(
    organisation_id: Optional[int] = None,
    *,
    organisation_name: str = "",
) -> Tuple[Optional[Tuple[str, int, Dict[str, Any]]], str]:
    """
    Hitri zajem + video: reuse že odprtega Minimax zavihka (firma) → navigacija na
    UvozPodatkovCSV. Če peach »Vstopite v program« → klik. Nov zavihek samo zadnja možnost
    in samo na :9223.
    """
    url = minimax_web_uvoz_url(organisation_id)

    # 1) Že na uvozu? (samo :9223)
    session0 = _minimax_pick_best_session_tab(organisation_name=organisation_name)
    if session0:
        host0, port0, page0 = session0
        u0 = str(page0.get("url") or "").lower()
        if "uvozpodatkov" in u0:
            ws0 = str(page0.get("webSocketDebuggerUrl") or "").strip()
            _chrome_cdp_activate_page(host0, port0, page0)
            if ws0:
                _minimax_cdp_pass_vstopite_gate(
                    ws0, host=host0, port=int(port0), page=page0, wait_after=1.2
                )
            return session0, "reuse UvozPodatkov"

    # 2) Najboljši že odprt zavihek (firma > Moje org > vhod) — NE odpiraj golega root
    session = _minimax_pick_best_session_tab(organisation_name=organisation_name)
    if session:
        host, port, page = session
        page, ws = _minimax_refresh_page_ws(host, int(port), page)
        _chrome_cdp_activate_page(host, port, page or {})
        if ws:
            _minimax_cdp_pass_vstopite_gate(
                ws, host=host, port=int(port), page=page, wait_after=1.5, timeout_sec=12.0
            )
            page, ws = _minimax_refresh_page_ws(host, int(port), page)
            try:
                if ws:
                    _chrome_cdp_navigate(ws, url, timeout_sec=18.0)
            except Exception as exc:
                log_error("_minimax_ensure_uvoz_tab_cdp navigate", exc)
            time.sleep(1.2)
            page, ws = _minimax_refresh_page_ws(host, int(port), page)
            if ws:
                _minimax_cdp_pass_vstopite_gate(
                    ws, host=host, port=int(port), page=page, wait_after=1.2
                )
            try:
                if ws:
                    href = _chrome_cdp_runtime_evaluate(ws, "location.href || ''", timeout_sec=5.0)
                    href_s = href if isinstance(href, str) else str((href or {}).get("value") or "")
                    if "uvozpodatkov" not in href_s.lower():
                        _chrome_cdp_navigate(ws, url, timeout_sec=18.0)
                        time.sleep(1.0)
                        page, ws = _minimax_refresh_page_ws(host, int(port), page)
                        if ws:
                            _minimax_cdp_pass_vstopite_gate(
                                ws, host=host, port=int(port), page=page, wait_after=1.0
                            )
            except Exception:
                pass
        found2 = _minimax_pick_best_session_tab(organisation_name=organisation_name)
        if found2 and "uvozpodatkov" in str(found2[2].get("url") or "").lower():
            return found2, "reuse firma → UvozPodatkovCSV"
        return (found2 or (host, port, page or {})), "reuse firma → UvozPodatkovCSV"

    # 3) Zadnja možnost — nov zavihek SAMO na :9223 + obvezen Vstopite
    if _minimax_open_cdp_new_tab_on_9223(url):
        time.sleep(1.5)
        found2 = _minimax_pick_best_session_tab(organisation_name=organisation_name)
        if found2:
            host, port, page = found2
            page, ws = _minimax_refresh_page_ws(host, int(port), page)
            _chrome_cdp_activate_page(host, port, page or {})
            if ws:
                _minimax_cdp_pass_vstopite_gate(
                    ws, host=host, port=int(port), page=page, wait_after=2.0, timeout_sec=14.0
                )
                page, ws = _minimax_refresh_page_ws(host, int(port), page)
                try:
                    if ws:
                        href = _chrome_cdp_runtime_evaluate(
                            ws, "location.href || ''", timeout_sec=5.0
                        )
                        href_s = (
                            href
                            if isinstance(href, str)
                            else str((href or {}).get("value") or "")
                        )
                        if "uvozpodatkov" not in href_s.lower():
                            _chrome_cdp_navigate(ws, url, timeout_sec=18.0)
                            time.sleep(1.0)
                            page, ws = _minimax_refresh_page_ws(host, int(port), page)
                            if ws:
                                _minimax_cdp_pass_vstopite_gate(
                                    ws, host=host, port=int(port), page=page, wait_after=1.2
                                )
                except Exception:
                    pass
            found3 = _minimax_pick_best_session_tab(organisation_name=organisation_name)
            return (found3 or found2), "nov zavihek + Vstopite"
        return None, "Minimax uvoz zavihek ni naložen (CDP :9223)."
    return None, (
        "Chrome CDP za Minimax (:9223) ni dosegljiv.\n"
        "Nastavitve → Odpri Minimax Chrome, prijavi se, nato ponovi."
    )


def _minimax_ensure_cdp_ready(
    *, wait_sec: float = 45.0, auto_start: bool = True
) -> Tuple[bool, str]:
    """
    Minimax Chrome/Edge debug mora že teči (prijava ostane).
    NE restartaj / NE ubij že odprtega brskalnika — sicer pride »Vstopite v program«.
    auto_start=False: samo odkrij obstoječi CDP (uvoz — brez nove prijave).
    """
    endpoints = _minimax_cdp_iter_endpoints()
    if endpoints:
        host, port = endpoints[0]
        return True, f"Minimax CDP {host}:{port}"

    host, port = _load_minimax_chrome_debug_endpoint()

    # Samo če ChromeMinimax še NE teče — zaženi z debug. Če teče brez debug: ne ubijaj.
    try:
        if _chrome_profile_process_running(_minimax_chrome_automation_profile_dir()):
            return False, (
                f"ChromeMinimax teče, a debug port {port} ni odprt.\n"
                "Zapri ta Chrome in: Nastavitve → Odpri Minimax Chrome "
                "(enkrat se prijavi) — nato ponovi uvoz.\n"
                "Ali odpri Minimax v Edge z --remote-debugging-port."
            )
    except Exception:
        pass

    if not auto_start:
        return False, (
            f"Ni odprtega Chrome/Edge z Minimax debug (npr. :{port}).\n"
            "Odpri Minimax v Chrome (Nastavitve → Odpri Minimax Chrome) ali Edge z debug,\n"
            "prijavi se, pusti zavihek odprt — nato ponovi.\n"
            "Ne odpiram nove Minimax prijave."
        )

    if _start_minimax_debug_chrome_if_needed(wait_sec=wait_sec, restart=False):
        if _furs_wait_for_debug_port(host, int(port), timeout_sec=max(15.0, min(35.0, float(wait_sec)))):
            return True, f"Minimax Chrome (debug {port}) zagnan"
    return False, (
        f"Minimax Chrome debug :{port} ni dosegljiv.\n"
        "Nastavitve → Odpri Minimax Chrome, prijavi se, nato ponovi."
    )


def _minimax_click_vstopite_js() -> str:
    """Vhodna stran moj.minimax.si: gumb »Vstopite v program« (screenshot peach)."""
    return """
(() => {
  const txt = (el) => ((el && (el.innerText || el.textContent || el.value
    || el.getAttribute('aria-label') || el.getAttribute('title'))) || '')
    .replace(/\\s+/g, ' ').trim();
  const visible = (el) => {
    if (!el) return false;
    const r = el.getBoundingClientRect();
    const st = window.getComputedStyle(el);
    return r.width > 8 && r.height > 8
      && st.visibility !== 'hidden' && st.display !== 'none' && st.opacity !== '0';
  };
  const fire = (el) => {
    if (!el) return false;
    try { el.scrollIntoView({ block: 'center', inline: 'center' }); } catch (e) {}
    try { el.focus(); } catch (e) {}
    try { el.click(); return true; } catch (e) {}
    try {
      el.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
      return true;
    } catch (e) { return false; }
  };
  const match = (s) => /vstopite(\\s+v\\s+program)?/i.test(s || '') || /vstop.*program/i.test(s || '');
  const sel = 'a, button, input[type=button], input[type=submit], [role="button"], span, div';
  const nodes = Array.from(document.querySelectorAll(sel)).filter(visible);
  let hit = nodes.find(el => match(txt(el)));
  if (!hit) {
    // peach: edini primarni gumb na golem moj.minimax.si
    hit = nodes.find(el => {
      const tag = (el.tagName || '').toLowerCase();
      const role = (el.getAttribute('role') || '').toLowerCase();
      if (!(tag === 'a' || tag === 'button' || tag === 'input' || role === 'button')) return false;
      const t = txt(el);
      return t.length >= 4 && t.length < 48 && /vstop/i.test(t);
    });
  }
  if (!hit) return { ok: false, reason: 'no_button', href: location.href, title: document.title || '' };
  const clickable = hit.closest('a, button, [role="button"]') || hit;
  if (!fire(clickable)) return { ok: false, reason: 'click_failed', text: txt(clickable) };
  return { ok: true, text: txt(clickable), href: location.href, title: document.title || '' };
})()
""".strip()


def _minimax_click_uvoz_iz_excela_js(
    *,
    organisation_id: Optional[int] = None,
    organisation_name: str = "",
) -> str:
    """
    Video frames: v firmi (navbar ALFA GYM) → zobnik zgoraj desno →
    Nastavitve organizacije → Uvoz iz Excela.
    Če še Moje org: zobnik v vrstici ciljne firme (Nastavitve), sicer header.
    """
    oid = json.dumps(str(int(organisation_id)) if organisation_id else "")
    onm = json.dumps(str(organisation_name or "").strip().lower())
    return f"""
(() => {{
  const oid = {oid};
  const onm = {onm};
  const txt = (el) => ((el && (el.innerText || el.textContent || el.value)) || '').replace(/\\s+/g, ' ').trim();
  const fire = (el) => {{
    if (!el) return false;
    try {{ el.click(); return true; }} catch (e) {{}}
    try {{
      el.dispatchEvent(new MouseEvent('click', {{ bubbles: true, cancelable: true, view: window }}));
      return true;
    }} catch (e) {{ return false; }}
  }};
  const findUvozLink = () => Array.from(document.querySelectorAll('a')).find(a =>
    /uvoz\\s*iz\\s*excel/i.test(txt(a)) || /UvozPodatkovCSV\\.aspx/i.test(a.getAttribute('href') || '')
  );
  const path = location.pathname || '';
  if (/UvozPodatkovCSV/i.test(path)) {{
    return {{ ok: true, how: 'already_uvoz', path }};
  }}
  let hit = findUvozLink();
  if (hit && fire(hit)) return {{ ok: true, how: 'link_visible', href: hit.getAttribute('href') || '', text: txt(hit) }};

  const onOrgList = /Zacetek\\.aspx/i.test(path) && !/ZacetekOrganizacije/i.test(path);
  // Moje org: zobnik v vrstici ciljne firme (stolpec Nastavitve)
  if (onOrgList) {{
    let row = null;
    if (oid) row = document.querySelector('tr[data-organizacijaid="' + oid + '"], tr.prijava[data-organizacijaid="' + oid + '"]');
    if (!row && onm && onm.length > 2) {{
      row = Array.from(document.querySelectorAll('tr.prijava, tr[data-organizacijaid], tr')).find(tr => {{
        const t = txt(tr).toLowerCase();
        return t.includes(onm) || (onm.split(/\\s+/).filter(p => p.length >= 3).slice(0, 2).every(p => t.includes(p)));
      }}) || null;
    }}
    if (row) {{
      const gearInRow = Array.from(row.querySelectorAll('a, button, span, i, div')).find(el => {{
        const cls = (el.className || '').toString().toLowerCase();
        const aria = (el.getAttribute('aria-label') || '').toLowerCase();
        const title = (el.getAttribute('title') || '').toLowerCase();
        const r = el.getBoundingClientRect();
        if (!(r.width > 0 && r.height > 0)) return false;
        return /icon-settings|settings|nastavit|gear|cog/.test(cls + ' ' + aria + ' ' + title);
      }});
      if (gearInRow) {{
        fire(gearInRow.closest('a, button') || gearInRow);
        hit = findUvozLink();
        if (hit && fire(hit)) return {{ ok: true, how: 'row_gear_then_link', text: txt(hit) }};
      }}
    }}
  }}

  // V firmi: zobnik v headerju (zgoraj desno) — video frame 5–6
  const gearCandidates = Array.from(document.querySelectorAll('a, button, span, i, div')).filter(el => {{
    const t = txt(el).toLowerCase();
    const cls = (el.className || '').toString().toLowerCase();
    const aria = (el.getAttribute('aria-label') || '').toLowerCase();
    const title = (el.getAttribute('title') || '').toLowerCase();
    const r = el.getBoundingClientRect();
    if (!(r.width > 0 && r.height > 0 && r.top < 100)) return false;
    return /icon-settings|settings|nastavit/.test(cls + ' ' + aria + ' ' + title)
      || (t === '' && /gear|cog|settings/.test(cls));
  }});
  const vw = window.innerWidth || 1200;
  const gear = gearCandidates.sort((a, b) => b.getBoundingClientRect().left - a.getBoundingClientRect().left)
    .find(el => el.getBoundingClientRect().left > vw * 0.55)
    || gearCandidates[0]
    || document.querySelector('[class*="settings"], [class*="icon-settings"], a[title*="Nastavit"]');
  if (gear) fire(gear.closest('a, button') || gear);

  // meni se odpre asinhrono — kratko počakaj v JS ni mogoče; klicatelj lahko retry
  hit = findUvozLink();
  if (hit && fire(hit)) return {{ ok: true, how: 'header_gear_then_link', href: hit.getAttribute('href') || '', text: txt(hit) }};
  return {{
    ok: false,
    how: 'not_found',
    path,
    onOrgList,
    gears: gearCandidates.length,
    title: document.title || ''
  }};
}})()
""".strip()


def _minimax_uvoz_find_page_ws(
    endpoints: List[Tuple[str, int]],
    *,
    needles: Optional[Sequence[str]] = None,
) -> Optional[Tuple[str, int, Dict[str, Any], str]]:
    want = [n.lower() for n in (needles or ("uvozpodatkov", "uvoz"))]
    for host, port in endpoints:
        for row in _chrome_cdp_list_pages(host, port):
            u = str(row.get("url") or "").lower()
            if any(n in u for n in want):
                ws = str(row.get("webSocketDebuggerUrl") or "").strip()
                if ws:
                    return host, port, row, ws
    return None


def _minimax_find_org_select_tab(
    endpoints: List[Tuple[str, int]],
    *,
    organisation_name: str = "",
) -> Optional[Tuple[str, int, Dict[str, Any], str]]:
    """Preferiraj firmo / Moje org pred peach Vstopite (samo podani endpoints = :9223)."""
    org_key = (organisation_name or "").strip().lower()
    org_parts = [p for p in re.split(r"[,.\s]+", org_key) if len(p) >= 3][:2]
    best: Optional[Tuple[int, str, int, Dict[str, Any], str]] = None
    for host, port in endpoints:
        for row in _chrome_cdp_list_pages(host, port):
            if str(row.get("type") or "").lower() not in ("", "page"):
                continue
            u = str(row.get("url") or "").lower()
            title = str(row.get("title") or "").lower()
            if "moj.minimax.si" not in u:
                continue
            ws = str(row.get("webSocketDebuggerUrl") or "").strip()
            if not ws:
                continue
            score = 10
            if "zacetekorganizacije" in u:
                score = 100
            elif org_parts and all(p in title or p in u for p in org_parts):
                score = 90
            elif "zacetek/zacetek.aspx" in u and "organizacije" not in u:
                score = 80
            elif "uvozpodatkov" in u:
                score = 70
            elif _minimax_is_vstopite_landing_url(u):
                score = 4
            cand = (score, host, int(port), row, ws)
            if best is None or cand[0] > best[0]:
                best = cand
    if best is None:
        return None
    return best[1], best[2], best[3], best[4]


def _minimax_cdp_select_organisation(
    endpoints: Optional[List[Tuple[str, int]]] = None,
    *,
    organisation_id: int,
    organisation_name: str = "",
    host: str = "127.0.0.1",
    port: int = 9223,
    timeout_sec: float = 25.0,
    allow_new_tab: bool = True,
) -> Tuple[bool, str]:
    """
    Izbira firme: reuse že odprtega Minimax zavihka na :9223 →
    Vstopite (če peach) → Zacetek.aspx → HARD klik firme → ZacetekOrganizacije.
    Ne odpira zavihkov na FURS/drugih debug portih.
    allow_new_tab=False: samo obstoječa seja (seje so vedno prijavljene).
    """
    org_name = (organisation_name or lookup_minimax_org_name(organisation_id) or "").strip()
    select_js = _minimax_select_org_on_zacetek_js(
        organisation_id=organisation_id,
        organisation_name=org_name,
    )
    check_js = _minimax_active_org_check_js(org_name)

    mm_endpoints = _minimax_cdp_iter_endpoints() or [(host, int(port))]
    if endpoints:
        # ohrani vrstni red, a filtriraj na Minimax port
        mm_port = int(port) if port else _load_minimax_chrome_debug_endpoint()[1]
        filtered = [(h, int(p)) for h, p in endpoints if int(p) == mm_port]
        if filtered:
            mm_endpoints = filtered

    # 1) Reuse že odprtega Minimax zavihka; nov zavihek samo če allow_new_tab
    open_deadline = time.time() + min(18.0, max(8.0, timeout_sec * 0.5))
    opened_ok = False
    while time.time() < open_deadline and not opened_ok:
        found_mm = _minimax_pick_best_session_tab(organisation_name=org_name)
        if found_mm:
            h0, p0, page0 = found_mm
            page0, ws0 = _minimax_refresh_page_ws(h0, int(p0), page0)
            _chrome_cdp_activate_page(h0, p0, page0 or {})
            if ws0:
                try:
                    chk0 = _chrome_cdp_runtime_evaluate(ws0, check_js, timeout_sec=6.0) or {}
                    if isinstance(chk0, dict) and chk0.get("ok"):
                        return True, f"Že aktivna: {chk0.get('org') or org_name or organisation_id}"
                except Exception:
                    pass
                if _minimax_cdp_pass_vstopite_gate(
                    ws0, host=h0, port=int(p0), page=page0, wait_after=1.6, timeout_sec=12.0
                ):
                    log_info("minimax_org_select | Vstopite v program")
                    page0, ws0 = _minimax_refresh_page_ws(h0, int(p0), page0)
                url0 = str((page0 or {}).get("url") or "").lower()
                already_list = "zacetek/zacetek.aspx" in url0 and "organizacije" not in url0
                if already_list:
                    opened_ok = True
                    host, port = h0, int(p0)
                    break
                try:
                    if ws0:
                        _chrome_cdp_navigate(ws0, MINIMAX_WEB_ZACETEK_URL, timeout_sec=15.0)
                        time.sleep(0.8)
                        page0, ws0 = _minimax_refresh_page_ws(h0, int(p0), page0)
                        if ws0:
                            _minimax_cdp_pass_vstopite_gate(
                                ws0, host=h0, port=int(p0), page=page0, wait_after=1.2
                            )
                        opened_ok = True
                        host, port = h0, int(p0)
                        break
                except Exception as exc:
                    log_error("_minimax_cdp_select_organisation navigate Zacetek", exc)
        if not allow_new_tab:
            break
        # samo :9223 — ne any_debug_port (FURS)
        if _minimax_open_cdp_new_tab_on_9223(MINIMAX_WEB_ZACETEK_URL):
            time.sleep(1.2)
            opened_ok = True
            break
        time.sleep(0.6)

    if not opened_ok:
        if not allow_new_tab:
            return False, (
                "Ni obstoječega Minimax zavihka — ne odpiram novega "
                "(seje so vedno prijavljene; pusti Minimax odprt)."
            )
        return False, (
            "Ni mogoče odpreti Moje organizacije (CDP :9223).\n"
            "Nastavitve → Odpri Minimax Chrome, prijavi se, nato ponovi."
        )

    endpoints = list(mm_endpoints)
    if (host, int(port)) not in endpoints:
        endpoints.insert(0, (host, int(port)))

    deadline = time.time() + timeout_sec
    last = ""
    clicked = False
    while time.time() < deadline:
        found = _minimax_find_org_select_tab(endpoints, organisation_name=org_name)
        if found is None:
            time.sleep(0.35)
            continue
        h, p, page, ws = found
        page, ws = _minimax_refresh_page_ws(h, int(p), page)
        if not ws:
            time.sleep(0.35)
            continue
        _chrome_cdp_activate_page(h, p, page or {})
        url_l = str((page or {}).get("url") or "").lower()
        on_org_list = "zacetek/zacetek.aspx" in url_l and "organizacije" not in url_l
        on_landing = _minimax_is_vstopite_landing_url(url_l)
        try:
            if on_landing or _minimax_cdp_pass_vstopite_gate(
                ws, host=h, port=int(p), page=page, wait_after=1.5, timeout_sec=10.0
            ):
                if on_landing:
                    _minimax_cdp_pass_vstopite_gate(
                        ws, host=h, port=int(p), page=page, wait_after=1.6, timeout_sec=12.0
                    )
                last = "Vstopite v program"
                page, ws = _minimax_refresh_page_ws(h, int(p), page)
                if not ws:
                    continue
                url_l = str((page or {}).get("url") or "").lower()
                on_org_list = "zacetek/zacetek.aspx" in url_l and "organizacije" not in url_l
                if not on_org_list and "zacetekorganizacije" not in url_l:
                    try:
                        _chrome_cdp_navigate(ws, MINIMAX_WEB_ZACETEK_URL, timeout_sec=12.0)
                        time.sleep(0.9)
                        page, ws = _minimax_refresh_page_ws(h, int(p), page)
                        if ws:
                            _minimax_cdp_pass_vstopite_gate(
                                ws, host=h, port=int(p), page=page, wait_after=1.2
                            )
                    except Exception:
                        pass
                    continue

            # Če smo že v firmi — preveri
            chk = _chrome_cdp_runtime_evaluate(ws, check_js, timeout_sec=8.0) or {}
            if isinstance(chk, dict) and chk.get("ok"):
                return True, f"Aktivna org: {chk.get('org') or org_name or organisation_id}"

            # Po kliku: nov zavihek lahko dobi Vstopite — poišči ga in spusti gate, nato HARD firm
            if clicked:
                firm_tab = _minimax_find_org_select_tab(endpoints, organisation_name=org_name)
                if firm_tab:
                    h2, p2, page2, ws2 = firm_tab
                    page2, ws2 = _minimax_refresh_page_ws(h2, int(p2), page2)
                    if ws2:
                        _chrome_cdp_activate_page(h2, p2, page2 or {})
                        if _minimax_is_vstopite_landing_url(str((page2 or {}).get("url") or "")):
                            _minimax_cdp_pass_vstopite_gate(
                                ws2, host=h2, port=int(p2), page=page2, wait_after=1.6
                            )
                            page2, ws2 = _minimax_refresh_page_ws(h2, int(p2), page2)
                        if ws2:
                            chk2 = _chrome_cdp_runtime_evaluate(ws2, check_js, timeout_sec=8.0) or {}
                            if isinstance(chk2, dict) and chk2.get("ok"):
                                return True, (
                                    f"Aktivna org: {chk2.get('org') or org_name or organisation_id}"
                                )
                            # še vedno Moje org / peach → HARD klik firme znova
                            u2 = str((page2 or {}).get("url") or "").lower()
                            if "zacetek/zacetek.aspx" in u2 and "organizacije" not in u2:
                                res2 = _chrome_cdp_runtime_evaluate(
                                    ws2, select_js, timeout_sec=10.0
                                ) or {}
                                if isinstance(res2, dict) and res2.get("ok"):
                                    last = (
                                        f"klik-retry {res2.get('how') or 'org'} "
                                        f"{res2.get('orgId') or organisation_id}"
                                    )
                                    log_info(
                                        f"minimax_org_select | {last} | {res2.get('text') or org_name}"
                                    )
                                    time.sleep(1.4)
                last = str(chk)
                time.sleep(0.45)
                continue

            if not on_org_list and not clicked:
                try:
                    _chrome_cdp_navigate(ws, MINIMAX_WEB_ZACETEK_URL, timeout_sec=12.0)
                except Exception:
                    pass
                time.sleep(0.8)
                page, ws = _minimax_refresh_page_ws(h, int(p), page)
                if ws:
                    _minimax_cdp_pass_vstopite_gate(
                        ws, host=h, port=int(p), page=page, wait_after=1.2
                    )
                continue

            if on_org_list and not clicked:
                res = _chrome_cdp_runtime_evaluate(ws, select_js, timeout_sec=10.0) or {}
                if isinstance(res, dict) and res.get("ok"):
                    clicked = True
                    last = f"klik {res.get('how') or 'org'} {res.get('orgId') or organisation_id}"
                    log_info(f"minimax_org_select | {last} | {res.get('text') or org_name}")
                    time.sleep(1.4)
                    continue
                last = str(
                    (res or {}).get("how")
                    or (res or {}).get("reason")
                    or res
                    or "no_click"
                )
                if isinstance(res, dict) and int(res.get("rows") or 0) == 0:
                    time.sleep(0.5)
                    continue
        except Exception as exc:
            last = str(exc)
        time.sleep(0.4)
    return False, f"Izbira firme ni uspela ({last or 'timeout'})."


def _minimax_uvoz_wait_report(
    endpoints: List[Tuple[str, int]],
    *,
    timeout_sec: float = 60.0,
    open_temeljnica: bool = True,
) -> Tuple[bool, str, Dict[str, Any]]:
    """Po Uvozi: čakaj poročilo, preveri Z napakami=0, opcijsko Prikaži temeljnico."""
    deadline = time.time() + timeout_sec
    last: Dict[str, Any] = {}
    while time.time() < deadline:
        found = _minimax_uvoz_find_page_ws(endpoints)
        if found is None:
            time.sleep(0.4)
            continue
        host, port, page, ws = found
        _chrome_cdp_activate_page(host, port, page)
        try:
            last = _chrome_cdp_runtime_evaluate(ws, _minimax_uvoz_read_report_js(), timeout_sec=10.0) or {}
        except Exception as exc:
            last = {"error": str(exc)}
            time.sleep(0.5)
            continue
        if isinstance(last, dict) and last.get("has_report"):
            errors = int(last.get("errors") or 0)
            if errors > 0:
                return False, f"Uvoz z napakami ({errors}).", last
            if open_temeljnica and last.get("show_temeljnica"):
                try:
                    _chrome_cdp_runtime_evaluate(
                        ws, _minimax_uvoz_click_show_temeljnica_js(), timeout_sec=8.0
                    )
                    last["opened_temeljnica"] = True
                    time.sleep(0.9)
                    try:
                        href = _chrome_cdp_runtime_evaluate(
                            ws, "location.href || ''", timeout_sec=5.0
                        )
                        if isinstance(href, str) and href.startswith("http"):
                            last["temelnica_url"] = href
                        elif isinstance(href, dict) and href.get("value"):
                            last["temelnica_url"] = str(href.get("value"))
                    except Exception:
                        last["temelnica_url"] = str(last.get("url") or page.get("url") or "")
                except Exception:
                    last["opened_temeljnica"] = False
            if not last.get("temelnica_url"):
                last["temelnica_url"] = str(last.get("url") or page.get("url") or "")
            return True, "Poročilo OK (0 napak).", last
        time.sleep(0.5)
    return False, "Poročilo o uvozu se ni prikazalo pravočasno.", last if isinstance(last, dict) else {}


def _minimax_cdp_org_already_active(
    endpoints: List[Tuple[str, int]],
    *,
    organisation_name: str = "",
) -> Tuple[bool, str]:
    """Hitri zajem: če navbar / naslov že kaže firmo (ZacetekOrganizacije ali Uvoz), ne hodimo na Moje org."""
    check_js = _minimax_active_org_check_js(organisation_name)
    for host, port in endpoints:
        for row in _chrome_cdp_list_pages(host, port):
            u = str(row.get("url") or "").lower()
            if "moj.minimax.si" not in u:
                continue
            ws = str(row.get("webSocketDebuggerUrl") or "").strip()
            if not ws:
                continue
            try:
                _chrome_cdp_activate_page(host, port, row)
                chk = _chrome_cdp_runtime_evaluate(ws, check_js, timeout_sec=5.0) or {}
            except Exception:
                continue
            if isinstance(chk, dict) and chk.get("ok"):
                org = str(chk.get("org") or organisation_name or "").strip()
                return True, f"Že v firmi: {org or chk.get('title') or 'OK'}"
    return False, ""


def _minimax_cdp_wait_firm_in_navbar(
    ws: str,
    *,
    organisation_name: str = "",
    timeout_sec: float = 18.0,
    host: str = "",
    port: int = 0,
    page: Optional[Dict[str, Any]] = None,
) -> Tuple[bool, str]:
    """Po kliku firme: čakaj title/navbar (ne seznam Moje org / Vstopite)."""
    cur_ws = (ws or "").strip()
    cur_page = page
    if not cur_ws and not (host and port and cur_page):
        return False, "ni ws"
    check_js = _minimax_active_org_check_js(organisation_name)
    deadline = time.time() + max(4.0, float(timeout_sec))
    last: Dict[str, Any] = {}
    while time.time() < deadline:
        try:
            if host and port and cur_page is not None:
                # po kliku firme Minimax pogosto odpre NOV zavihek (lahko z Vstopite)
                best = _minimax_find_org_select_tab(
                    [(host, int(port))], organisation_name=organisation_name
                )
                if best:
                    host, port, cur_page, cur_ws = best[0], best[1], best[2], best[3]
                    _chrome_cdp_activate_page(host, int(port), cur_page)
            if cur_ws:
                _minimax_cdp_pass_vstopite_gate(
                    cur_ws,
                    wait_after=1.0,
                    host=host or "",
                    port=int(port or 0),
                    page=cur_page,
                    timeout_sec=6.0,
                )
                if host and port and cur_page is not None:
                    cur_page, cur_ws = _minimax_refresh_page_ws(host, int(port), cur_page)
            if not cur_ws:
                time.sleep(0.4)
                continue
            last = _chrome_cdp_runtime_evaluate(cur_ws, check_js, timeout_sec=6.0) or {}
            if isinstance(last, dict) and last.get("ok"):
                org = str(last.get("org") or organisation_name or "").strip()
                return True, f"Firma v seji: {org or last.get('title') or 'OK'}"
        except Exception as exc:
            last = {"error": str(exc)}
        time.sleep(0.45)
    reason = ""
    if isinstance(last, dict):
        reason = str(last.get("reason") or last.get("path") or last.get("error") or last)
    return False, f"Firma ni v navbarju ({reason or 'timeout'})"


def _minimax_uvoz_fill_in_user_chrome(
    *,
    xlsx_path: Path,
    yyyy: str,
    mm: str,
    organisation_id: Optional[int] = None,
    organisation_name: str = "",
    vrsta_temeljnice: str = MINIMAX_WEB_UVOZ_VRSTA_TEMELJNICE,
    click_import: bool = True,
    open_temeljnica: bool = True,
    timeout_sec: float = 45.0,
) -> Tuple[bool, str]:
    """
    VIDEO (uvoz_excel frames 1–11) — že odprt Chrome/Edge Minimax CDP, NE restart:
    1) Aktiviraj isti moj.minimax.si zavihek
    2) Če Moje org / navbar ≠ firma → HARD klik tr[data-organizacijaid] naziva
    3) Počakaj ZacetekOrganizacije + navbar ime firme
    4) Zobnik → Uvoz iz Excela (ali ista seja → UvozPodatkovCSV.aspx)
    5) KN → radio → IR → datum/opis → Excel → Uvozi
    """
    path = Path(xlsx_path).resolve()
    if not path.is_file():
        return False, f"Datoteka ne obstaja:\n{path}"
    page_url = MINIMAX_WEB_UVOZ_URL  # video: goli URL ŠELE po seji firme
    date_sl = last_day_of_month_sl(yyyy, mm)
    opis = minimax_web_uvoz_opis(yyyy, mm)
    org_name = (organisation_name or "").strip()
    if organisation_id and not org_name:
        org_name = (lookup_minimax_org_name(organisation_id) or "").strip()

    # Samo attach — ne zaženi novega Chrome/Edge (nova prijava).
    ready, ready_msg = _minimax_ensure_cdp_ready(
        wait_sec=max(8.0, min(20.0, float(timeout_sec))),
        auto_start=False,
    )
    if not ready:
        return False, (
            f"{ready_msg}\n\n"
            "Program ne odpira nove Minimax prijave.\n"
            "Pusti prijavljen zavihek odprt, nato ponovi uvoz."
        )

    host, port = _load_minimax_chrome_debug_endpoint()
    endpoints: List[Tuple[str, int]] = _minimax_cdp_iter_endpoints()
    if not endpoints:
        return False, ready_msg
    tab_steps: List[str] = [ready_msg]

    # a) Preferiraj že odprt prijavljen zavihek (Moje org / firma) — NE goli root / nov login
    session = _minimax_pick_best_session_tab(organisation_name=org_name)
    if session is None:
        ports = ", ".join(f":{p}" for _, p in endpoints) or f":{port}"
        return False, (
            f"Ni odprtega Minimax zavihka (moj.minimax.si) na CDP {ports}.\n"
            "Odpri Minimax v Chrome ali Edge (Nastavitve → Odpri Minimax Chrome),\n"
            "prijavi se (Moje organizacije / firma), pusti zavihek odprt — nato ponovi.\n"
            "Ne odpiram nove Minimax prijave."
        )
    host, port, page = session
    page, ws = _minimax_refresh_page_ws(host, int(port), page)
    _chrome_cdp_activate_page(host, int(port), page or {})
    if not ws:
        return False, f"Minimax zavihek brez CDP websocket (:{port})."
    if _minimax_cdp_pass_vstopite_gate(
        ws, host=host, port=int(port), page=page, wait_after=1.6, timeout_sec=14.0
    ):
        tab_steps.append("Vstopite → Moje org")
        page, ws = _minimax_refresh_page_ws(host, int(port), page)
        if not ws:
            return False, "Po Vstopite ni CDP websocket (osveži ChromeMinimax)."
    tab_steps.append("reuse Minimax zavihek")
    # še enkrat zavrni peach — ne nadaljuj na golem Vstopite
    if page and _minimax_is_vstopite_landing_url(str(page.get("url") or "")):
        if not _minimax_cdp_pass_vstopite_gate(
            ws, host=host, port=int(port), page=page, wait_after=1.8, timeout_sec=12.0
        ):
            return False, (
                "Chrome kaže »Vstopite v program« — klik ni uspel.\n"
                "Klikni gumb ročno (ali se prijavi v ChromeMinimax :9223), nato ponovi."
            )
        page, ws = _minimax_refresh_page_ws(host, int(port), page)

    # b–c) HARD: firma v seji (navbar), sicer klik na Moje org
    firm_ok, firm_msg = _minimax_cdp_org_already_active(endpoints, organisation_name=org_name)
    if firm_ok:
        tab_steps.append(firm_msg)
    else:
        if not organisation_id:
            return False, (
                "Ni znan OrganisationId — ne morem izbrati firme na Moje org.\n"
                "Izberi firmo v programu (npr. ALFA GYM) ali odpri firmo v Minimaxu."
            )
        try:
            ok_org, org_msg = _minimax_cdp_select_organisation(
                endpoints,
                organisation_id=int(organisation_id),
                organisation_name=org_name,
                host=host,
                port=int(port),
                timeout_sec=max(22.0, min(32.0, float(timeout_sec) * 0.55)),
            )
            tab_steps.append(org_msg)
            log_info(f"minimax_uvoz_video | org_select HARD | ok={ok_org} | {org_msg}")
            if not ok_org:
                return False, (
                    f"Video pot: vstop v firmo ni uspel.\n{org_msg}\n\n"
                    f"Na Moje organizacije klikni »{org_name or organisation_id}« "
                    f"(data-organizacijaid={organisation_id}), nato ponovi.\n"
                    f"{', '.join(tab_steps)}"
                )
        except Exception as exc:
            log_error("minimax_uvoz_video org HARD", exc)
            return False, (
                f"Video pot: izbira firme spodletela ({exc}).\n"
                f"{', '.join(tab_steps)}"
            )
        time.sleep(0.6)
        endpoints = _minimax_cdp_iter_endpoints() or [(host, int(port))]
        session2 = _minimax_pick_best_session_tab(organisation_name=org_name)
        if session2:
            host, port, page = session2
            page, ws = _minimax_refresh_page_ws(host, int(port), page)
            ws = ws or str((page or {}).get("webSocketDebuggerUrl") or "").strip()
            _chrome_cdp_activate_page(host, int(port), page or {})
        firm_ok, firm_msg = _minimax_cdp_wait_firm_in_navbar(
            ws,
            organisation_name=org_name,
            timeout_sec=16.0,
            host=host,
            port=int(port),
            page=page,
        )
        tab_steps.append(firm_msg)
        if not firm_ok:
            return False, (
                f"Video pot: po kliku firme navbar še ne kaže »{org_name or organisation_id}«.\n"
                f"{firm_msg}\nŠe vedno na Moje org? Odpri firmo ročno, nato ponovi.\n"
                f"{', '.join(tab_steps)}"
            )

    # d) ŠELE zdaj Uvoz — zobnik → Uvoz iz Excela (ista seja / isti zavihek)
    gear_js = _minimax_click_uvoz_iz_excela_js(
        organisation_id=int(organisation_id) if organisation_id else None,
        organisation_name=org_name,
    )
    gear_ok = False
    for attempt in range(3):
        try:
            gear = _chrome_cdp_runtime_evaluate(ws, gear_js, timeout_sec=10.0) or {}
            if isinstance(gear, dict) and gear.get("ok"):
                gear_ok = True
                tab_steps.append(f"Uvoz iz Excela ({gear.get('how')})")
                time.sleep(1.5)
                break
            tab_steps.append(f"gear try{attempt + 1}: {(gear or {}).get('how') or gear}")
            log_info(f"minimax_uvoz_video | gear | {gear}")
            time.sleep(0.7)
        except Exception as exc:
            tab_steps.append(f"gear try{attempt + 1}: {exc}")
            log_error("minimax_uvoz_video gear", exc)
            time.sleep(0.5)

    if not gear_ok:
        # Rezerva SAMO če je firma še v seji (navbar) — ne slepi URL z Moje org
        still_firm, still_msg = _minimax_cdp_wait_firm_in_navbar(
            ws, organisation_name=org_name, timeout_sec=4.0
        )
        if not still_firm:
            return False, (
                "Video pot: Uvoz iz Excela ni odprt in firma ni v navbarju.\n"
                f"{still_msg}\n"
                "Pot: Moje org → klik firme → zobnik → Uvoz iz Excela.\n"
                f"{', '.join(tab_steps)}"
            )
        try:
            _chrome_cdp_navigate(ws, page_url, timeout_sec=18.0)
            tab_steps.append("navigate UvozPodatkovCSV (po potrjeni firmi)")
            time.sleep(1.2)
            _minimax_cdp_pass_vstopite_gate(ws, wait_after=1.2)
        except Exception as exc:
            return False, (
                f"Ni mogoče odpreti UvozPodatkovCSV po seji firme.\n{exc}\n"
                f"{', '.join(tab_steps)}"
            )

    log_info(
        f"minimax_uvoz_video | {ready_msg} | {page_url} | org={org_name or organisation_id} | {tab_steps}"
    )

    select_js = _minimax_uvoz_select_podatki_kn_js()
    fill_js = _minimax_uvoz_fill_form_js(
        date_sl=date_sl,
        opis=opis,
        vrsta_label=vrsta_temeljnice or MINIMAX_WEB_UVOZ_VRSTA_TEMELJNICE,
        vrsta_id=MINIMAX_WEB_UVOZ_VRSTA_TEMELJNICE_ID,
    )
    deadline = time.time() + max(28.0, float(timeout_sec) * 0.65)
    last_err = ""
    steps: List[str] = []
    kn_done = False
    while time.time() < deadline:
        found = _minimax_uvoz_find_page_ws(endpoints, needles=("uvozpodatkov", "uvoz"))
        if found is None:
            if not ws:
                time.sleep(0.35)
                continue
            page_u = ""
        else:
            host, port, page, ws = found
            _chrome_cdp_activate_page(host, port, page)
            page_u = str(page.get("url") or "").lower()

        if _minimax_cdp_pass_vstopite_gate(ws):
            steps.append("vstopite")
            try:
                gear2 = _chrome_cdp_runtime_evaluate(
                    ws,
                    _minimax_click_uvoz_iz_excela_js(
                        organisation_id=int(organisation_id) if organisation_id else None,
                        organisation_name=org_name,
                    ),
                    timeout_sec=8.0,
                ) or {}
                if not (isinstance(gear2, dict) and gear2.get("ok")):
                    firm_gate, _ = _minimax_cdp_wait_firm_in_navbar(
                        ws, organisation_name=org_name, timeout_sec=3.0
                    )
                    if firm_gate:
                        _chrome_cdp_navigate(ws, page_url, timeout_sec=15.0)
                time.sleep(1.0)
            except Exception:
                pass
            continue

        if page_u and "uvozpodatkov" not in page_u:
            try:
                gear2 = _chrome_cdp_runtime_evaluate(
                    ws,
                    _minimax_click_uvoz_iz_excela_js(
                        organisation_id=int(organisation_id) if organisation_id else None,
                        organisation_name=org_name,
                    ),
                    timeout_sec=8.0,
                ) or {}
                if not (isinstance(gear2, dict) and gear2.get("ok")):
                    firm_gate, _ = _minimax_cdp_wait_firm_in_navbar(
                        ws, organisation_name=org_name, timeout_sec=3.0
                    )
                    if firm_gate:
                        _chrome_cdp_navigate(ws, page_url, timeout_sec=15.0)
                    else:
                        last_err = "ni firme v navbarju pred Uvoz URL"
                time.sleep(0.9)
            except Exception as exc:
                last_err = str(exc)
            continue

        if not kn_done:
            try:
                sel = _chrome_cdp_runtime_evaluate(ws, select_js, timeout_sec=10.0) or {}
            except Exception as exc:
                last_err = str(exc)
                time.sleep(0.35)
                continue
            if isinstance(sel, dict) and (sel.get("has_form") or sel.get("ok")):
                steps.extend(str(s) for s in (sel.get("steps") or []) if s)
                kn_done = bool(sel.get("has_form"))
                if not kn_done:
                    time.sleep(0.7)
                    continue
                time.sleep(0.8)
            else:
                last_err = str((sel or {}).get("steps") or sel or "KN ni izbran")
                time.sleep(0.4)
                continue

        try:
            filled = _chrome_cdp_runtime_evaluate(ws, fill_js, timeout_sec=12.0)
        except Exception as exc:
            last_err = str(exc)
            time.sleep(0.35)
            continue
        if isinstance(filled, dict) and filled.get("reason") == "need_KN":
            kn_done = False
            time.sleep(0.35)
            continue
        if isinstance(filled, dict) and filled.get("ok"):
            steps.extend(str(s) for s in (filled.get("steps") or []) if s)
            time.sleep(0.5)
            try:
                _chrome_cdp_runtime_evaluate(ws, fill_js, timeout_sec=10.0)
            except Exception:
                pass
            if _chrome_cdp_set_file_input(ws, MINIMAX_WEB_UVOZ_FILE_INPUT, path):
                steps.append("datoteka")
            else:
                steps.append("datoteka: ročno")

            if click_import:
                try:
                    clicked = _chrome_cdp_runtime_evaluate(
                        ws, _minimax_uvoz_click_import_js(), timeout_sec=8.0
                    )
                    if isinstance(clicked, dict) and clicked.get("ok"):
                        steps.append("uvozi")
                    else:
                        steps.append("uvozi: ročno")
                except Exception as exc:
                    steps.append(f"uvozi: {exc}")
                ok_rep, rep_msg, rep = _minimax_uvoz_wait_report(
                    endpoints, timeout_sec=50.0, open_temeljnica=open_temeljnica
                )
                if rep.get("opened_temeljnica"):
                    steps.append("prikazi_temeljnico")
                tem_url = str((rep or {}).get("temelnica_url") or "").strip()
                msg = (
                    f"{'OK' if ok_rep else 'Napaka'} | {', '.join(tab_steps + steps)} | "
                    f"datum={date_sl} | opis={opis} | {path.name} | {rep_msg}"
                )
                if tem_url:
                    msg += f" | temelnica_url={tem_url}"
                log_info(f"minimax_uvoz_direct | {msg} | {page_url}")
                return ok_rep, msg

            msg = (
                f"Odprt uvoz + {', '.join(tab_steps + steps) or 'vpisano'} | "
                f"datum={date_sl} | opis={opis} | {path.name}"
            )
            log_info(f"minimax_uvoz_direct | {msg} | {page_url}")
            return True, msg
        if isinstance(filled, dict):
            last_err = str(filled.get("steps") or filled)
        time.sleep(0.35)

    return False, (
        f"Nov zavihek odprt, vpis ni uspel ({last_err or 'Podatki/KN / obrazec'}).\n"
        f"{page_url}\n"
        f"Datum: {date_sl} | opis: {opis} | {path.name}"
    )


def minimax_web_uvoz_fast_automation(
    *,
    xlsx_path: Path,
    yyyy: str,
    mm: str,
    organisation_id: Optional[int] = None,
    organisation_name: str = "",
    vrsta_temeljnice: str = MINIMAX_WEB_UVOZ_VRSTA_TEMELJNICE,
    click_import: bool = True,
    open_temeljnica: bool = True,
) -> Tuple[bool, str]:
    """Minimax debug CDP → UvozPodatkov → KN → IR → Excel (Arhiv 2.2.29 + Hitri zajem)."""
    return _minimax_uvoz_fill_in_user_chrome(
        xlsx_path=xlsx_path,
        yyyy=yyyy,
        mm=mm,
        organisation_id=organisation_id,
        organisation_name=organisation_name,
        vrsta_temeljnice=vrsta_temeljnice,
        click_import=click_import,
        open_temeljnica=open_temeljnica,
    )


def minimax_web_uvoz_fast_automation_threaded(
    *,
    on_done: Optional[Callable[[bool, str], None]] = None,
    **kwargs: Any,
) -> None:
    def work() -> None:
        ok, msg = False, ""
        try:
            ok, msg = minimax_web_uvoz_fast_automation(**kwargs)
        except Exception as exc:
            ok, msg = False, str(exc)
            log_error("minimax_web_uvoz_fast_automation_threaded", exc)
        if on_done is not None:
            try:
                on_done(ok, msg)
            except Exception as exc2:
                log_error("minimax_web_uvoz_fast on_done", exc2)

    threading.Thread(target=work, daemon=True).start()


def minimax_web_uvoz_webview2_automation(
    *,
    xlsx_path: Path,
    yyyy: str,
    mm: str,
    organisation_id: Optional[int] = None,
    organisation_name: str = "",
    click_import: bool = True,
    open_temeljnica: bool = True,
    on_log: Optional[Callable[[str], None]] = None,
) -> Tuple[bool, str]:
    """Hitri Minimax uvoz v WebView2 — firma → KN → IR → Excel → Uvozi → temeljnica."""
    from v2.minimax_uvoz_config import load_minimax_uvoz_config
    from v2.minimax_webview2 import MinimaxUvozWebView2Controller, WebView2Unavailable
    from v2.version_journal import APP_ROOT

    path = Path(xlsx_path).resolve()
    if not path.is_file():
        return False, f"Datoteka ne obstaja:\n{path}"
    cfg = load_minimax_uvoz_config()
    date_sl = last_day_of_month_sl(yyyy, mm)
    opis = minimax_web_uvoz_opis(yyyy, mm)
    port = int(cfg.get("remote_debugging_port") or 9333)
    org_name = (organisation_name or "").strip()
    if organisation_id and not org_name:
        org_name = (lookup_minimax_org_name(organisation_id) or "").strip()
    # Začni na Moje org / Zacetek — uvoz šele po HARD firimi v hostu
    start_url = MINIMAX_WEB_ZACETEK_URL
    uvoz_url = minimax_web_uvoz_url(organisation_id)
    log = on_log or (lambda m: log_info(f"minimax_uvoz_webview2 | {m}"))

    login_user, login_pass = "", ""
    try:
        login_user, login_pass = load_minimax_web_login_credentials_from_settings()
    except Exception:
        login_user, login_pass = "", ""

    ctrl = MinimaxUvozWebView2Controller(APP_ROOT)
    try:
        result = ctrl.import_knjizbe(
            xlsx_path=path,
            date_sl=date_sl,
            opis=opis,
            organisation_id=organisation_id,
            organisation_name=org_name,
            click_import=bool(click_import),
            open_temeljnica=bool(open_temeljnica),
            remote_debugging_port=port,
            start_url=start_url,
            login_username=login_user or "",
            login_password=login_pass or "",
            log=log,
        )
    except WebView2Unavailable as exc:
        return False, f"WebView2 ni na voljo:\n{exc}"
    except Exception as exc:
        log_error("minimax_web_uvoz_webview2_automation", exc)
        return False, str(exc)

    steps = ", ".join(str(s) for s in (result.get("steps") or []))
    org = result.get("organisation") or ""
    msg = (
        f"WebView2 OK | {steps} | datum={date_sl} | opis={opis} | {path.name}"
        + (f" | org={org}" if org else "")
    )
    log_info(f"minimax_uvoz_webview2 | {msg} | {uvoz_url}")
    return True, msg


def minimax_web_uvoz_webview2_automation_threaded(
    *,
    on_done: Optional[Callable[[bool, str], None]] = None,
    **kwargs: Any,
) -> None:
    def work() -> None:
        ok, msg = False, ""
        try:
            ok, msg = minimax_web_uvoz_webview2_automation(**kwargs)
        except Exception as exc:
            ok, msg = False, str(exc)
            log_error("minimax_web_uvoz_webview2_automation_threaded", exc)
        if on_done is not None:
            try:
                on_done(ok, msg)
            except Exception as exc2:
                log_error("minimax_web_uvoz_webview2 on_done", exc2)

    threading.Thread(target=work, daemon=True).start()


