    def _report_callback_exception(self, exc, val, tb) -> None:  # type: ignore[override]
        err = val if isinstance(val, BaseException) else Exception(str(val))
        log_error("Tk callback", err)
        messagebox.showerror("Napaka", f"Prišlo je do napake.\n\n{err}\n\nLog: {self._display_path(LOG_FILE)}")

    def _safe_call(self, fn, name: str):
        def wrapped(*args, **kwargs):
            try:
                return fn(*args, **kwargs)
            except Exception as exc:
                log_error(name, exc)
                messagebox.showerror("Napaka", f"Napaka v {name}:\n{exc}\n\nLog: {self._display_path(LOG_FILE)}")
                return None
        return wrapped


