    def _load_minimax_settings_from_disk(self) -> None:
        try:
            if not SETTINGS_FILE.exists():
                return
            data = json.loads(SETTINGS_FILE.read_text(encoding="utf-8"))
            if not isinstance(data, dict):
                return
            self.minimax_api_base.set(str(data.get("minimax_api_base") or MINIMAX_API_BASE_DEFAULT))
            self.minimax_auth_url.set(str(data.get("minimax_auth_url") or MINIMAX_AUTH_URL_DEFAULT))
            self.minimax_scope.set(str(data.get("minimax_scope") or MINIMAX_SCOPE_DEFAULT))
            self.minimax_client_id.set(str(data.get("minimax_client_id") or ""))
            self.minimax_client_secret.set(str(data.get("minimax_client_secret") or ""))
            self.minimax_api_username.set(str(data.get("minimax_api_username") or ""))
            self.minimax_api_password.set(str(data.get("minimax_api_password") or ""))
            self.minimax_web_username.set(str(data.get("minimax_web_username") or ""))
            self.minimax_web_password.set(str(data.get("minimax_web_password") or ""))
            self.minimax_org_id.set(str(data.get("minimax_org_id") or ""))
            doc_type = parse_minimax_document_type_api(
                str(data.get("minimax_document_type") or MINIMAX_DOCUMENT_TYPE_DEFAULT)
            )
            self.minimax_document_type.set(doc_type)
            self.minimax_customer_id.set(str(data.get("minimax_customer_id") or ""))
            self.minimax_payment_method_code.set(str(data.get("minimax_payment_method_code") or MINIMAX_PAYMENT_METHOD_CODE_DEFAULT))
            pm_id_raw = data.get("minimax_payment_method_id")
            try:
                pm_id = int(pm_id_raw) if pm_id_raw not in (None, "") else MINIMAX_PAYMENT_METHOD_ID_DEFAULT
            except (TypeError, ValueError):
                pm_id = MINIMAX_PAYMENT_METHOD_ID_DEFAULT
            if pm_id <= 0:
                pm_id = MINIMAX_PAYMENT_METHOD_ID_DEFAULT
            self.minimax_payment_method_id.set(str(pm_id))
            self.minimax_payment_method_label.set(minimax_payment_method_label_for_id(pm_id))
            self.minimax_vat_accounting_type_s.set(str(data.get("minimax_vat_accounting_type_s") or MINIMAX_VAT_ACCOUNTING_TYPE_S_DEFAULT))
            self.minimax_vat_accounting_type_z.set(str(data.get("minimax_vat_accounting_type_z") or MINIMAX_VAT_ACCOUNTING_TYPE_Z_DEFAULT))
            self.minimax_vat_accounting_type_n.set(str(data.get("minimax_vat_accounting_type_n") or MINIMAX_VAT_ACCOUNTING_TYPE_N_DEFAULT))
            self.minimax_vat_rate_22_search.set(str(data.get("minimax_vat_rate_22_search") or MINIMAX_VAT_RATE_22_SEARCH_DEFAULT))
            self.minimax_vat_rate_95_search.set(str(data.get("minimax_vat_rate_95_search") or MINIMAX_VAT_RATE_95_SEARCH_DEFAULT))
            self.minimax_vat_rate_0_search.set(str(data.get("minimax_vat_rate_0_search") or MINIMAX_VAT_RATE_0_SEARCH_DEFAULT))
            if "minimax_ddv_zavezanec" in data:
                self.minimax_ddv_zavezanec.set(bool(data.get("minimax_ddv_zavezanec")))
            else:
                self.minimax_ddv_zavezanec.set(MINIMAX_DDV_ZAVEZANEC_DEFAULT)
            load_kontiranje_from_settings_data(data)
            self._try_merge_oauth_settings_fallback()
        except Exception as exc:
            log_error("_load_minimax_settings_from_disk", exc)

    def _try_merge_oauth_settings_fallback(self) -> bool:
        if not self._missing_oauth_fields():
            return False
        var_by_key = {
            "minimax_client_id": self.minimax_client_id,
            "minimax_client_secret": self.minimax_client_secret,
            "minimax_api_username": self.minimax_api_username,
            "minimax_api_password": self.minimax_api_password,
            "minimax_web_username": self.minimax_web_username,
            "minimax_web_password": self.minimax_web_password,
        }
        merged = False
        for candidate in minimax_oauth_fallback_settings_paths(SETTINGS_FILE):
            if not candidate.is_file():
                continue
            try:
                data = json.loads(candidate.read_text(encoding="utf-8"))
            except Exception as exc:
                log_error("_try_merge_oauth_settings_fallback read", exc)
                continue
            if not isinstance(data, dict) or not minimax_settings_has_oauth(data):
                continue
            for key, var in var_by_key.items():
                incoming = str(data.get(key) or "").strip()
                if incoming and not var.get().strip():
                    var.set(incoming)
                    merged = True
            if merged:
                self._save_minimax_settings_to_disk(show_message=False)
                log_info(
                    "OAuth nastavitve združene iz "
                    f"{candidate} -> {SETTINGS_FILE}"
                )
                break
        return merged

    def _load_ui_settings_from_disk(self) -> None:
        try:
            if not UI_SETTINGS_FILE.exists():
                return
            data = json.loads(UI_SETTINGS_FILE.read_text(encoding="utf-8"))
            if not isinstance(data, dict):
                return
            self._saved_company_zst = str(data.get("selected_company_zst") or "").strip()
            search = str(data.get("company_search") or "").strip()
            if search:
                self.company_search.set(search)
            if bool(data.get("filter_evidenca_davcnih")):
                self.filter_evidenca_davcnih.set(True)
            raw_zip = data.get("zip_selection_by_root")
            if isinstance(raw_zip, dict):
                self._zip_selection_by_root = {
                    str(k): {str(z): bool(v) for z, v in (zv or {}).items()}
                    for k, zv in raw_zip.items()
                    if isinstance(zv, dict)
                }
            py = str(data.get("period_yyyy") or "").strip()
            pm = str(data.get("period_mm") or "").strip()
            if re.fullmatch(r"\d{4}", py):
                self._saved_period_yyyy = py
            if re.fullmatch(r"\d{1,2}", pm):
                self._saved_period_mm = f"{int(pm):02d}"
            try:
                self._saved_active_view_tab = int(data.get("active_view_tab") or 0)
            except Exception:
                self._saved_active_view_tab = 0
            try:
                self._saved_export_tab = int(data.get("export_tab") or 0)
            except Exception:
                self._saved_export_tab = 0
            raw_uvoz = data.get("minimax_uvoz_by_zst")
            if isinstance(raw_uvoz, dict):
                self._minimax_uvoz_by_zst = {
                    str(k): dict(v)
                    for k, v in raw_uvoz.items()
                    if isinstance(v, dict) and str(k).strip()
                }
            # poti: samo StringVar (brez Path.exists) — obnova po izboru firme
            self._saved_paths = data.get("paths") if isinstance(data.get("paths"), dict) else {}
        except Exception as exc:
            log_error("_load_ui_settings_from_disk", exc)

    def _save_zip_selection_settings(self) -> None:
        root = self._analysis_source_root(self._to_path(self.root_dir.get()))
        key = str(root.resolve())
        self._zip_selection_by_root[key] = dict(self._zip_enabled)
        self._save_ui_settings_to_disk()

    def _ensure_zip_selection_loaded(self) -> None:
        if not self.include_zips.get():
            self._zip_enabled = {}
            return
        root = self._analysis_source_root(self._to_path(self.root_dir.get()))
        if not root.is_dir():
            self._zip_enabled = {}
            return
        csv_name = (self.csv_name.get() or "blagajne.csv").strip() or "blagajne.csv"
        ctx_year = infer_blagajna_context_year(root)
        probes = scan_blagajna_zips(root, csv_name, context_yyyy=ctx_year)
        if not probes:
            self._zip_enabled = {}
            return
        key = str(root.resolve())
        saved = self._zip_selection_by_root.get(key, {})
        self._zip_enabled = default_zip_enabled_map(probes, saved)

    def _get_enabled_zip_names(self) -> List[str]:
        if not self.include_zips.get():
            return []
        # Ne kliči _ensure_zip_selection_loaded() tukaj — sicer pobriše
        # _ensure_zip_enabled_for_period pred branjem CSV.
        if not self._zip_enabled:
            self._ensure_zip_selection_loaded()
        return [name for name, on in self._zip_enabled.items() if on]

    def _ensure_zip_enabled_for_period(self, yyyy: str, mm: str) -> None:
        """Ob uvozu vklopi ZIP za izbrano obdobje (Leto/Mesec)."""
        if not self.include_zips.get():
            return
        self._ensure_zip_selection_loaded()
        mm_norm = f"{int(mm):02d}"
        zip_name = f"{yyyy}-{mm_norm}.zip"
        root = self._analysis_source_root(self._to_path(self.root_dir.get()))
        if not root.is_dir():
            return
        for zp in list_blagajna_zip_files(root):
            if zp.name == zip_name:
                self._zip_enabled[zip_name] = True
                key = str(root.resolve())
                saved = dict(self._zip_selection_by_root.get(key, {}))
                saved[zip_name] = True
                self._zip_selection_by_root[key] = saved
                log_info(f"_ensure_zip_enabled_for_period | vključen {zip_name}")
                break

    def _zip_selection_summary(self) -> str:
        if not self.include_zips.get():
            return "ZIP izklopljen"
        self._ensure_zip_selection_loaded()
        root = self._analysis_source_root(self._to_path(self.root_dir.get()))
        total = len(list_blagajna_zip_files(root))
        enabled = len(self._get_enabled_zip_names())
        if total == 0:
            return "ZIP: ni datotek"
        return f"ZIP: {enabled}/{total} izbranih"

    def _open_zip_packages_dialog(self) -> None:
        if not self.include_zips.get():
            messagebox.showinfo(
                "ZIP paketi",
                "Vklopi checkbox ZIP zgoraj, nato izberi pakete.",
                parent=self,
            )
            return
        self._ensure_zip_selection_loaded()
        ZipPackagesDialog(self)

    def _save_ui_settings_to_disk(self) -> None:
        """Samo disk — brez CDP/analize (sicer zmrzne UI)."""
        try:
            ym = self._get_period_ym_from_combos()
            yyyy = (ym[0] if ym else (self.period_year.get() or "").strip())
            mm = (ym[1] if ym else (self.period_month.get() or "").strip())
            active_tab = int(getattr(self, "_v21_active_view_tab", self._saved_active_view_tab) or 0)
            export_tab = self._saved_export_tab
            try:
                bar = getattr(self, "_v21_export_tab_bar", None)
                if bar is not None and hasattr(bar, "active_index"):
                    export_tab = int(bar.active_index())
            except Exception:
                pass
            payload = {
                "selected_company_zst": (
                    str(self.selected_company.get("Zšt", "")).strip()
                    if self.selected_company
                    else (self._saved_company_zst or "")
                ),
                "company_search": (self.company_search.get() or "").strip(),
                "filter_evidenca_davcnih": bool(self.filter_evidenca_davcnih.get()),
                "zip_selection_by_root": self._zip_selection_by_root,
                "period_yyyy": str(yyyy or "").strip(),
                "period_mm": str(mm or "").strip(),
                "active_view_tab": active_tab,
                "export_tab": export_tab,
                "minimax_uvoz_by_zst": self._minimax_uvoz_by_zst,
                "paths": {
                    "root_dir": (self.root_dir.get() or "").strip(),
                    "out_dir": (self.out_dir.get() or "").strip(),
                    "out_file": (self.out_file.get() or "").strip(),
                    "sheet_name": (self.sheet_name.get() or "").strip(),
                    "csv_name": (self.csv_name.get() or "").strip(),
                    "template_path": (self.template_path.get() or "").strip(),
                },
            }
            UI_SETTINGS_FILE.parent.mkdir(parents=True, exist_ok=True)
            UI_SETTINGS_FILE.write_text(
                json.dumps(payload, ensure_ascii=False, indent=2),
                encoding="utf-8",
            )
        except Exception as exc:
            log_error("_save_ui_settings_to_disk", exc)

    def _on_app_close(self) -> None:
        """Shrani zadnje stanje (firma, obdobje, poti, uvoz) in zapri — brez CDP."""
        try:
            self._save_ui_settings_to_disk()
        except Exception as exc:
            log_error("_on_app_close save", exc)
        try:
            self.destroy()
        except Exception:
            pass

    def _restore_period_from_settings(self) -> None:
        yyyy = (self._saved_period_yyyy or "").strip()
        mm = (self._saved_period_mm or "").strip()
        if not (re.fullmatch(r"\d{4}", yyyy) and re.fullmatch(r"\d{1,2}", mm)):
            return
        try:
            self._period_sync_guard = True
            self.period_year.set(yyyy)
            self.period_month.set(f"{int(mm):02d}")
        finally:
            self._period_sync_guard = False

    def _warmup_chrome_sessions_cache(self) -> None:
        """Ob zagonu app: iz aktivnega Chrome shrani Minimax/eDavki/eVEM/AJPES seje v cache."""

        def work() -> None:
            try:
                from v2.chrome_session_sync import sync_all_from_chrome

                summary = sync_all_from_chrome(
                    log=lambda m: log_info(f"session_warmup | {m}")
                )
                parts = []
                for key, info in (summary.get("services") or {}).items():
                    if info.get("ok"):
                        parts.append(f"{key}:{info.get('cookies', 0)}")
                    elif info.get("cache_ok"):
                        parts.append(f"{key}:cache")
                log_info(
                    "session_warmup | "
                    + (", ".join(parts) if parts else "ni aktivnega Chrome CDP")
                    + f" | saved={summary.get('saved', 0)}"
                )
                try:
                    from v2 import portal_bridge

                    if portal_bridge.endm_available():
                        mx = portal_bridge.resolve_portal(
                            "minimax",
                            log=lambda m: log_info(f"portal_bridge | {m}"),
                        )
                        log_info(
                            "portal_bridge | minimax motor="
                            + portal_bridge.engine_status_text(mx)
                        )
                except Exception as pexc:
                    log_error("session_warmup portal_bridge", pexc)
            except Exception as exc:
                log_error("_warmup_chrome_sessions_cache", exc)

        threading.Thread(target=work, daemon=True, name="ChromeSessionWarmup").start()

    def _restore_session_after_startup(self) -> None:
        """Obnovi zadnjo sejo: obdobje, firma, zavihki, poti, tiha analiza (brez CDP)."""
        try:
            self._restore_period_from_settings()
        except Exception as exc:
            log_error("_restore_session_after_startup period", exc)
        try:
            if not self.selected_company and (self._saved_company_zst or "").strip():
                self._restore_selected_company_from_settings()
            elif self.selected_company:
                # ponovno označi firmo v drevesu (filter Ev. lahko prekrije)
                self._restore_selected_company_from_settings()
        except Exception as exc:
            log_error("_restore_session_after_startup company", exc)
        try:
            paths = getattr(self, "_saved_paths", None) or {}
            if isinstance(paths, dict):
                for key, var in (
                    ("out_file", self.out_file),
                    ("sheet_name", self.sheet_name),
                    ("csv_name", self.csv_name),
                    ("template_path", self.template_path),
                ):
                    val = str(paths.get(key) or "").strip()
                    if val:
                        var.set(val)
                # root/out samo če se ujemata z Zšt izbrane firme (sicer pusti apply_company)
                zst = ""
                if self.selected_company:
                    zst = format_zst_folder(self.selected_company.get("Zšt", ""))
                root_s = str(paths.get("root_dir") or "").strip()
                out_s = str(paths.get("out_dir") or "").strip()
                if zst and root_s and (f"\\{zst}\\" in root_s or root_s.endswith(f"\\{zst}") or f"/{zst}/" in root_s):
                    self.root_dir.set(root_s)
                if zst and out_s and (f"\\{zst}\\" in out_s or out_s.endswith(f"\\{zst}") or f"/{zst}/" in out_s):
                    self.out_dir.set(out_s)
        except Exception as exc:
            log_error("_restore_session_after_startup paths", exc)
        try:
            tab = int(self._saved_active_view_tab or 0)
            if hasattr(self, "_select_v21_view_tab"):
                self._select_v21_view_tab(tab)
        except Exception as exc:
            log_error("_restore_session_after_startup tab", exc)
        try:
            bar = getattr(self, "_v21_export_tab_bar", None)
            if bar is not None and hasattr(bar, "select"):
                bar.select(int(self._saved_export_tab or 0), fire=True)
        except Exception as exc:
            log_error("_restore_session_after_startup export_tab", exc)
        try:
            self._refresh_minimax_uvoz_status_for_selected()
        except Exception:
            pass
        # Tiha analiza — napolni drevo (Skupaj vse), brez dialogov; po UI paint
        if self.selected_company and self._get_period_ym_from_combos():
            self._update_minimax_status("obnavljam zadnjo sejo …")
            self.after(200, self._safe_call(self._restore_session_analyze, "_restore_session_analyze"))

    def _restore_session_analyze(self) -> None:
        """Naloži podatke za shranjeno firmo/obdobje (tiho, brez CDP)."""
        if not self.selected_company:
            return
        root = self._to_path(self.root_dir.get())
        if not root.is_dir():
            self._update_minimax_status("seja: mapa firme ni dosegljiva — klikni Uvozi podatke")
            return
        self._session_restore_silent = True
        try:
            self._analyze()
            ym = self._get_period_ym_from_combos()
            name = (self.selected_company.get("NAZIV") or "").strip()
            short = name.split()[0] if name else "?"
            if ym:
                self._update_minimax_status(f"seja: {short} {ym[1]}.{ym[0]} — drevo obnovljeno")
            else:
                self._update_minimax_status(f"seja: {short} — drevo obnovljeno")
            self._refresh_minimax_uvoz_status_for_selected()
        except Exception as exc:
            log_error("_restore_session_analyze", exc)
            self._update_minimax_status(f"seja: analiza ni uspela — {exc}")
        finally:
            self._session_restore_silent = False

    def _record_minimax_uvoz_result(
        self,
        *,
        ok: bool,
        yyyy: str,
        mm: str,
        path: Path,
        date_sl: str,
        opis: str,
        msg: str,
        organisation_id: Optional[int] = None,
        organisation_name: str = "",
    ) -> None:
        zst = ""
        if self.selected_company:
            zst = str(self.selected_company.get("Zšt", "")).strip()
        if not zst:
            zst = (self._saved_company_zst or "").strip()
        if not zst:
            return
        tem_url = ""
        m = re.search(r"temelnica_url=(https?://\S+)", msg or "")
        if m:
            tem_url = m.group(1).rstrip(")|,;")
        entry = {
            "ok": bool(ok),
            "yyyy": str(yyyy),
            "mm": f"{int(mm):02d}" if str(mm).isdigit() else str(mm),
            "date_sl": date_sl,
            "opis": opis,
            "file": path.name,
            "file_path": str(path),
            "at": datetime.now().isoformat(timespec="seconds"),
            "org_id": organisation_id,
            "org_name": organisation_name
            or ((self.selected_company or {}).get("NAZIV") or "").strip(),
            "temelnica_url": tem_url
            or str((self._minimax_uvoz_by_zst.get(zst) or {}).get("temelnica_url") or ""),
            "msg": (msg or "")[:400],
        }
        self._minimax_uvoz_by_zst[zst] = entry
        self._save_ui_settings_to_disk()
        try:
            # Osveži stolpec «Datum in čas pošiljanja» za uvožen mesec.
            self._refresh_tree()
        except Exception:
            pass

    def _refresh_minimax_uvoz_status_for_selected(self) -> None:
        if not self.selected_company:
            return
        zst = str(self.selected_company.get("Zšt", "")).strip()
        entry = self._minimax_uvoz_by_zst.get(zst) if zst else None
        if not isinstance(entry, dict) or not entry:
            return
        name = (entry.get("org_name") or self.selected_company.get("NAZIV") or "").strip()
        short = name.split()[0] if name else zst
        ym = f"{entry.get('mm') or '?'}.{entry.get('yyyy') or '?'}"
        flag = "OK" if entry.get("ok") else "napaka"
        file_name = entry.get("file") or ""
        opis = entry.get("opis") or ""
        self._update_minimax_status(
            f"{short} | uvoz {ym} {flag} · {file_name}"
            + (f" · {opis}" if opis else "")
        )

    def _save_minimax_settings_to_disk(self, show_message: bool = False) -> None:
        payload = self._settings_payload()
        SETTINGS_FILE.parent.mkdir(parents=True, exist_ok=True)
        if SETTINGS_FILE.exists():
            try:
                existing = json.loads(SETTINGS_FILE.read_text(encoding="utf-8"))
                if isinstance(existing, dict):
                    merged = dict(existing)
                    merged.update(payload)
                    payload = merged
            except Exception as exc:
                log_error("_save_minimax_settings_to_disk merge", exc)
        SETTINGS_FILE.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        if show_message:
            messagebox.showinfo("Nastavitve", f"Nastavitve shranjene v:\n{self._display_path(SETTINGS_FILE)}")

    def _mask_token(self, token: str) -> str:
        token = (token or "").strip()
        if len(token) <= 10:
            return token or "(prazen)"
        return f"{token[:6]}...{token[-4:]}"

    def _update_minimax_status(self, extra: str = "") -> None:
        org = self.minimax_org_id.get().strip() or "?"
        token_part = self._mask_token(self.minimax_access_token) if self.minimax_access_token else "ni tokena"
        ddv_part = "DDV zavezanec" if self._is_ddv_zavezanec() else "NI DDV zavezanec"
        base = f"Minimax: org={org} | {ddv_part} | token={token_part}"
        if extra:
            base += f" | {extra}"
        self.minimax_status.set(base)

    def _snapshot_main_window(self) -> None:
        """Zapomni geometrijo pred dialogi / odpiranjem brskalnika (da se forma ne skrči)."""
        try:
            self.update_idletasks()
            self._geom_before_api = self.winfo_geometry()
            self._state_before_api = str(self.state())
        except Exception:
            self._geom_before_api = ""
            self._state_before_api = ""

    def _restore_main_window_after_api(self) -> None:
        """Po API dialogu povrni velikost/stanje glavnega okna."""

        def _do() -> None:
            try:
                st = str(getattr(self, "_state_before_api", "") or "")
                geom = str(getattr(self, "_geom_before_api", "") or "")
                self.deiconify()
                if st == "zoomed":
                    try:
                        self.state("zoomed")
                    except tk.TclError:
                        if geom:
                            self.geometry(geom)
                elif geom:
                    self.geometry(geom)
                self.lift()
                try:
                    self.attributes("-topmost", True)
                    self.after(180, lambda: self.attributes("-topmost", False))
                except tk.TclError:
                    pass
            except Exception as exc:
                log_error("_restore_main_window_after_api", exc)

        try:
            self.after(0, _do)
            self.after(250, _do)
        except Exception:
            _do()

    def _get_minimax_document_type(self) -> str:
        cb = self._minimax_document_type_cb
        raw = ""
        if cb is not None:
            try:
                idx = cb.current()
                if idx >= 0 and idx < len(MINIMAX_DOCUMENT_TYPE_OPTIONS):
                    raw = MINIMAX_DOCUMENT_TYPE_OPTIONS[idx]
                if not raw:
                    raw = cb.get().strip()
            except tk.TclError:
                pass
        if not raw:
            raw = self.minimax_document_type.get().strip()
        return parse_minimax_document_type_api(raw)

    def _is_ddv_zavezanec(self) -> bool:
        return bool(self.minimax_ddv_zavezanec.get())

    def _on_ddv_zavezanec_toggle(self) -> None:
        self._save_minimax_settings_to_disk(show_message=False)
        self._update_minimax_status("nastavitev DDV zavezanec shranjena")

    def _sync_minimax_document_type_display(self, *_args, save: bool = False) -> None:
        api = self._get_minimax_document_type()
        if self.minimax_document_type.get() != api:
            self.minimax_document_type.set(api)
        cb = self._minimax_document_type_cb
        if cb is not None:
            try:
                cb.set(api)
            except tk.TclError:
                pass
        label = MINIMAX_DOCUMENT_TYPE_LABELS.get(api, api)
        # Excel DDV stolpec 'Knjiga' je VEDNO 'IR' (za vse DocumentType: IZT, IRI, IRS, AVA).
        self.minimax_document_type_hint.set(f"Izbrano: {api} — {label.split(' - ', 1)[-1]}  →  Excel Knjiga: IR")
        if save:
            self._save_minimax_settings_to_disk(show_message=False)

    def _get_placilni_konto(self) -> str:
        label = self.minimax_payment_method_label.get().strip()
        konto = resolve_placilo_konto(label)
        if not konto:
            raise ValueError(
                f"Za način plačila «{label}» ni nastavljen konto.\n"
                "Dvojni klik na «Način plačila» → vpiši konto (npr. 1000 za gotovino)."
            )
        return konto

    def _refresh_vrsta_prodaje_combo(self) -> None:
        labels = list(VRSTA_PRODAJE_LABELS)
        if self._vrsta_prodaje_cb is not None:
            self._vrsta_prodaje_cb.configure(values=labels)
        cur = self.vrsta_prodaje.get().strip()
        if cur not in labels:
            if labels:
                self.vrsta_prodaje.set(labels[0])

    def _on_kontiranje_saved(self) -> None:
        self._refresh_vrsta_prodaje_combo()
        self._save_minimax_settings_to_disk(show_message=False)

    def _open_kontiranje_placila_editor(self) -> None:
        KontiranjeEditorDialog(self, mode="placila", on_save=self._on_kontiranje_saved)

    def _open_kontiranje_prihodkov_editor(self) -> None:
        KontiranjeEditorDialog(self, mode="prihodki", on_save=self._on_kontiranje_saved)

    def _get_minimax_payment_method_id(self) -> int:
        label = self.minimax_payment_method_label.get().strip()
        if label:
            mapped = self._minimax_payment_method_label_to_id.get(label)
            if mapped is not None:
                return mapped
            from_label = minimax_payment_method_id_from_label(label)
            if from_label is not None:
                return from_label
        raw = (self.minimax_payment_method_id.get() or "").strip()
        try:
            pm_id = int(raw) if raw else MINIMAX_PAYMENT_METHOD_ID_DEFAULT
        except ValueError:
            pm_id = MINIMAX_PAYMENT_METHOD_ID_DEFAULT
        return pm_id if pm_id > 0 else MINIMAX_PAYMENT_METHOD_ID_DEFAULT

    def _sync_minimax_payment_method_from_label(self, *_args: Any) -> None:
        if self._pm_sync_guard:
            return
        pm_id = self._get_minimax_payment_method_id()
        new_id = str(pm_id)
        if (self.minimax_payment_method_id.get() or "").strip() != new_id:
            self.minimax_payment_method_id.set(new_id)

    def _apply_minimax_payment_method_options(
        self,
        labels: List[str],
        label_to_id: Dict[str, int],
        *,
        select_id: Optional[int] = None,
    ) -> None:
        self._minimax_payment_method_label_to_id = dict(label_to_id)
        if self._minimax_payment_method_cb is not None:
            self._minimax_payment_method_cb.configure(values=labels)
        target_id = select_id if select_id is not None else self._get_minimax_payment_method_id()
        if target_id <= 0:
            target_id = MINIMAX_PAYMENT_METHOD_ID_DEFAULT
        label, target_id = pick_payment_method_label_for_id(label_to_id, target_id, prefer_typ="G")
        self._pm_sync_guard = True
        try:
            self.minimax_payment_method_label.set(label)
            self.minimax_payment_method_id.set(str(target_id))
        finally:
            self._pm_sync_guard = False
        self._sync_minimax_payment_method_combobox_display()

    def _sync_minimax_payment_method_combobox_display(self) -> None:
        cb = self._minimax_payment_method_cb
        if cb is None or self._pm_sync_guard:
            return
        label = self.minimax_payment_method_label.get().strip()
        values = list(self._minimax_payment_method_label_to_id.keys())
        if label and label not in values:
            values = [label] + values
        try:
            current_values = tuple(cb.cget("values") or ())
        except tk.TclError:
            current_values = ()
        if tuple(values) != current_values:
            cb.configure(values=values)
        if label:
            try:
                if cb.get().strip() != label:
                    self._pm_sync_guard = True
                    try:
                        cb.set(label)
                    finally:
                        self._pm_sync_guard = False
            except tk.TclError:
                pass
        self._tint_combobox(cb)

    def _on_minimax_payment_method_selected(self) -> None:
        self._sync_minimax_payment_method_combobox_display()
        self._save_minimax_settings_to_disk(show_message=False)

    def _load_payment_methods_on_startup(self) -> None:
        fb_labels, fb_map = minimax_payment_method_fallback_options()
        self._apply_minimax_payment_method_options(fb_labels, fb_map)
        if not self.minimax_access_token:
            return
        try:
            api_base = self.minimax_api_base.get().strip() or MINIMAX_API_BASE_DEFAULT
            org_raw = self.minimax_org_id.get().strip()
            if not org_raw:
                return
            organisation_id = int(org_raw)
            labels, label_to_id = minimax_load_payment_method_options(
                api_base, self.minimax_access_token, organisation_id
            )
            self._apply_minimax_payment_method_options(
                labels, label_to_id, select_id=self._get_minimax_payment_method_id()
            )
        except Exception as exc:
            log_error("_load_payment_methods_on_startup", exc)

    def _refresh_minimax_payment_methods(self) -> None:
        try:
            api_base, organisation_id, token = self._ensure_minimax_session()
            labels, label_to_id = minimax_load_payment_method_options(
                api_base, token, organisation_id, refresh=True
            )
            self._apply_minimax_payment_method_options(
                labels, label_to_id, select_id=self._get_minimax_payment_method_id()
            )
            self._save_minimax_settings_to_disk(show_message=False)
            self._update_minimax_status(f"načini plačila: {len(labels)}")
            messagebox.showinfo(
                "Načini plačila",
                f"Osveženo {len(labels)} načinov plačila (org {organisation_id}).",
            )
        except Exception as exc:
            log_error("_refresh_minimax_payment_methods", exc)
            messagebox.showerror("Načini plačila", f"Osvežitev ni uspela:\n{exc}")

    def _get_minimax_ddv_knjiga(self) -> str:
        return resolve_ddv_knjiga_for_document_type(self._get_minimax_document_type())

    def _missing_oauth_fields(self) -> List[str]:
        required = [
            ("Client ID", self.minimax_client_id.get().strip()),
            ("Client secret", self.minimax_client_secret.get().strip()),
            ("API username", self.minimax_api_username.get().strip()),
            ("API password", self.minimax_api_password.get().strip()),
        ]
        return [label for label, value in required if not value]

    def _open_oauth_settings_dialog(self) -> None:
        win = tk.Toplevel(self)
        win.title("Nastavi OAuth / Minimax")
        win.geometry("860x620")
        win.transient(self)
        win.grab_set()

        fields = [
            ("Minimax API URL", self.minimax_api_base, False),
            ("Scope", self.minimax_scope, False),
            ("Client ID", self.minimax_client_id, False),
            ("Client secret", self.minimax_client_secret, True),
            ("API username", self.minimax_api_username, False),
            ("API password", self.minimax_api_password, True),
            ("Web username (uvoz; prazno=API)", self.minimax_web_username, False),
            ("Web password (uvoz; prazno=API)", self.minimax_web_password, True),
            ("Org ID", self.minimax_org_id, False),
            ("Customer ID (IRS/IRI/AVA)", self.minimax_customer_id, False),
            ("Način plačila (koda; prazno=Gotovina)", self.minimax_payment_method_code, False),
            ("DDV tip S", self.minimax_vat_accounting_type_s, False),
            ("DDV tip Z", self.minimax_vat_accounting_type_z, False),
            ("DDV tip N", self.minimax_vat_accounting_type_n, False),
            ("VAT rate lookup 22%", self.minimax_vat_rate_22_search, False),
            ("VAT rate lookup 9,5%", self.minimax_vat_rate_95_search, False),
            ("VAT rate lookup 0%", self.minimax_vat_rate_0_search, False),
        ]

        show_secrets = tk.BooleanVar(value=False)
        secret_entries: List[tk.Entry] = []

        body = ttk.Frame(win, padding=12)
        body.pack(fill="both", expand=True)
        body.columnconfigure(1, weight=1)

        for row_i, (label, var, is_secret) in enumerate(fields):
            ttk.Label(body, text=label + ":").grid(row=row_i, column=0, sticky="w", padx=(0, 8), pady=5)
            entry = self._yellow_entry(body, textvariable=var, show="*" if is_secret else "")
            entry.grid(row=row_i, column=1, sticky="ew", pady=5)
            if is_secret:
                secret_entries.append(entry)

        doc_row = len(fields)
